// ---------- упражнения в тетрадь: l — урок (7 — повторение), st — сложность 1–5 (особые жанры — поле os), obr — образец ----------
const CLASSIC=[
// Урок 1
 {n:1,l:1,st:1,task:'Прочитать словосочетания. 1) Выписать прилагательные, образованные от существительных. Рядом записать существительное, от которого образовано прилагательное, и обозначить суффикс. 2) Распределить выписанные прилагательные на два столбика: с одной н и с двумя н. 3) Найти два прилагательных, которые не образованы от существительных, и объяснить, почему в них одна н. 4) Объяснить, почему в словах медный и книжная одна н, хотя в них тоже есть суффикс -н-.',
  obr:'Соловьиная трель; осенний лес. → Соловьиная ← соловей, суффикс -ин- — одна н. Осенний ← осень: основа на н (осен-) + суффикс -н- — две н.',
  body:'Овсяное печенье, журавлиный клин, пустынный пляж, лекционный зал, клятвенное обещание, ледяная горка, барабанная дробь, медный провод, юный шахматист, тополиный пух, лекарственные травы, жестяная банка, ураганный ветер, чугунная ограда, телефонный разговор, пчелиный рой, костяной гребень, зелёный светофор, книжная полка, мужественный поступок.',
  key:'1), 2) Одна н: овсяное (овёс, -ян-), журавлиный (журавль, -ин-), ледяная (лёд, -ян-), тополиный (тополь, -ин-), жестяная (жесть, -ян-), пчелиный (пчела, -ин-), костяной (кость, -ян-), медный (медь, -н-), книжная (книга, -н-).<br>Две н: пустынный (пустыня: основа пустын- + суффикс -н-), барабанная (барабан + -н-), ураганный (ураган + -н-), чугунная (чугун + -н-), телефонный (телефон + -н-) — основа на н + суффикс -н-; лекционный (лекция, -онн-), клятвенное (клятва, -енн-), лекарственные (лекарство, -енн-), мужественный (мужество, -енн-) — суффиксы -онн-, -енн-.<br>3) Юный, зелёный — не образованы от существительных: суффикса -н- в них нет, н входит в корень (юн-) или в старый суффикс, который сейчас не выделяется (зелёный), поэтому одна н.<br>4) В медный и книжная суффикс -н- присоединяется к основе, которая не оканчивается на н (мед-, книж-), поэтому н одна. Две н получаются, только если основа сама кончается на н (чугун + н).'},
 {n:2,l:1,st:1,task:'Образовать от существительных прилагательные. Записать их в два столбика: с одной н и с двумя н. Обозначить суффикс; если одна из двух н принадлежит основе существительного, подчеркнуть её. Если от слова можно образовать несколько прилагательных, взять то, в суффиксе которого есть н. С четырьмя прилагательными (два из одного столбика, два из другого) составить словосочетания.',
  obr:'Гусь, лимон. → Гус-ин-ый — одна н (суффикс -ин-); лимон-н-ый — две н (первая н — из основы лимон-, вторая — суффикс): гусиное перо, лимонный сок.',
  body:'Глубина, орёл, сезон, родство, мышь, коллекция, старина, голубь, окно, смола, торжество, ресторан, трава, экскурсия, вагон, нефть, количество, картон, комар, стекло, крыса.',
  key:'Одна н: орлиный (орл-ин-ый), мышиный (мыш-ин-ый), голубиный (голуб-ин-ый), комариный (комар-ин-ый), крысиный (крыс-ин-ый) — суффикс -ин-; смоляной (смол-ян-ой), травяной (трав-ян-ой), нефтяной (нефт-ян-ой) — суффикс -ян-.<br>Две н: глубинный (глубин-а + -н-), старинный (старин-а + -н-), оконный (окно → окон- + -н-), сезонный, ресторанный, вагонный, картонный — основа на н + суффикс -н- (подчёркивается первая н); родственный, торжественный, количественный — суффикс -енн-; коллекционный, экскурсионный — суффикс -онн-; стеклянный — исключение (суффикс -янн-). От слова стекло есть и прилагательное стекольный (стекольный завод): суффикс -н-, основа не на н — одна н; такой ответ тоже верен, если записан в нужный столбик.<br>Словосочетания — например: орлиное гнездо, старинный замок, оконная рама, торжественная линейка.'},
 {n:3,l:1,st:2,task:'Переписать предложения, вставляя пропущенные буквы. Обозначить суффикс в прилагательных с пропуском; если одна из двух н принадлежит основе существительного, подчеркнуть её. Рядом в скобках записать существительное, от которого образовано прилагательное.',
  obr:'Дедушка подарил мне шерстя..ые варежки. → Шерстяные (шерсть): суффикс -ян-, одна н.',
  body:'1. Илья Муромец — самый известный были..ый богатырь. 2. На операцио..ом столе лежал маленький котёнок, а ветеринар спокойно мыл руки. 3. Во дворе музея-усадьбы сохранилась ба..ая печь. 4. Лыжники прошли по равни..ой трассе двадцать километров. 5. Мама сварила на завтрак тыкве..ую кашу с изюмом. 6. Под старой елью мы нашли муравьи..ую тропу и долго наблюдали за её жителями. 7. Бабушка подарила внучке льня..ую скатерть с вышивкой. 8. Мой брат стал миллио..ым посетителем зоопарка и получил приз. 9. Из вольера донёсся льви..ый рык, и малыши испуганно прижались к родителям. 10. Музей получил це..ый подарок — письмо Пушкина. 11. Экра..ая версия романа понравилась не всем читателям. 12. На реке когда-то работала водя..ая мельница. 13. На фотографиях поверхность Марса выглядит безжизне..ой и пустой. 14. Ко..ая полиция следила за порядком на площади во время праздника.',
  key:'1. Былинный (былина): основа былин- + суффикс -н-. 2. Операционном (операция): суффикс -онн-. 3. Банная (баня): бан- + -н-. 4. Равнинной (равнина): равнин- + -н-. 5. Тыквенную (тыква): суффикс -енн-. 6. Муравьиную (муравей): суффикс -ин-, одна н. 7. Льняную (лён): суффикс -ян-, одна н. 8. Миллионным (миллион): миллион- + -н-. 9. Львиный (лев): суффикс -ин-, одна н. 10. Ценный (цена): цен- + -н-. 11. Экранная (экран): экран- + -н-. 12. Водяная (вода): суффикс -ян-, одна н. 13. Безжизненной (жизнь): приставка без- и суффикс -енн-. 14. Конная (конь): кон- + -н-.'},
 {n:5,l:1,st:2,task:'Переписать предложения, вставляя пропущенные буквы. Обозначить суффикс; если одна из двух н принадлежит основе существительного, подчеркнуть её. Указать в скобках существительное, от которого образовано прилагательное.',
  obr:'Над крыльцом висел жестя..ой фонарь. → Жестяной (жесть): суффикс -ян-, одна н.',
  body:'1. Высокий земля..ой вал окружал город; где вал был ниже, там высовывалась каме..ая стена или дом, служивший батареей, или, наконец, дубовый частокол. (Н. В. Гоголь, «Тарас Бульба») 2. Солнце пекло; из полутёмных сеней постоялого дворика несло запахом тёплого ржа..ого хлеба. (И. С. Тургенев, «Отцы и дети») 3. Рядчик вынул из-под полы кафтана новый кожа..ый кошелёк, не торопясь распутал шнурок и, насыпав множество мелочи на руку, выбрал новенький грош. (И. С. Тургенев, «Записки охотника») 4. Голова, как хозяин, сидел в одной только рубашке и полотня..ых шароварах. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 5. Он нёс в одной руке глиня..ый кувшин с водою — на всякий случай; сумка с хирургическими инструментами и бинтами болталась на его левом плече. (И. С. Тургенев, «Вешние воды») 6. Я спустился в долину; узкая песча..ая дорожка вилась по ней и вела в город. (И. С. Тургенев, «Первая любовь») 7. Молнии не прекращались ни на мгновение; была, что называется в народе, воробьи..ая ночь. (И. С. Тургенев, «Первая любовь») 8. Лебеди..ой грудью вздымался белый парус под резвыми вымпелами. (И. С. Тургенев, «Стихотворения в прозе») 9. Хороши также летние тума..ые дни, хотя охотники их и не любят. (И. С. Тургенев, «Записки охотника») 10. Скоро появилась сама Одинцова в простом утре..ем платье. (И. С. Тургенев, «Отцы и дети») 11. Его мысли заняты были одним: он никак не мог позабыть вероломства Солохи и со..ый не переставал бранить её. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 12. Особенно боятся его почтмейстеры, непременные заседатели и станцио..ые смотрители. (И. С. Тургенев, «Записки охотника») Пояснения: вал — высокая насыпь вокруг крепости; батарея — здесь: место, где стоят пушки; частокол — забор из вбитых в землю кольев; постоялый двор (дворик) — гостиница с двором для лошадей и повозок; сени — помещение между крыльцом и жилыми комнатами; рядчик — здесь: торговец-подрядчик, один из героев рассказа; пола — нижний край одежды; кафтан — старинная длинная верхняя одежда; грош — мелкая монета; голова — здесь: сельский староста; шаровары — широкие штаны; он — здесь: военный доктор; «воробьи..ая ночь» — так в народе называют летнюю ночь с непрерывными зарницами и грозой; вымпел — узкий длинный флажок на мачте; вероломство — измена; бранить — ругать; почтмейстер — начальник почтовой конторы; непременный заседатель — чиновник уездного суда; смотритель — здесь: начальник почтовой станции, где меняли лошадей.',
  key:'1. Земляной (земля): суффикс -ян-, одна н; каменная (камень): основа камен- + суффикс -н-, две н. 2. Ржаного (рожь): суффикс -ан-, одна н. 3. Кожаный (кожа): суффикс -ан-, одна н. 4. Полотняных (полотно): суффикс -ян-, одна н. 5. Глиняный (глина): суффикс -ян-, одна н. 6. Песчаная (песок): суффикс -ан-, одна н. 7. Воробьиная (воробей): суффикс -ин-, одна н. 8. Лебединой (лебедь): суффикс -ин-, одна н. 9. Туманные (туман): туман- + -н-, две н. 10. Утреннем (утро): суффикс -енн-, две н. 11. Сонный (сон): сон- + -н-, две н. 12. Станционные (станция): суффикс -онн-, две н.'},
 {n:6,l:1,st:2,task:'Вставить пропущенные буквы. Распределить словосочетания по пяти столбикам: 1) суффиксы -ан-, -ян-, -ин- (одна н); 2) суффикса -н- нет, н входит в корень (одна н); 3) суффиксы -онн-, -енн- (две н); 4) основа на н + суффикс -н- (две н); 5) исключения. Обозначить суффикс.',
  obr:'Гуси..ое перо, лимо..ый сок. → Гусиное — 1-й столбик (гус-ин-ое); лимонный — 4-й столбик (лимон- + -н-).',
  body:'Воробьи..ое гнездо, авиацио..ый завод, багря..ый клён, бето..ая плита, соля..ая пещера, отечестве..ая история, стекля..ая банка, рья..ый болельщик, лу..ый свет, торфя..ое болото, информацио..ый стенд, сте..ая газета, сви..ая отбивная, тигри..ый рык, письме..ый стол, пламе..ая речь, деревя..ая ложка, конопля..ое поле, величестве..ый собор, бессо..ая ночь.',
  key:'1) Воробьиное, тигриный (-ин-); соляная, торфяное, конопляное (-ян-).<br>2) Багряный, рьяный, свиная — суффикса -н- нет, н относится к корню.<br>3) Авиационный, информационный (-онн-); отечественная, письменный, величественный (-енн-).<br>4) Бетонная (бетон + -н-), лунный (луна: лун- + -н-), стенная (стена: стен- + -н-), пламенная (пламя: основа пламен- + -н-), бессонная (сон: приставка бес-, основа сон- + -н-).<br>5) Стеклянная, деревянная — исключения: суффикс -ян-, но две н.<br>Пояснение к слову: рьяный — очень усердный, горячий.'},
 {n:4,l:1,st:3,task:'Образовать от каждой пары существительных прилагательные и записать парами. Обозначить суффикс; если одна из двух н принадлежит основе существительного, подчеркнуть её. 1) Объяснить, почему в каждой паре прилагательные звучат на конце похоже, а пишутся по-разному. 2) Сделать вывод: можно ли по сочетанию «ин», «ан» на конце слова решить, сколько н писать? 3) С тремя парами составить предложения, в каждом из которых есть оба прилагательных пары.',
  obr:'Гусь — длина. → Гус-ин-ый: суффикс -ин-, одна н. Длин-н-ый: первая н — из основы длин(а), вторая — суффикс -н-, две н.',
  body:'1. Сокол — картина. 2. Лось — машина. 3. Зверь — пружина. 4. Оса — лавина. 5. Петух — камин. 6. Кровь — диван. 7. Железо — сено. 8. Береста — сукно.',
  key:'1) 1. Соколиный (сокол-ин-ый) — картинный (картин-а + -н-). 2. Лосиный (лос-ин-ый) — машинный (машин-а + -н-). 3. Звериный (звер-ин-ый) — пружинный (пружин-а + -н-). 4. Осиный (ос-ин-ый) — лавинный (лавин-а + -н-). 5. Петушиный (петуш-ин-ый, чередование х//ш) — каминный (камин + -н-). 6. Кровяной (кров-ян-ой) — диванный (диван + -н-). 7. Железный (желез-н-ый): суффикс -н-, но основа не на н — одна н; сенной (сен-о + -н-) — две н. 8. Берестяной (берест-ян-ой) — суконный (сукно → сукон- + -н-, беглый о).<br>В первом слове каждой пары суффикс -ин-, -ян- (или -н-) присоединяется к основе без н — н одна. Во втором слове основа существительного сама оканчивается на н (картина, диван, сено), к ней прибавляется суффикс -н- — получается две н.<br>2) Нельзя. «Ин» в конце может быть суффиксом (соколиный) или частью основы (картинный). Нужно найти исходное существительное и посмотреть, оканчивается ли его основа на н.<br>3) Например: В каминном зале висели лосиные рога. Пока врач измерял дедушке кровяное давление, кот дремал на диванной подушке. На картинной выставке была работа «Соколиная охота».'},
 {n:44,l:1,st:3,task:'1) Выписать из предложений все прилагательные, образованные от существительных с помощью суффиксов, в которых есть н (их не меньше девяти). Рядом записать исходное существительное. 2) Разобрать по составу прилагательные ледяными, огненные, лошадиную, оловянных, бессильный по плану: окончание (изменить слово) → основа → корень (подобрать однокоренные слова) → приставка → суффикс. 3) Указать, каким способом образовано прилагательное бессильный. 4) Объяснить, почему в каждом выписанном прилагательном одна н или две н.',
  obr:'Бабушка сварила куриный бульон. → Куриный (курица). Окончание -ый (куриная, куриного); основа курин-; корень кур- (курица, куры); приставки нет; суффикс -ин-. Образовано суффиксальным способом. Суффикс -ин- — одна н.',
  body:'1. Как бессильный старец, держал он в холодных объятиях своих далёкое, тёмное небо, обсыпая ледяными поцелуями огненные звёзды, которые тускло реяли среди тёплого ночного воздуха, как бы предчувствуя скорое появление блистательного царя ночи. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 2. Прежде, бывало, я мог согнуть и разогнуть в одной руке медный пятак и лошадиную подкову; а теперь мешков с углём не подыму. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 3. По выходе отца своего она долго ещё принаряживалась и жеманилась перед небольшим в оловянных рамках зеркалом и не могла налюбоваться собою. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 4. Вот зашла однажды о нём речь у барыни с её главным дворецким, Гаврилой, человеком, которому, судя по одним его жёлтым глазкам и утиному носу, сама судьба, казалось, определила быть начальствующим лицом. (И. С. Тургенев, «Муму») Пояснения: он (в предложении 1) — пруд; я (в предложении 2) — кузнец, который несёт мешки; реять — здесь: мерцать, плавно колыхаться; царь ночи — месяц; пятак — монета в пять копеек; жеманиться — вести себя притворно, кокетничать; дворецкий — старший слуга в барском доме; о нём — о сапожнике Капитоне; начальствующее лицо — начальник.',
  key:'1) Бессильный (сила), холодных (холод), ледяными (лёд), огненные (огонь), ночного (ночь), медный (медь), лошадиную (лошадь), оловянных (олово), утиному (утка). Можно выписать и главным (глава → глав-н-ым), хотя связь этого слова со словом глава сейчас мало заметна.<br>2) Ледяными: окончание -ыми (ледяной, ледяная); основа ледян-; корень лед- (лёд, ледник, гололёд); приставки нет; суффикс -ян-.<br>Огненные: окончание -ые (огненный, огненная); основа огненн-; корень огн- (огонь, огонёк, огниво); приставки нет; суффикс -енн-.<br>Лошадиную: окончание -ую (лошадиный, лошадиного); основа лошадин-; корень лошад- (лошадь, лошадка); приставки нет; суффикс -ин-.<br>Оловянных: окончание -ых (оловянный, оловянная); основа оловянн-; корень олов- (олово); приставки нет; суффикс -янн-.<br>Бессильный: окончание -ый (бессильная, бессильного); основа бессильн-; корень сил- (сила, силач, усилие); приставка бес-; суффикс -н-.<br>3) Бессильный ← сила: приставочно-суффиксальный способ (одновременно присоединены приставка бес- и суффикс -н-).<br>4) Одна н: ледяными (-ян-), лошадиную, утиному (-ин-); бессильный, холодных, ночного, медный, главным — суффикс -н- присоединяется к основе не на н (сил-, холод-, ноч-, мед-, глав-). Две н: огненные — суффикс -енн-; оловянных — исключение (суффикс -ян-, но две н). Не выписываются: далёкое, тёмное, тёплого, скорое, жёлтым, небольшим — не образованы от существительных с суффиксом -н-; блистательного — от глагола блистать (суффикс -тельн-); начальствующим — причастие.'},
 {n:7,l:1,st:3,task:'Переписать предложения, вставляя пропущенные буквы. Обозначить суффикс и объяснить написание: суффикс; основа на н; исключение; суффикса -н- нет. Затем выписать отдельно: а) слова, которые пишутся не по общему правилу о суффиксах; б) слово, в котором легко ошибиться, приняв часть основы за суффикс.',
  obr:'Весь день был ветре..ым. → Ветреным — исключение: ожидается суффикс -енн-, а пишется одна н.',
  body:'1. Вместо мрачных ставней глядели весёлые стекля..ые окна и двери. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 2. Капитон только прищурил немного свои оловя..ые глазки, но не опустил их, даже усмехнулся слегка и провёл рукой по своим белесоватым волосам, которые так и ерошились во все стороны. (И. С. Тургенев, «Муму») 3. Однажды я вошёл к ней и увидел её сидящей на соломе..ом стуле, с головой, прижатой к острому краю стола. (И. С. Тургенев, «Первая любовь») 4. Серебря..ый туман пал на окрестность. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 5. Дверь растворилась — и весёлый, свежий, румя..ый появился Николай Петрович. (И. С. Тургенев, «Отцы и дети») 6. Взор её так и мелькал, словно змеи..ое жало. (И. С. Тургенев, «Записки охотника») 7. Когда невыносимый полуде..ый зной заставил нас искать убежища, он свёл нас на свою пасеку, в самую глушь леса. (И. С. Тургенев, «Записки охотника») 8. Несколько мужиков, по обыкновению, зевали, сидя на лавках перед воротами в своих овчи..ых тулупах. (Н. В. Гоголь, «Мёртвые души») 9. Голос его поразил церковные деревя..ые стены, давно молчаливые и оглохлые. (Н. В. Гоголь, «Вий») Пояснения: ставни — створки для закрывания окон снаружи; в предложении 2 речь о тусклых, невыразительных глазах — серых и без блеска, как металл; ерошиться — торчать в разные стороны; к ней — к Зинаиде, героине повести; окрестность — местность вокруг; взор — взгляд; убежище — укрытие; он (в предложении 7) — старик-слуга, о котором идёт речь в рассказе; пасека — место, где стоят ульи с пчёлами; тулуп — длинная шуба из овечьих шкур; оглохлые — глухие, давно не слышавшие звуков.',
  key:'1. Стеклянные — исключение (стекл-янн-ые). 2. Оловянные — исключение (олов-янн-ые). 3. Соломенном (солома) — суффикс -енн-. 4. Серебряный (серебро) — суффикс -ян-, одна н. 5. Румяный — суффикса -н- нет, н относится к корню, одна н. 6. Змеиное (змея) — суффикс -ин-, одна н. 7. Полуденный (полдень) — основа полуден- + суффикс -н-, две н. 8. Овчинных (овчина) — основа овчин- + суффикс -н-, две н. 9. Деревянные — исключение (дерев-янн-ые).<br>а) Не по общему правилу: стеклянные, оловянные, деревянные (суффикс -ян-, а пишется две н); румяный (н в корне, суффикса -н- нет).<br>б) Овчинных: «ин» здесь не суффикс -ин-, а конец основы существительного овчина; к ней прибавлен суффикс -н-. Сравнить: змеиное (зме-ин-ое) — суффикс -ин-, одна н.'},
 {n:8,l:1,st:4,task:'Выбрать из скобок слово, которое подходит по смыслу, и вставить пропущенные буквы. Объяснить выбор: что значит слово, от какого слова оно образовано и почему в нём одна или две н. В одном предложении нужно выбрать между прилагательными с разными суффиксами (-ян- и -ист-): объяснить и эту разницу.',
  body:'1. Разнообразнейшие чувства, лёгкие, быстрые, как тени облаков в солнечный (ветре..ый, ветря..ой) день, перебегали то и дело по её глазам и губам. (И. С. Тургенев, «Первая любовь») 2. За воротами находились две (ветре..ые, ветря..ые) мельницы. (Н. В. Гоголь, «Вий») 3. В кабинете над диваном висел портрет хозяина в уланском мундире, писанный (масля..ыми, масле..ыми) красками. (И. С. Тургенев, «Записки охотника») 4. И (ветре..ая, ветря..ая) красавица уже шутила со своими подругами. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 5. Надо (серебря..ых, серебристых) тополей побольше здесь сажать, да ёлок, да, пожалуй, липок, подбавивши чернозёму. (И. С. Тургенев, «Отцы и дети») 6. После блинов у малыша были (масля..ые, масле..ые) щёки и пальцы. 7. Ночь выдалась тихая, (ветре..ая, безветре..ая), и дым из труб поднимался прямо вверх. 8. В детском саду карантин: у троих малышей (ветре..ая, ветря..ая) оспа. 9. Мастер заменил в машине (масля..ый, масле..ый) фильтр. 10. На холмах за городом построили (ветре..ые, ветря..ые) электростанции. Пояснения: уланский мундир — форма улана, кавалериста; красавица (в предложении 4) — Оксана: она только что прогнала влюблённого кузнеца и уже уверена, что он вернётся; подбавить — добавить.',
  key:'1. Ветреный — с ветром (о погоде); исключение: одна н. 2. Ветряные — приводимые в движение ветром; суффикс -ян-, одна н. 3. Масляными — сделанными на масле (о красках); суффикс -ян-, одна н. 4. Ветреная — легкомысленная, непостоянная; то же слово, что ветреный день, другое значение, тоже одна н. 5. Серебристых — серебристый тополь: дерево с листьями, которые блестят, как серебро; суффикс -ист-, н в нём нет. Серебряный — сделанный из серебра (суффикс -ян-), тополь серебряным быть не может. 6. Масленые — пропитанные, вымазанные маслом; образовано от глагола маслить, одна н. 7. Безветренная — без ветра: приставка без- и суффикс -енн-, две н (сравнить: ветреная — одна н). 8. Ветряная оспа — название болезни; суффикс -ян-, одна н. 9. Масляный фильтр — фильтр для масла; суффикс -ян-, одна н. 10. Ветряные электростанции — работают от ветра; суффикс -ян-, одна н.'},
 {n:9,l:1,st:4,task:'Найти и исправить ошибки в написании н и нн. Ошибки есть не во всех предложениях. Объяснить каждое исправление. Доказать, что в остальных предложениях прилагательные написаны верно.',
  body:'1. Вечер выдался тихий, безветреный, и над озером повис туман. 2. В гардеробе висела чья-то кожаная куртка с капюшоном. 3. На стариной карте острова не было ни одной дороги. 4. Рыбаки развели костёр на песчаном берегу. 5. Из окна поезда были видны бескрайние ржаные поля. 6. Малыш размазал по столу клюквеное варенье. 7. Традиционый турнир по шахматам прошёл в школьной библиотеке. 8. Соседи сложили поленья в дровяной сарай. 9. Утреняя зарядка заняла у меня десять минут. 10. Юнный пианист сыграл без единой ошибки. 11. Длинный коридор вёл в спортзал. 12. Сонный котёнок свернулся клубком на подоконнике. 13. На уроке труда мы делали торфяные горшочки для рассады. 14. Брат с гордостью показал серебряную медаль за олимпиаду.',
  key:'Ошибки (6): 1. Безветренный — приставка без- и суффикс -енн-: две н (одна н — только в слове ветреный без приставки). 3. Старинной — старина: основа старин- + суффикс -н-, две н. 6. Клюквенное — суффикс -енн-. 7. Традиционный — суффикс -онн- (традиция). 9. Утренняя — суффикс -енн- (утро). 10. Юный — в слове нет суффикса -н-, н входит в корень: одна н.<br>Верно: 2. кожаная (кожа, -ан-); 4. песчаном (песок, -ан-); 5. ржаные (рожь, -ан-; ударение не влияет); 8. дровяной (дрова, -ян-); 11. длинный (длина: длин- + -н-); 12. сонный (сон- + -н-); 13. торфяные (торф, -ян-); 14. серебряную (серебро, -ян-).'},
 {n:41,l:1,st:4,task:'Прочитать отрывок. 1) Выписать прилагательные, образованные от существительных, в которых есть н или нн в суффиксе или на стыке основы и суффикса. Указать исходное существительное, обозначить суффикс и распределить слова по группам: а) одна н; б) две н: основа на н + суффикс -н-; в) две н: суффикс -онн-, -енн-; г) исключение. 2) Найти в отрывке слово с нн, которое образовано не от существительного. Определить, какая это часть речи и почему правило этого урока к нему не относится. 3) Объяснить, почему в словах мучными и колокольный одна н, а в слове длинные — две, хотя во всех трёх есть суффикс -н-. 4) Найти два прилагательных, в которых н входит в корень, а суффикса -н- нет.',
  body:'Бричка между тем поворотила в более пустынные улицы; скоро потянулись одни длинные деревянные заборы, предвещавшие конец города. Вот уже и мостовая кончилась, и шлагбаум, и город назади, и ничего нет, и опять в дороге. И опять по обеим сторонам столбового пути пошли вновь писать версты, станционные смотрители, колодцы, обозы, серые деревни с самоварами, бабами и бойким бородатым хозяином, бегущим из постоялого двора с овсом в руке, пешеход в протёртых лаптях, плетущийся за восемьсот вёрст, городишки, выстроенные живьём, с деревянными лавчонками, мучными бочками, лаптями, калачами и прочей мелюзгой, рябые шлагбаумы, чинимые мосты <…>, зелёные, жёлтые и свежеразрытые чёрные полосы, мелькающие по степям, затянутая вдали песня, сосновые верхушки в тумане, пропадающий далече колокольный звон, вороны как мухи и горизонт без конца… (Н. В. Гоголь, «Мёртвые души») Пояснения: бричка — лёгкая дорожная повозка; шлагбаум — подъёмная перекладина на въезде в город; назади — позади; столбовой путь — большая дорога с верстовыми столбами; «пошли писать версты» — замелькали вёрсты (верста — старинная мера длины, около километра); смотритель — здесь: начальник почтовой станции, где проезжающие меняли лошадей; постоялый двор — гостиница с двором для лошадей; выстроенные живьём — построенные наспех; калач — круглый белый хлеб с ручкой-дужкой; мелюзга — здесь: всякая мелочь; чинимые — которые чинят; далече — далеко.',
  key:'1) а) Одна н: мучными (мука: муч-н-ыми, суффикс -н-, чередование к//ч), колокольный (колокол: колоколь-н-ый, суффикс -н-).<br>б) Две н, основа на н + -н-: пустынные (пустыня: пустын- + -н-), длинные (длина: длин- + -н-).<br>в) Две н, суффикс -онн-: станционные (станция).<br>г) Исключение: деревянные, деревянными (дерево: суффикс -ян-, но две н).<br>Мостовая, столбового, сосновые — суффикс -ов-, н в нём нет; бородатым — суффикс -ат-.<br>2) Выстроенные — причастие (от глагола выстроить): полное страдательное причастие с приставкой, в суффиксе -енн- две н (глава «Причастие»). Правило урока касается только прилагательных, образованных от существительных.<br>3) Во всех трёх словах суффикс -н- одинаковый. В мучными и колокольный основа существительного не оканчивается на н (мук-, колокол-), поэтому н одна. У длина основа длин- сама оканчивается на н, и к ней прибавляется ещё одна н суффикса — получаются две.<br>4) Зелёные, чёрные: суффикса -н- нет, н входит в корень (у зелёный — в старый суффикс, который сейчас не выделяется), поэтому одна н.'},
 {n:42,l:1,st:5,task:'Лингвистическая задача. 1) Во всех словах первой группы пишется две н, но по разным причинам. Разделить слова на две подгруппы: а) суффикс -енн-; б) основа на н + суффикс -н-. Доказать свой выбор: подобрать форму существительного, в которой видна (или не видна) н основы. Объяснить, почему в словах песенный и лиственный на слух одинаковое «-енн-», а причины разные. 2) Во всех словах второй группы одна н или н нет совсем. Указать исходное существительное и суффикс каждого прилагательного, объяснить, почему нет двух н, и показать на примерах словосочетаний, чем слова в парах различаются по значению. 3) Объяснить, почему глиняный пишется с одной н, хотя в слове глина есть сочетание «ин», а машинный — с двумя.',
  body:'Первая группа: песенный, лиственный, коленный, бесценный, хозяйственный, семенной, государственный.<br>Вторая группа: водяной — водный; земляной — земной; ледяной — ледовый.<br>Третья пара: глиняный — машинный.',
  key:'1) а) Суффикс -енн-: лиственный (листва → листв-енн-ый), хозяйственный (хозяйство → хозяйств-енн-ый), государственный (государство → государств-енн-ый). В этих существительных нет формы, где основа оканчивалась бы на н (листва, листвы; хозяйство, хозяйства).<br>б) Основа на н + суффикс -н-: песенный (песня — песен: в родительном падеже множественного числа видна основа песен- с беглым е), коленный (колено — колен- + -н-), бесценный (цена — цен- + -н-; приставка бес-, способ приставочно-суффиксальный), семенной (семя — семени: основа семен- + -н-).<br>На слух песенный и лиственный оканчиваются одинаково, но в песенный е и первая н принадлежат основе (песен-), а в лиственный «енн» — целиком суффикс: основы «листвен-» нет.<br>2) Водяной (вод-ян-ой) — водный (вод-н-ый); земляной (земл-ян-ой) — земной (зем-н-ой); ледяной (лед-ян-ой) — ледовый (лед-ов-ый). В -ян- одна н; суффикс -н- присоединяется к основе не на н — тоже одна; в -ов- н нет. Значения: водяная мельница (приводится в движение водой) — водный транспорт (по воде); земляной вал (из земли) — земной шар (относящийся к Земле); ледяная горка (из льда) — ледовый дворец (для катания на льду).<br>3) Глиняный: корень глин-, суффикс -ян- (глин-ян-ый); «ин» здесь — часть корня, а суффикс -ян- даёт одну н. Машинный: основа машин- + суффикс -н- — н основы и н суффикса, две н.'},
 {n:43,l:1,st:5,os:'диктант',task:'Диктант. Текст читает учитель или родитель. Записать под диктовку. Затем: 1) подчеркнуть прилагательные, образованные от существительных, в которых есть н или нн в суффиксе или на стыке основы и суффикса (их восемь); обозначить суффикс и объяснить, почему одна н или две; 2) выписать прилагательные с суффиксами -ист-, -ов-, -чат- и объяснить, почему их нельзя путать с прилагательными на -ян-, -ан-; 3) найти два причастия с нн и объяснить, почему в них две н (по главе «Причастие»).',
  body:'Точно: под самым обрывом таится источник; дубовый куст жадно раскинул над водою свои лапчатые сучья; большие серебристые пузыри, колыхаясь, поднимаются со дна, покрытого мелким, бархатным мхом. <…> Ветер внезапно налетел и промчался; воздух дрогнул кругом: уж не гром ли? Вы выходите из оврага… что за свинцовая полоса на небосклоне? <…> Трава, кусты, всё вдруг потемнело… Скорей! вон, кажется, виднеется сенной сарай… скорее!.. Вы добежали, вошли… <…> Кое-где сквозь соломенную крышу закапала вода на душистое сено… Но вот солнце опять заиграло. Гроза прошла; вы выходите. Боже мой, как весело сверкает всё кругом, как воздух свеж и жидок, как пахнет земляникой и грибами!.. (И. С. Тургенев, «Записки охотника») …Осенью вальдшнепы часто держатся в старинных липовых садах. Таких садов у нас в Орловской губернии довольно много. <…> Лет через пятьдесят, много семьдесят, эти усадьбы, «дворянские гнёзда», понемногу исчезали с лица земли, дома сгнивали или продавались на своз, каменные службы превращались в груды развалин, яблони вымирали и шли на дрова, заборы и плетни истреблялись. Одни липы по-прежнему росли себе на славу и теперь, окружённые распаханными полями, гласят нашему ветреному племени о «прежде почивших отцах и братиях». Прекрасное дерево — такая старая липа… Её щадит даже безжалостный топор русского мужика. Лист на ней мелкий, могучие сучья широко раскинулись во все стороны, вечная тень под ними. (И. С. Тургенев, «Записки охотника») Пояснения: точно — в самом деле (рассказчик спустился в овраг, чтобы найти родник); вальдшнеп — лесная птица; на своз — чтобы разобрать и увезти; службы — хозяйственные постройки при доме; плетень — изгородь из прутьев; гласить — говорить, напоминать; «племя» здесь — нынешнее поколение, потомки; «прежде почившие отцы и братия» — умершие предки.',
  key:'1) Одна н: бархатным (бархат + -н-), безжалостный (жалость: без- + -н-), вечная (век: веч-н-ая) — суффикс -н- присоединяется к основе не на н; ветреному — исключение, одна н. Две н: сенной (сено: сен- + -н-), старинных (старина: старин- + -н-), каменные (камень: камен- + -н-) — основа на н + суффикс -н-; соломенную (солома) — суффикс -енн-.<br>(Русского, Орловской, дворянские — суффикс -ск-, н в нём нет; мелким, могучие, прекрасное — не образованы от существительных.)<br>2) Серебристые, душистое (-ист-), дубовый, свинцовая, липовых (-ов-), лапчатые (-чат-) — в этих суффиксах н нет совсем. Серебристые — похожие на серебро по цвету и блеску, а не сделанные из серебра (серебряный, -ян-).<br>3) Окружённые (распаханными полями), распаханными — полные страдательные причастия прошедшего времени с приставками (о-, рас-), поэтому две н. Покрытого — причастие с суффиксом -т-.'},
 {n:10,l:1,st:5,os:'сочинение',task:'Написать сочинение-миниатюру «В краеведческом музее» (6–8 предложений): описать один зал музея и предметы в нём. Условия: 1) употребить не меньше девяти прилагательных, образованных от существительных: не меньше двух с суффиксами -ан-, -ян-, -ин-; не меньше двух с суффиксами -онн-, -енн-; не меньше двух, в которых основа оканчивается на н (камень → каменный); одно из исключений; 2) употребить пару слов, которые легко спутать: масляный — масленый, ветреный — ветряной или серебряный — серебристый (оба слова пары); 3) прилагательные должны стоять в разных падежах. Подчеркнуть прилагательные, обозначить суффикс и объяснить написание н или нн.',
  body:'Опорные слова (можно взять другие): глина, береста, олово, стекло, дерево, лён, кожа, сукно, камень, старина, серебро, утро, ремесло, коллекция, экскурсия, витрина, прялка, самовар, сундук, карта.',
  key:'Ответы могут быть разными. Проверить: не меньше девяти прилагательных от существительных; есть суффиксы -ан-, -ян-, -ин- (глиняные горшки, берестяной туесок, кожаный пояс, льняное полотенце) — одна н; -онн-, -енн- (экскурсионная группа, коллекционные монеты, ремесленные изделия, утреннее солнце) — две н; основа на н + -н- (каменный топор, старинная карта, суконный кафтан, витринное стекло) — две н; исключение (оловянные пуговицы, стеклянная витрина, деревянная прялка) — две н; пара слов употреблена верно по значению (масляная лампа — масленые пятна на скатерти; ветреный день — ветряная мельница на картине; серебряная ложка — серебристый мех); прилагательные стоят в разных падежах; суффиксы обозначены верно; нет ошибок вида «кожанный», «деревяный», «стариный», «ветренный».'},
// Урок 2
 {n:11,l:2,st:1,task:'Прочитать словосочетания. Выписать слова с н или нн, образованные от глаголов, и распределить их по пяти столбикам: 1) есть приставка (кроме не-); 2) есть зависимое слово; 3) есть суффикс -ова- (-ева-, -ирова-); 4) образовано от глагола совершенного вида; 5) примет нет. Приметы проверять по порядку, как в схеме урока: слово записывается в столбик первой найденной приметы. Подчеркнуть примету. Слова, образованные от существительных, не выписывать. Ответить: какая ещё примета есть у всех слов первого столбика?',
  obr:'Нарезанный хлеб → 1-й столбик: на- (приставка). Глиняный кувшин — от существительного (глина), не выписывается.',
  body:'Подметённая дорожка, солёные огурцы, тренированный спортсмен, тушённое на медленном огне мясо, стёганое одеяло, песчаный берег, купленный билет, квашеная капуста, газированная вода, тканный вручную ковёр, обиженный малыш, нечищеная картошка, кожаный ремень, маринованные грибы, копчённая на ольховых щепках рыба, отглаженная рубашка, утренняя газета, данное слово, варёное яйцо, кручёный мяч, застеклённая веранда, длинный коридор.',
  key:'1) Приставка: подметённая (под-), отглаженная (от-), застеклённая (за-).<br>2) Зависимое слово: тушённое (на медленном огне), тканный (вручную), копчённая (на ольховых щепках).<br>3) Суффикс -ова- (-ирова-): тренированный, газированная, маринованные.<br>4) Совершенный вид: купленный (купить), обиженный (обидеть), данное (дать).<br>5) Примет нет, одна н: солёные, стёганое, квашеная, нечищеная (не- приметой не считается), варёное, кручёный.<br>Не выписываются (от существительных): песчаный, кожаный, утренняя, длинный.<br>Ответ: все слова первого столбика образованы от глаголов совершенного вида (подмести, отгладить, застеклить) — у них сразу две приметы.'},
 {n:45,l:2,st:1,task:'Прочитать текст. Выписать все прилагательные и причастия с н или нн в суффиксе и распределить их в две группы: А) образованные от существительных; Б) образованные от глаголов. В группе Б у слов с нн назвать примету, у слов с одной н написать «примет нет». Слова с суффиксом -т- (вышитый, литой) не выписывать.',
  obr:'У двери стоял деревянный сундук, а на нём — сложенное вчетверо одеяло. → А) деревянный (дерево; исключение). Б) сложенное (сложить: приставка с-, зависимое слово вчетверо).',
  body:'В субботу наш класс ездил в краеведческий музей. В первом зале стояли берестяные туеса, расписанные яркими цветами прялки и плетёные короба. Под стеклом лежали серебряные монеты, обнаруженные при раскопках у реки, и простреленный солдатский шлем. Рядом висел дублёный тулуп ямщика и лежала данная городу царём грамота. Нас удивила старинная карта губернии, начерченная от руки. Больше всего ребятам понравилась диорама «Ярмарка»: маленькие торговцы продают мочёные яблоки, сушёные грибы и печёные пироги, а на прилавках стоят глиняные свистульки. В последнем зале показывали рисованный фильм об истории города. Домой мы возвращались по осеннему городу, освещённому фонарями. Пояснения: туес — коробка с крышкой из берёзовой коры; прялка — приспособление для прядения ниток; тулуп — длинная шуба из овчины; ямщик — кучер, который возил почту и путников; диорама — объёмная картина с фигурками.',
  key:'А) От существительных: берестяные (берёста, -ян-), серебряные (-ян-), старинная (старина: основа на н + -н-), глиняные (-ян-), осеннему (осень + -н-).<br>Б) От глаголов: расписанные — приставка рас- (и зависимое слово); плетёные — примет нет; обнаруженные — приставка об- (и зависимое слово); простреленный — приставка про-; дублёный — примет нет; данная — совершенный вид (дать), есть и зависимые слова; начерченная — приставка на-; мочёные, сушёные, печёные — примет нет; рисованный — суффикс -ова-; освещённому — приставка о- (и зависимое слово).'},
 {n:12,l:2,st:2,task:'Вставить н или нн. Записать в скобках глагол, от которого образовано слово, указать его вид и объяснить выбор буквы.',
  obr:'Броше..ый камень → брошенный (бросить, сов. в.): глагол совершенного вида — две н. Лома..ая линия → ломаная (ломать, несов. в.): примет нет — одна н.',
  body:'Реше..ая задача, кипячё..ая вода, проще..ый долг, гофрирова..ый картон, рубле..ые котлеты, вяле..ая дыня, плавле..ый сырок, пленё..ый офицер, топлё..ое молоко, дрессирова..ый медведь, жёва..ая бумага, краде..ый велосипед, сея..ая мука, фарширова..ый перец, гружё..ая баржа, точё..ые ножки стола.',
  key:'Решённая (решить, сов.) — две н; кипячёная (кипятить, несов.) — одна; прощённый (простить, сов.) — две; гофрированный (гофрировать, несов.) — две: суффикс -ирова-; рубленые (рубить, несов.) — одна; вяленая (вялить, несов.) — одна; плавленый (плавить, несов.) — одна; пленённый (пленить, сов.) — две; топлёное (топить, несов.) — одна; дрессированный (дрессировать, несов.) — две: суффикс -ирова-; жёваная (жевать, несов.) — одна: -ев- входит в корень (жую), суффикса -ева- нет; краденый (красть, несов.) — одна; сеяная (сеять, несов.) — одна; фаршированный (фаршировать, несов.) — две: суффикс -ирова-; гружёная (грузить, несов.) — одна; точёные (точить, несов.) — одна.'},
 {n:13,l:2,st:2,task:'Вставить н или нн. Распределить словосочетания в три столбика: 1) две н только из-за суффикса -ова- (-ева-, -ирова-), других примет нет; 2) две н, потому что есть приставка (кроме не-) или зависимое слово (если при этом есть и -ова-, слово всё равно записать сюда); 3) одна н. Для каждого слова, в котором перед н стоит -ов- (-ёв-), записать глагол в форме «я …ю» и показать, суффикс это или часть корня.',
  obr:'Пломбирова..ый зуб → пломбированный: пломбировать — я пломбирую; -ирова- — суффикс (корень пломб-), других примет нет — 1-й столбик.',
  body:'Кова..ая ограда, клёва..ое воробьями яблоко, рискова..ый трюк, избалова..ая кошка, нешлифова..ый камень, неглаже..ая юбка, консервирова..ый горошек, непуга..ые птицы, полирова..ый стол, непаха..ое поле, нераспакова..ые чемоданы, тка..ый половик, асфальтирова..ая площадка, мороже..ая рыба, ноше..ый старшим братом свитер, организова..ый отдых, мощё..ая улица, зашнурова..ые ботинки.',
  key:'1) Только -ова- (-ирова-): рискованный (я рискую), нешлифованный (я шлифую; не- не мешает), консервированный (я консервирую), полированный (я полирую), асфальтированная (я асфальтирую), организованный (я организую) — в форме «я …ю» -ова- меняется на -у-, а корень остаётся.<br>2) Приставка или зависимое слово: клёванное воробьями (зависимое слово; -ёв- здесь в корне: я клюю), избалованная (приставка из-; я избалую), нераспакованные (приставка рас-; я распакую), ношенный старшим братом (зависимое слово), зашнурованные (приставка за-; я зашнурую).<br>3) Одна н: кованая (я кую — -ов- входит в корень, суффикса -ова- нет), неглаженая, непуганые, непаханое (не- приметой не считается), тканый, мороженая, мощёная — примет нет.'},
 {n:14,l:2,st:2,task:'Переписать предложения, вставляя н или нн. Над каждым словом с пропуском указать примету, по которой выбрана буква, или написать «примет нет».',
  obr:'На подоконнике сохли выстира..ые салфетки и штопа..ые варежки. → Выстиранные (приставка вы-), штопаные (примет нет).',
  body:'1. Через полчаса в камине закипало уже в горшке какое-то варево, а в ожидании, пока оно поспеет, Валек поставил на трёхногий столик сковороду, на которой дымились куски жаре..ого мяса. (В. Г. Короленко, «Дети подземелья») 2. Старуха мать, засучив сильные загорелые руки, раскладывала виноград, сушё..ую рыбу, каймак и хлеб на низеньком круглом татарском столике. (Л. Н. Толстой, «Казаки») 3. Больные один за другим выходили из дверей, у которых стоял сторож и давал каждому из них толстый белый, вяза..ый из бумаги колпак с красным крестом на лбу. (В. М. Гаршин, «Красный цветок») 4. Кругом стола было несколько некраше..ых, но от долгого употребления залакирова..ых табуретов. (Л. Н. Толстой, «Детство») 5. Сидевший в официантской пудре..ый старик слуга тихим движением встал и шёпотом доложил: «Пожалуйте». (Л. Н. Толстой, «Война и мир») 6. Мать, расстрое..ая душевно, потому что очень любила покойного дедушку, и очень утомлё..ая, пролежала почти целый день, не занимаясь нами. (С. Т. Аксаков, «Детские годы Багрова-внука») 7. Только дома были почти все деревянные и улицы немощё..ые. (Л. Н. Толстой, «Воскресение») 8. Хозяин был красавец лет двадцати пяти, свежий, холё..ый, расчёса..ый. (Л. Н. Толстой, «Холстомер») 9. Отец встретил его мрачным и удивлё..ым взглядом, но Тыбурций выдержал этот взгляд спокойно. (В. Г. Короленко, «Дети подземелья») Пояснения: Валек, Тыбурций — герои повести; каймак — густые сливки; бумага (в 3-м предложении) — хлопковая пряжа; официантская — комната для прислуги; холить — заботливо ухаживать.',
  key:'1. Жареного — примет нет. 2. Сушёную — примет нет. 3. Вязанный — зависимое слово (вязанный из чего? из бумаги). 4. Некрашеных — не- приметой не считается, других примет нет; залакированных — приставка за-, суффикс -ова-. 5. Пудреный — примет нет. 6. Расстроенная — приставка рас-; утомлённая — глагол совершенного вида (утомить). 7. Немощёные — не- не в счёт, примет нет. 8. Холёный — примет нет; расчёсанный — приставка рас-. 9. Удивлённым — глагол совершенного вида (удивить).'},
 {n:15,l:2,st:3,task:'Вставить н или нн. Подчеркнуть слова, в которых две н пишутся без всяких примет (слова-исключения); для остальных слов назвать примету или написать «примет нет». Ответить на вопросы: 1) Изменилось бы написание слова в 3-м предложении, если убрать слово «мною»? 2) Почему в 10-м предложении слово с не- пишется с двумя н, а во 2-м и 8-м — с одной?',
  obr:'Пришла нежда..ая весть. Никто не просил его непроше..ых советов. → Нежданная — исключение: примет нет, но две н. Непрошеных — не- приметой не считается, других примет нет — одна н.',
  body:'1. Я был так поражён этим невида..ым зрелищем, что совершенно онемел и не отвечал ни одного слова на вопросы отца и матери. (С. Т. Аксаков, «Детские годы Багрова-внука») 2. Нечёса..ые волосы, закинутые кверху, открывали невысокий и чрезвычайно чистый лоб. (Л. Н. Толстой, «Альберт») 3. Когда мы выехали на десятину, которую жали человек с десять, говор прекратился, но зато шарканье серпов по соломе усилилось и наполняло всё поле необыкновенными и неслыха..ыми мною звуками. (С. Т. Аксаков, «Детские годы Багрова-внука») 4. Она подошла к Пьеру тихими, медле..ыми шагами. (Л. Н. Толстой, «Война и мир») 5. Я хозяин дворца и сада, я принял тебя как дорогого гостя и зва..ого, накормил, напоил и спать уложил, а ты эдак-то заплатил за моё добро? (С. Т. Аксаков, «Детские годы Багрова-внука») 6. Неприятель побеждён, и завтра погоним его из свяще..ой земли русской, — сказал Кутузов, крестясь; и вдруг всхлипнул от наступивших слёз. (Л. Н. Толстой, «Война и мир») 7. Испуга..ые неожида..ым плеском, местные лягушки все попрятались в воду. (В. М. Гаршин, «Лягушка-путешественница») 8. Кидали им туда тесто непечё..ое, как собакам, да в кувшине воду спускали. (Л. Н. Толстой, «Кавказский пленник») 9. И наконец пришёл этот жела..ый день и час! (С. Т. Аксаков, «Детские годы Багрова-внука») 10. То вспоминался ему награждё..ый Лазарев и Денисов, наказа..ый и непрощё..ый. (Л. Н. Толстой, «Война и мир») Пояснения: десятина — участок поля (старая мера площади); жать — срезать колосья серпом; эдак-то — вот так; день и час (в 9-м предложении) — день, когда на реке тронулся лёд; Лазарев, Денисов — герои романа: одного наградили, другого наказали.',
  key:'Исключения (две н без примет): 1. невиданным; 3. неслыханными; 4. медленными; 6. священной; 7. неожиданным; 9. желанный.<br>Остальные: 2. Нечёсаные — не- не в счёт, примет нет, одна н. 5. Званого — примет нет, одна н. 7. Испуганные — приставка ис-. 8. Непечёное — не- не в счёт, примет нет, одна н. 10. Награждённый, наказанный — приставка на-; непрощённый — глагол совершенного вида (простить).<br>Ответы: 1) Нет: неслыханный — исключение и без зависимых слов пишется с двумя н. 2) Не- приметой не считается ни там, ни там; решает остальное: у непрощённый есть примета (простить — совершенный вид), у нечёсаные и непечёное (чесать, печь — несовершенный вид) примет нет.'},
 {n:16,l:2,st:3,task:'Вставить н или нн. Выписать слова с пропусками в два столбика: 1) прилагательные, образованные от существительных; 2) слова, образованные от глаголов. В первом столбике обозначить суффикс (или объяснить исключение), во втором — назвать примету или написать «примет нет».',
  obr:'На полке стояли стекля..ая банка и выреза..ая из липы ложка. → 1) стеклянная — от существительного стекло, исключение; 2) вырезанная — от глагола вырезать: приставка вы-, зависимое слово (из липы).',
  body:'1. Небольшой круглый стол был убран роскошно: посредине стояло прекрасное дерево с цветами и плодами; гранё..ый хрусталь, серебро и золото ослепили мои глаза. (С. Т. Аксаков, «Детские годы Багрова-внука») 2. Казаки сидели за ужином в маза..ых сенях кордона, на земля..ом полу, вокруг низкого татарского столика, когда речь зашла о череде в секрет. (Л. Н. Толстой, «Казаки») 3. На большие столы без скатертей поставили по нескольку деревя..ых краше..ых и золочё..ых мисок с жидкою пшё..ою кашицею; больные уселись на лавки; им раздали по ломтю чёрного хлеба. (В. М. Гаршин, «Красный цветок») 4. Мы въехали на широкий четвероугольный двор, посреди которого был устроен мраморный фонтан и солнечные часы: они были окружены широкими красивыми цветниками с песча..ыми дорожками. (С. Т. Аксаков, «Детские годы Багрова-внука») 5. У нас с сестрицей были прекрасные с крышечками берестовые бурачки, испещрё..ые вытисне..ыми на них узорами. (С. Т. Аксаков, «Детские годы Багрова-внука») 6. Она нагнула голову и исподлобья смотрела сияющими мокрыми глазами на маленькую, худенькую и жалкую в своей штопа..ой кофточке и ночном чепчике, всю дрожавшую от волнения Долли. (Л. Н. Толстой, «Анна Каренина») 7. Это было большое каменное здание старинной казё..ой постройки. (В. М. Гаршин, «Красный цветок») 8. Из-под тулупа поднялся старик в ночной шапке и лоснящемся, рва..ом бешмете. (Л. Н. Толстой, «Хаджи-Мурат») 9. Я даже слышал сквозь запертую и завеше..ую дверь сначала выразительный и явстве..ый шёпот, а потом и жаркий разговор вполголоса, причём иногда вырывались и громкие слова. (С. Т. Аксаков, «Детские годы Багрова-внука») Пояснения: сени — помещение между жилой частью избы и крыльцом; кордон — сторожевой пост; череда в секрет — очередь идти в ночной дозор; бурачок — коробочка из бересты; испещрить — покрыть мелким пёстрым узором; вытиснить — выдавить узор на поверхности; бешмет — кафтан у народов Кавказа; явственный — отчётливый.',
  key:'1) От существительных: земляном (-ян-), деревянных (исключение), пшённою (пшено: основа пшён- на н + -н-), песчаными (-ан-), казённой (казна: основа казён- на н + -н-), явственный (-енн-).<br>2) От глаголов: гранёный — примет нет; мазаных — примет нет; крашеных, золочёных — примет нет; испещрённые — приставка ис-; вытисненными — приставка вы-, зависимое слово (на них); штопаной — примет нет; рваном — примет нет; завешенную — приставка за-.'},
 {n:46,l:2,st:3,task:'Вставить н или нн. Выписать слова с пропусками и разобрать их по составу (окончание, основа, корень, приставка, суффиксы). Рядом записать глагол, от которого образовано слово, и его вид. По разбору объяснить, почему пишется одна н или две. Ответить: что в составе слов копаная и сорванных решает, сколько н писать?',
  obr:'Мальчишка был в лата..ой куртке → лат-а-н-ой: окончание -ой, основа латан-, корень лат-, суффиксы -а-, -н-; латать — несов. в. Приставки, суффикса -ова- и зависимых слов нет — одна н.',
  body:'1. Я был любимец, фаворит, как многие называли меня, и, следовательно, балова..ое дитя. (С. Т. Аксаков, «Детские годы Багрова-внука») 2. Несколько воробьёв вспорхнули с насиже..ых мест на хорах и вылетели в большую прореху в крыше. (В. Г. Короленко, «Дети подземелья») 3. Вслед за тем сам хорунжий, в новой черкеске с офицерскими погонами на плечах, в чище..ых сапогах — редкость у казаков, — с улыбкой на лице, раскачиваясь, вошёл в комнату и поздравил с приездом. (Л. Н. Толстой, «Казаки») 4. Только одна могила, огороже..ая частоколом, каждую весну зеленела свежим дёрном, пестрела цветами. (В. Г. Короленко, «Дети подземелья») 5. Кто-то стучал в углу топором, готовя гробик из старых досок, сорва..ых с крыши часовни. (В. Г. Короленко, «Дети подземелья») 6. Очевидно, это была копа..ая канава. (Л. Н. Толстой, «Хозяин и работник») 7. Подошёл он ближе; видит — ульи стоят плетё..ые из соломы, и пчёлы летают, гудят. (Л. Н. Толстой, «Кавказский пленник») Пояснения: фаворит — любимец; хоры — верхняя галерея в церкви (здесь — в старой часовне); прореха — дыра; хорунжий — младший офицерский чин у казаков; черкеска — длинный кафтан; частокол — забор из кольев; дёрн — верхний слой земли с травой.',
  key:'1. Балованное: бал-ова-нн-ое (баловать, несов.) — суффикс -ова-, две н.<br>2. Насиженных: на-сиж-енн-ых (насидеть, сов.) — приставка на-, две н.<br>3. Чищеных: чищ-ен-ых (чистить, несов.) — приставки, -ова- и зависимых слов нет, одна н.<br>4. Огороженная: о-горож-енн-ая (огородить, сов.) — приставка о-, есть и зависимое слово (частоколом), две н.<br>5. Сорванных: со-рв-а-нн-ых (сорвать, сов.) — приставка со-, зависимое слово (с крыши), две н.<br>6. Копаная: коп-а-н-ая (копать, несов.) — примет нет, одна н.<br>7. Плетённые: плет-ённ-ые (плести, несов.) — приставки нет, но есть зависимое слово (из соломы), две н.<br>(Основа в каждом слове — всё, кроме окончания.)<br>Ответ: суффиксы у копаная и сорванных одинаковые (-а- и суффикс с н), а решает приставка со-: она есть только в сорванных.'},
 {n:17,l:2,st:4,task:'Вставить н или нн. В каждом пункте сравнить однокоренные слова: почему их написание совпадает или различается? Назвать примету (или исключение), которая решает дело. В пунктах 6 и 7 объяснить, почему пишутся две н, хотя на первый взгляд приметы нет или она «отменена».',
  body:'1. Больше чем когда-нибудь Борис решился служить впредь не по той писа..ой в уставе, а по этой неписа..ой субординации. (Л. Н. Толстой, «Война и мир») 2. Хотя по нескоше..ому было мало надежды найти столько же, сколько по скоше..ому, Левин обещал Степану Аркадьичу сойтись с ним и пошёл со своим спутником дальше по прокоше..ым и непрокоше..ым полосам. (Л. Н. Толстой, «Анна Каренина») 3. Бабушка вообще очень любила грибы, а грузди в особенности; она любила кушать их жаре..ые в сметане, отварные в рассоле, а всего более солё..ые. (С. Т. Аксаков, «Детские годы Багрова-внука») 4. Белё..ые стены хаты сияли на солнце. — Стены, белё..ые известью к празднику, сияли на солнце. 5. Солдаты почётного караула шли чека..ым шагом. — На монетном дворе нам показали только что отчекане..ую памятную монету. 6. Было тихо, веяло спокойствием и глубоким миром броше..ого кладбища. (В. Г. Короленко, «Дети подземелья») 7. Наверху же, на хорах, уже стояли приведённые прежде — с одной стороны с бритыми полуголовами каторжные, обнаруживавшие своё присутствие позвякиванием цепей, с другой — небритые и незакова..ые подследственные. (Л. Н. Толстой, «Воскресение») Пояснения: субординация — правила подчинения младших по службе старшим; Левин и Степан Аркадьич охотятся на болотную дичь в лугах; полосы — участки луга; грузди — грибы; отварные — сваренные; известь — белое вещество для побелки; каторжные — осуждённые на каторгу; подследственные — те, чьё дело ещё расследуют; хоры — верхняя галерея.',
  key:'1. Писанной (зависимое слово: в уставе) — неписаной (не- приметой не считается, зависимых слов нет): различает зависимое слово.<br>2. Нескошенному, скошенному, прокошенным, непрокошенным — во всех две н: везде есть приставка (с-, про-), а не- перед ней этого не отменяет. Слова употреблены как существительные (по нескошенному лугу), но пишутся по тому же правилу.<br>3. Жаренные (зависимое слово: в сметане) — солёные (примет нет).<br>4. Белёные (примет нет) — белённые (зависимые слова: известью, к празднику).<br>5. Чеканным — исключение, две н без примет; отчеканенную — приставка от-. Написание совпадает, но по разным причинам.<br>6. Брошенного — приставки и зависимых слов нет, но бросить — глагол совершенного вида.<br>7. Незакованные — не- приметой не считается, но за ним стоит приставка за-, она и даёт две н. Небритые — суффикс -т-, вопроса о н или нн нет.'},
 {n:18,l:2,st:4,task:'1) Преобразовать словосочетания. Если в слове одна н — добавить зависимое слово или приставку так, чтобы получилось причастие. Если две н — убрать приставку и зависимые слова, где это возможно, и записать отглагольное прилагательное. Отметить слова, у которых написание после преобразования не изменилось или преобразование невозможно, и объяснить почему. 2) С тремя полученными причастиями составить предложения, в которых причастный оборот стоит после определяемого слова; расставить знаки препинания.',
  obr:'Квашеная капуста → квашенная в бочке капуста (зависимое слово) или заквашенная капуста (приставка) — написание изменилось.',
  body:'Строганые доски, накрахмаленный воротник, клеёная фанера, катаные валенки, обиженный ребёнок, зашифрованное письмо, нехоженая тропа, нечаянная встреча, провяленная на солнце рыба, хвалёный рецепт, толчёные орехи, калёные семечки.',
  key:'1) Например: строганные рубанком (выстроганные) доски; крахмаленый воротник; склеенная из трёх слоёв (клеённая в три слоя) фанера; валенки, катанные вручную; никем не хоженная тропа (не пишется раздельно: у причастия есть зависимое слово); вяленая рыба; расхваленный всеми рецепт; толчённые в ступке орехи; прокалённые на сковороде семечки.<br>Написание не меняется: обиженный ребёнок — без приставки и зависимых слов всё равно две н, обидеть — глагол совершенного вида; шифрованное письмо — без приставки остаётся суффикс -ова-, две н; нечаянная встреча — исключение, две н без примет, одна н невозможна.<br>2) Например: Мы прошли по тропе, никем не хоженной с прошлого лета. Бабушка насыпала семечки, прокалённые на сковороде, в бумажный кулёк. На полу лежали доски, выстроганные отцом.'},
 {n:47,l:2,st:4,task:'Вставить н или нн. Составить таблицу из четырёх граф: слово с пропуском; от какого слова образовано (существительное или глагол); все приметы причастия, которые в нём есть (их может быть несколько), или суффикс прилагательного (-ан-, -ян-, -ин-, -енн-, основа на н), или «примет нет»; н или нн. Ответить: 1) в каком слове не- стоит перед другой приставкой и влияет ли оно на написание? 2) какое слово в 1-м предложении образовано от глагола, но вопроса о н или нн в нём нет? Почему?',
  body:'1. Они въехали в усыпа..ый щебнем и убра..ый цветником двор, на котором два работника обкладывали взрыхлё..ую цветочную клумбу необдела..ыми ноздреватыми камнями, и остановились в крытом подъезде. (Л. Н. Толстой, «Анна Каренина») 2. Старик этот был одет в заплата..ый озям, суко..ые штаны и разноше..ые, заплата..ые бродни. (Л. Н. Толстой, «Воскресение») 3. Они чинно едят траву, выгибая свои лебеди..ые стриже..ые шейки, и, как будто у них тоже есть хвосты, помахивают своими веничками. (Л. Н. Толстой, «Холстомер») 4. Это были короткие дроги с четырьмя столбиками по углам, между которыми очень ловко укладывались снопы в два ряда, укреплё..ые сверху гнётом и крепко привяза..ые верёвками спереди и сзади. (С. Т. Аксаков, «Детские годы Багрова-внука») 5. Тёплая ванна и пузырь со льдом, положе..ый на голову, произвели своё действие. (В. М. Гаршин, «Красный цветок») 6. Я оговариваюсь, потому что настоящий отрывок, выхваче..ый из средины полных и подробных рассказов, может показаться несколько неестестве..ым и преувеличе..ым. (С. Т. Аксаков, «Детские годы Багрова-внука») Пояснения: озям — длинный крестьянский кафтан; бродни — высокие сапоги; они (в 3-м предложении) — годовалые кобылки-стригунки; веничками — короткими хвостиками; дроги — длинная телега без кузова; снопы — связки сжатых колосьев; гнёт — тяжёлая жердь, которую кладут сверху; средина — середина.',
  key:'1. Усыпанный (усыпать; приставка у-, зависимое слово щебнем) — нн; убранный (убрать; приставка у-, зависимое слово цветником) — нн; взрыхлённую (взрыхлить; приставка вз-) — нн; необделанными (обделать; приставка об-) — нн.<br>2. Заплатанный, заплатанные (заплатать; приставка за-) — нн; суконные (сукно: основа сукон- на н + -н-) — нн; разношенные (разносить; приставка раз-) — нн.<br>3. Лебединые (лебедь; суффикс -ин-) — н; стриженые (стричь; примет нет) — н.<br>4. Укреплённые (укрепить; приставка у-, зависимые слова сверху гнётом) — нн; привязанные (привязать; приставка при-, зависимое слово верёвками) — нн.<br>5. Положенный (положить; приставка по-, зависимое слово на голову) — нн.<br>6. Выхваченный (выхватить; приставка вы-, зависимое слово) — нн; неестественным (естество; суффикс -енн-) — нн; преувеличенным (преувеличить; приставка пре-) — нн.<br>Ответы: 1) необделанными: не- стоит перед приставкой об-; не- приметой не считается, но и не отменяет приставку об-, поэтому две н. 2) Крытом (крыть): у него суффикс -т-, а не -н- или -нн-.'},
 {n:19,l:2,st:4,task:'Найти и исправить ошибки в написании н и нн. Объяснить каждое исправление и доказать, что остальные слова с н или нн написаны верно.',
  body:'После ремонта наш стадион не узнать. Обновлённые трибуны с нарисоваными гербами города видны издалека, вокруг поля появились новые прорезиненые дорожки. В субботу здесь прошёл первый матч сезона. Купленые заранее билеты разошлись за неделю, и организованый пропуск зрителей начался ещё в полдень. Ветераны клуба, приглашённые на открытие, сидели в первом ряду, а на перилах расселись незваные гости — воробьи. В буфете продавали бутерброды с варёной и копчённой колбасой. До свистка оставались считаные минуты; тренер ходил вдоль скамейки с деланным спокойствием. После игры победителям вручили серебряные кубки, а судья унёс заполненный капитанами протокол.',
  key:'Ошибки (6): нарисованными — приставка на- и суффикс -ова-; прорезиненные — приставка про-; купленные — глагол совершенного вида (купить), есть и зависимое слово (заранее); организованный — суффикс -ова-; копчёной — примет нет (коптить, несов. в.), одна н; считанные — исключение.<br>Написано верно: обновлённые (приставка об-), приглашённые (приставка при-, зависимое слово), незваные (не- не в счёт, примет нет), варёной (примет нет), деланным (исключение), серебряные (от существительного, суффикс -ян-), заполненный (приставка за-, зависимое слово).'},
 {n:20,l:2,st:5,task:'Тонкость. Вставить н или нн. Определить вид глагола ранить: подставить его в предложения «Вчера осколок … солдата» и «Почти каждый день кого-нибудь …». Объяснить, почему слово от глагола ранить без приставки и зависимых слов пишется с одной н, хотя ранить может быть и глаголом совершенного вида, и когда в нём пишутся две н. Проверить вывод на глаголе контузить (предложения 7–8). Сравнить с глаголами лишить и решить. Объяснить написание остальных слов с пропусками.',
  body:'1. На дне её, ухватясь обеими руками за края, лежал ране..ый. (Л. Н. Толстой, «Рубка леса») 2. Долохов, ране..ый в руку, пешком, с десятком солдат своей роты (он был уже офицер), и его полковой командир, верхом, представляли из себя остатки всего полка. (Л. Н. Толстой, «Война и мир») 3. С батареи свезли пленных, в том числе ране..ого французского генерала, которого окружили офицеры. (Л. Н. Толстой, «Война и мир») 4. С князем Андреем везли присоединившегося к ним в Москве майора его полка Тимохина с красным носиком, ране..ого в ногу в том же Бородинском сражении. (Л. Н. Толстой, «Война и мир») 5. Навстречу ему поднимался поезд телег с ране..ыми во вчерашнем деле. (Л. Н. Толстой, «Война и мир») 6. Ране..ые, обвязанные тряпками, бледные, с поджатыми губами и нахмуре..ыми бровями, держась за грядки, прыгали и толкались в телегах. (Л. Н. Толстой, «Война и мир») 7. Контуже..ого взрывом бойца вынесли с поля боя на руках. 8. Через неделю контуже..ый боец уже помогал санитарам. Пояснения: её (в 1-м предложении) — повозки; Долохов, Тимохин, князь Андрей — герои романа; батарея — позиция с пушками; в деле — в бою; грядки — боковые края телеги; контузить — оглушить ударом или взрывом.',
  key:'Ранить — двувидовой глагол: «вчера осколок ранил солдата» — совершенный вид, «почти каждый день кого-нибудь ранит» — несовершенный. Для таких глаголов примета «совершенный вид» не действует: без приставки и зависимых слов пишется одна н, с зависимым словом или приставкой — две. Лишить и решить — только совершенного вида (несовершенный — лишать, решать), поэтому лишённый, решённый пишутся с двумя н и без приставки.<br>1. Раненый — зависимых слов нет (слово употреблено как существительное). 2. Раненный — зависимое слово (в руку). 3. Раненого — зависимых слов нет: французского относится к слову генерала, а не к причастию. 4. Раненного — зависимое слово (в ногу). 5. Раненными — зависимое слово (во вчерашнем деле), хотя слово употреблено как существительное. 6. Раненые — примет нет; нахмуренными — приставка на-. 7. Контуженного — зависимое слово (взрывом). 8. Контуженый — примет нет: контузить тоже двувидовой глагол.'},
 {n:48,l:2,st:5,task:'Вставить н или нн. Для каждого слова назвать все приметы, которые в нём есть (их может быть несколько), или объяснить, почему пишется одна н. Ответить на вопросы: 1) В каком предложении одно зависимое слово относится сразу к двум причастиям? 2) В каком предложении зависимое слово стоит при слове-исключении и почему оно не влияет на написание? 3) Почему в 4-м предложении не с причастием пишется раздельно (вспомнить правило главы «Причастие»)? 4) Чем слово с одной н в 6-м предложении отличается от двух других слов на -анный в этом предложении?',
  body:'1. Успокое..ая Александра Ивановна ушла к гостям, а я принялся подробно рассказывать матери всё виде..ое и слыша..ое мной. (С. Т. Аксаков, «Детские годы Багрова-внука») 2. Князь Андрей чувствовал себя взволнова..ым, раздражё..ым и вместе с тем сдержанно спокойным, каким бывает человек при наступлении давно жела..ой минуты. (Л. Н. Толстой, «Война и мир») 3. В моей груди, навстречу его угрозам, подымалось едва осозна..ое оскорблё..ое чувство покинутого ребёнка и какая-то жгучая любовь к тем, кто меня пригрел там, в старой часовне. (В. Г. Короленко, «Дети подземелья») 4. К тому же картина, вызва..ая из глубины душевных воспоминаний и не облечё..ая в слово, решительно теряет единство, цельность и оригинальность представления; другие, может быть, этого и не заметят, да я-то знаю очень хорошо. (С. Т. Аксаков, «Детские годы Багрова-внука») 5. Бледное, окаймлё..ое подстриже..ой рыжей бородой лицо его с постоянно сощуре..ыми маленькими глазами было, как каменное, совершенно неподвижно. (Л. Н. Толстой, «Хаджи-Мурат») 6. В его обвязанном шарфе, в его валя..ых сапогах, в его заспа..ом лице ему послышался голос другой жизни, призывавшей его, — жизни трудов, лишений, деятельности. (Л. Н. Толстой, «Казаки») Пояснения: Александра Ивановна — гостья в доме; облечь в слово — выразить словами; окаймить — окружить каймой, обрамить; сощурить — прищурить; валять — делать войлок из шерсти.',
  key:'1. Успокоенная — приставка у-; виденное и слышанное — общее зависимое слово мной (виденное мной и слышанное мной), поэтому в обоих две н.<br>2. Взволнованным — приставка вз- и суффикс -ова-; раздражённым — приставка раз-; желанной — исключение: при нём зависимое слово давно, но желанный и без зависимых слов пишется с двумя н.<br>3. Осознанное — приставка о-, зависимое слово едва; оскорблённое — приставка о-, глагол совершенного вида (оскорбить).<br>4. Вызванная — приставка вы-, зависимые слова; не облечённая — приставка об- (облечь), зависимое слово в слово; не пишется раздельно, потому что при причастии есть зависимое слово.<br>5. Окаймлённое — приставка о-, зависимое слово бородой; подстриженной — приставка под-; сощуренными — приставка со-, зависимое слово постоянно.<br>6. Валяных — примет нет (валять, несов. в.), одна н; заспанном — приставка за-; обвязанном — приставка об-.<br>Ответы: 1) в 1-м; 2) во 2-м (давно желанной); 3) см. п. 4; 4) у валяных нет ни приставки, ни зависимых слов, а у заспанном и обвязанном есть приставки за- и об-.'},
// Урок 3
 {n:49,l:3,st:1,task:'Распределить сочетания по пяти группам: 1) сложное прилагательное, во второй части нет приставки; 2) сложное прилагательное, во второй части есть приставка; 3) повтор с пере-; 4) прилагательное с приставкой; 5) прилагательное с не-. В сложных словах отделить чертой первую часть, в остальных выделить приставку. Для каждой группы записать, сколько н пишется и почему. Сделать вывод: от чего зависит число н в сложном прилагательном.',
  obr:'Малосолёные огурцы → мало|солёные: солить — приставки нет → группа 1, одна н. Свежевыкрашенные перила → свеже|выкрашенные: выкрасить — приставка вы- → группа 2, две н.',
  body:'Свежемороженая клубника, запущенный сад, нечищеные ботинки, свежесваренный суп, стираный-перестираный халат, цельнокроеный рукав, рассеянный взгляд, малоизученная болезнь, неметёный пол, глаженая-переглаженая скатерть, выдержанный сыр, засушенные цветы. Пояснения: цельнокроеный — скроенный из одного куска ткани, без шва.',
  key:'1) Одна н, во второй части нет приставки: свеже|мороженая (морозить), цельно|кроеный (кроить).<br>2) Две н, во второй части приставка: свеже|сваренный (сварить, приставка с-), мало|изученная (изучить, приставка из-).<br>3) Повтор — одна н в обеих частях, хотя во второй части есть пере-: стираный-перестираный, глаженая-переглаженая.<br>4) Прилагательные с приставкой — две н, хотя называют постоянный признак: за-пущенный, рас-сеянный, вы-держанный, за-сушенные.<br>5) С не- — одна н: не-чищеные, не-метёный (не- приметой причастия не считается).<br>Вывод: в сложном прилагательном число н определяет вторая часть — есть ли у неё приставка.'},
 {n:23,l:3,st:2,task:'Вставить пропущенные буквы. Распределить слова с пропусками на две группы: 1) повторы, которые обозначают высокую степень признака; 2) отдельные слова с приставкой. Объяснить, почему приставка пере- в повторе не даёт двух н, а в отдельном слове приставка требует нн.',
  obr:'Штопаные-перештопаные варежки → повтор: одна н в обеих частях. Заштопанные варежки → отдельное слово с приставкой за- → две н.',
  body:'1. По хоже..ым-перехоже..ым тропинкам мы вышли к озеру. 2. Эту тайгу, исхоже..ую ещё в юности, дед знал как свои пять пальцев. 3. В сарае у деда стоял чине..ый-перечине..ый велосипед. 4. Мастер вернул нам почине..ый зонт уже на следующий день. 5. Грузовик свернул на езже..ую-переезже..ую лесную дорогу. 6. Колея, изъезже..ая тракторами, превратилась в канаву. 7. Рыбаки сушили на берегу лата..ые-перелата..ые сети. 8. Мама отыскала в шкафу залата..ые на локтях джинсы. 9. В её сундуках я нашёл пропасть всякого старушечьего хлама, но, перебрав все поношенные чепцы и перештопа..ые чулки, я не нашёл ни денег, ни драгоценных вещей… (А. П. Чехов, «Драма на охоте») Пояснения: пропасть — здесь: очень много; чепец — женский домашний головной убор.',
  key:'1. Хожеными-перехожеными — повтор, одна н в обеих частях. 2. Исхоженную — отдельное слово, приставка ис- → нн. 3. Чиненый-перечиненый — повтор. 4. Починенный — приставка по- → нн. 5. Езженую-переезженую — повтор. 6. Изъезженная — приставка из- (и зависимое слово тракторами) → нн. 7. Латаные-перелатаные — повтор. 8. Залатанные — приставка за- (и зависимое слово на локтях) → нн. 9. Перештопанные — отдельное слово с приставкой пере- → нн (сравнить: штопаные-перештопаные — повтор).<br>Группа 1: 1, 3, 5, 7. Группа 2: 2, 4, 6, 8, 9.<br>Повтор называет один признак в высокой степени (велосипед чинили много раз, по тропинкам ходили очень много): вся пара работает как одно прилагательное, поэтому и во второй части одна н. Отдельное слово с приставкой подчиняется общему правилу: приставка (кроме не-) даёт нн.'},
 {n:22,l:3,st:2,task:'Заменить описательные обороты сложными прилагательными с первой частью мало-, свеже- или домо-. Записать полученные сочетания, отделить чертой первую часть и объяснить, сколько н пишется во второй части. Найти оборот, из которого получается прилагательное совсем без н, и объяснить почему.',
  obr:'Тропа, по которой мало ходят → мало|хоженая тропа: ходить — без приставки → одна н. Пирожки, которые только что испекли → свеже|испечённые пирожки: испечь — приставка ис- → две н.',
  body:'1. Дорога, по которой мало ездят. 2. Рубашка, которую только что выгладили. 3. Скатерть, которую ткали дома. 4. Ель, которую только что срубили. 5. Кроссовки, которые мало носили. 6. Пол, который только что вымыли. 7. Картофель, который только что выкопали. 8. Огурцы, которые солили недолго. 9. Остров, который мало исследовали. 10. Рыба, которую только что выловили.',
  key:'1. Мало|езженая дорога — ездить, приставки нет → н. 2. Свеже|выглаженная рубашка — выгладить, приставка вы- → нн. 3. Домо|тканая скатерть — ткать → н. 4. Свеже|срубленная ель — срубить, приставка с- → нн. 5. Мало|ношеные кроссовки — носить → н. 6. Свеже|вымытый пол — суффикс -т- (вымыть → вымытый): н нет совсем. 7. Свеже|выкопанный картофель — выкопать → нн. 8. Мало|солёные огурцы — солить → н. 9. Мало|исследованный остров — исследовать: приставка ис- и суффикс -ова- → нн. 10. Свеже|выловленная рыба — выловить → нн.<br>Вторая часть сложного слова пишется так же, как отдельное слово: без приставки — одна н, с приставкой — две.'},
 {n:21,l:3,st:2,task:'Вставить пропущенные буквы. Определить, что перед нами: устойчивое сочетание со значением прилагательного или причастие. Доказать: у причастия найти зависимое слово или примету; для слова с одной н объяснить его значение своими словами.',
  obr:'Названые сёстры с детства делились всем. → Названые — устойчивое сочетание: не родные, а принятые как сёстры; одна н. Река, названная в честь первооткрывателя, течёт на север. → Названная — причастие, есть зависимое слово (в честь первооткрывателя); две н.',
  body:'1. На свадьбе посажё..ым отцом невесты был её крёстный. 2. Яблони, посаже..ые дедом, в этом году впервые дали урожай. 3. Смышлё..ый щенок быстро понял, где стоит его миска. 4. В Проще..ое воскресенье принято просить друг у друга прощения. 5. Проще..ая обида быстро забывается. 6. Младшая дочь купца была писа..ая красавица. 7. В гостиной висел портрет прадеда, писа..ый маслом. 8. Ну ладно, уж ладно, верче..ая, — слабо отбивалась от неё старуха. (А. И. Куприн, «Олеся») 9. Монетка, верче..ая в пальцах фокусника, вдруг исчезла. Пояснения: в 1-м предложении речь о человеке, который на свадьбе заменяет невесте родного отца; в 4-м — о последнем воскресенье перед Великим постом; в 8-м старуха так называет внучку-непоседу.',
  key:'1. Посажёным — устойчивое сочетание «посажёный отец», одна н. 2. Посаженные — причастие с зависимым словом (дедом), нн. 3. Смышлёный — устойчивое слово, «сообразительный», одна н. 4. Прощёное — название праздника, устойчивое сочетание, одна н. 5. Прощённая — причастие: простить — совершенный вид, нн. 6. Писаная (красавица) — устойчивое сочетание: «очень красивая, как на картине», одна н. 7. Писанный — причастие с зависимым словом (маслом), нн. 8. Верченая — «вертлявая, непоседливая», значение прилагательного, одна н. 9. Верченная — причастие с зависимым словом (в пальцах), нн.'},
 {n:50,l:3,st:2,task:'Вставить пропущенные буквы. Над каждым словом с пропуском указать приставку, если она есть. Объяснить, почему слово с приставкой пишется с нн, даже когда называет постоянный признак и зависимых слов нет, а слово с не- — с одной н.',
  obr:'Тёсаные брёвна (приставки нет → н) — обтёсанные брёвна (приставка об- → нн) — нетёсаные брёвна (не- приметой не считается → н).',
  body:'1. На полке выстроились гранё..ые стаканы. 2. В углу мастерской стоял потрёпа..ый чемодан. 3. На ветру хлопали рва..ые паруса. 4. К блинам подали топлё..ое масло. 5. Сестра всегда отличалась изыска..ым вкусом. 6. На ужин были котлеты с толчё..ой картошкой. 7. Брат вернулся с рыбалки голодный и взъероше..ый. 8. Немаза..ые колёса телеги противно скрипели. 9. Мама попросила не надевать нестира..ую футболку. 10. В прихожей пахло вяле..ой рыбой. 11. Почтальон вручил нам запечата..ый конверт. 12. После тренировки у вратаря был утомлё..ый вид. 13. К обеду подали кваше..ую капусту.',
  key:'1. Гранёные — н. 2. Потрёпанный — по-, нн. 3. Рваные — н. 4. Топлёное — н. 5. Изысканным — из-, нн. 6. Толчёной — н. 7. Взъерошенный — взъ-, нн. 8. Немазаные — не-, н. 9. Нестираную — не-, н. 10. Вяленой — н. 11. Запечатанный — за-, нн. 12. Утомлённый — у-, нн. 13. Квашеную — н.<br>Приставка (кроме не-) даёт нн и тогда, когда слово стало прилагательным и называет постоянный признак (потрёпанный чемодан, изысканный вкус): так требует правило. Не- приметой причастия не считается, поэтому немазаные, нестираную пишутся так же, как мазаные, стираные.'},
 {n:24,l:3,st:3,task:'Вставить пропущенные буквы. Над каждым словом с пропуском указать приставку, если она есть. Выписать прилагательные с нн и доказать, что это прилагательные, хотя в них две н: называют постоянный признак, зависимых слов при них нет. Объяснить, почему в словах с не- одна н.',
  obr:'И мальчики, приходившие к Ане в гости, обыкновенно в рваных сапогах и в поноше..ых брюках, тоже должны были выслушивать наставления. (А. П. Чехов, «Анна на шее») → Поношенных: приставка по-; слово называет признак (старые, заношенные брюки), зависимых слов нет — это прилагательное, но с приставкой, поэтому нн.',
  body:'1. Представьте вы себе самый маленький в мире зал с некраше..ыми деревянными стенами. (А. П. Чехов, «Драма на охоте») 2. При отчая..ом лае собаки коляска выехала со двора и пошла колыхаться по засохшим кочкам немощё..ого переулка. (И. А. Гончаров, «Обломов») 3. Каждый раз, когда я приходил, Олеся встречала меня с своим привычным сдержа..ым достоинством. (А. И. Куприн, «Олеся») 4. Утончё..ый вкус не удовольствовался бы этими тяжёлыми, неграциозными стульями красного дерева, шаткими этажерками. (И. А. Гончаров, «Обломов») 5. Подушки белели, как снег, и горой возвышались чуть не до потолка; одеяла шёлковые, стёга..ые. (И. А. Гончаров, «Обломов») 6. Я сильно привязался к этому милому животному, с крепкими, тоненькими, точё..ыми ножками, с косматой чёлкой, из-под которой сердито и недоверчиво выглядывали огненные глазки… (А. И. Куприн, «Олеся») 7. Мужчины с поднятыми воротниками пальто и дамы с бледными, заспа..ыми лицами, когда позвонили к чаю, стали спускаться вниз. (А. П. Чехов, «Ариадна») 8. Не хотите ли вы, лучше я велю вам мочё..ой морошки с сахаром подать? (Н. С. Лесков, «Очарованный странник») 9. Всё теперь заслонилось в его глазах счастьем: контора, тележка отца, замшевые перчатки, замасле..ые счёты — вся деловая жизнь. (И. А. Гончаров, «Обломов») Пояснения: удовольствоваться — остаться довольным; этажерка — лёгкая открытая полка-стойка; животное (в 6-м предложении) — лошадка рассказчика; морошка — северная ягода; счёты — прибор для подсчёта с костяшками на прутьях.',
  key:'1. Некрашеными — не- приметой не считается, одна н. 2. Отчаянном — приставка от- (отчаяться), прилагательное, нн; немощёного — не-, одна н. 3. Сдержанным — приставка с-, прилагательное, нн. 4. Утончённый — приставка у-, прилагательное, нн. 5. Стёганые — приставки нет, глагол стегать несовершенного вида, зависимых слов нет, одна н. 6. Точёными — точить, без примет причастия, одна н. 7. Заспанными — приставка за-, прилагательное, нн. 8. Мочёной — мочить, без примет, одна н. 9. Замасленные — приставка за-, нн (сравнить: масленый блин — одна н, урок 1).<br>Прилагательные с нн: отчаянном (лае), сдержанным (достоинством), утончённый (вкус), заспанными (лицами), замасленные (счёты). Они отвечают на вопрос «какой?», называют постоянный признак, зависимых слов нет — но есть приставка, поэтому нн.'},
 {n:51,l:3,st:3,task:'Вставить пропущенные буквы. Указать, от какого глагола образовано слово с пропуском и какого вида этот глагол. Отметить двувидовые глаголы (бывают и совершенного, и несовершенного вида) и объяснить, как это влияет на число н. Найти слово, в котором нн пишется без приставки и без зависимых слов, и объяснить почему.',
  obr:'Раненый лось ушёл в чащу. → Ранить — двувидовой глагол; приставки и зависимых слов нет → одна н. Лось, раненный охотником, ушёл в чащу. → Есть зависимое слово (охотником) → нн.',
  body:'1. Он облизал свою помятую, ране..ую спину и, как ни в чём не бывало, замахал хвостом и залаял на волчиху. (А. П. Чехов, «Белолобый») 2. Зришь сам не знаешь куда, и вдруг пред тобой отколь ни возьмётся обозначается монастырь или храм, и вспомнишь крещё..ую землю и заплачешь. (Н. С. Лесков, «Очарованный странник») 3. Нешто мы некрещё..ые или злодеи какие? (А. П. Чехов, «Злоумышленник») 4. Ране..ая в крыло утка не могла взлететь. 5. Боец, ране..ый в первом же бою, через месяц вернулся в полк. 6. Контуже..ый лётчик долго не слышал ни звука. 7. Сапёра, контуже..ого взрывом, увезли в госпиталь. 8. Младенца, окрещё..ого в старинной церкви, назвали Иваном. 9. Изране..ый осколками танк всё-таки дотянул до своих. 10. На обочине ржавел броше..ый трактор. Пояснения: зришь — смотришь; отколь ни возьмётся — откуда ни возьмись; обозначается — показывается; нешто — разве; контузить — оглушить ударом или взрывом.',
  key:'1. Раненую — ранить (двувидовой), приставки и зависимых слов нет → н. 2. Крещёную — крестить (двувидовой) → н. 3. Некрещёные — не- приметой не считается → н. 4. Раненная — есть зависимое слово (в крыло) → нн. 5. Раненный — есть зависимые слова (в первом же бою) → нн. 6. Контуженый — контузить (двувидовой), без приставки и зависимых слов → н. 7. Контуженного — есть зависимое слово (взрывом) → нн. 8. Окрещённого — приставка о- (и зависимые слова) → нн. 9. Израненный — приставка из- → нн. 10. Брошенный — бросить, только совершенного вида → нн даже без приставки и зависимых слов.<br>Ранить, контузить, крестить — двувидовые: без приставки и зависимых слов от них пишется одна н (раненый, контуженый, крещёный), хотя они бывают и совершенного вида. Примета «совершенный вид» работает только для глаголов, у которых нет второго, несовершенного вида (бросить).'},
 {n:52,l:3,st:3,task:'Прочитать предложения. Выписать все прилагательные и причастия, в которых перед окончанием стоит н или нн после гласной (глиняный, длинный, сделанный), и распределить их в четыре столбика: 1) образованы от существительных; 2) одна н — образованы от глагола, примет причастия нет; 3) нн — с приставкой (кроме не-), в том числе сложные слова с приставкой во второй части; 4) н входит в корень. Существительные не выписывать. Каждое слово объяснить.',
  obr:'Девочка достала из ящика гусиное перо, обёрнутое бумагой. → Гусиное — от существительного гусь, суффикс -ин- (столбик 1). Обёрнутое — суффикс -т-, н нет — не выписывается.',
  body:'1. Затем я вступал с Ярмолой в запутанный, необычайно сложный отвлечённый спор. (А. И. Куприн, «Олеся») 2. И я знал почему-то, что в этом спокойном круге с нечёткими краями притаилась безмолвная, однообразная, таинственная и грозная жизнь, ещё более жуткая и угнетающая, чем бешеный хаос моих сновидений. (А. И. Куприн, «Олеся») 3. Снится ещё Илье Ильичу большая тёмная гостиная в родительском доме, с ясеневыми старинными креслами, вечно покрытыми чехлами, с огромным, неуклюжим и жёстким диваном, обитым полинялым голубым барканом в пятнах, и одним большим кожаным креслом. (И. А. Гончаров, «Обломов») 4. В кухне возле самой печи за засаленным столом сидели Журкин и его жена. (А. П. Чехов, «Барыня») 5. Ниже его горела тем же огнём церковная глава, и лоснился на солнце свежевыкрашенный зелёный купол, а за сверкающим крестом широко расстилалась прозрачная, далёкая синева. (А. П. Чехов, «Драма на охоте») 6. У окна, подёрнутого у краёв ледяными узорами, сидела на табурете его жилица, Анюта, маленькая, худенькая брюнетка лет 25-ти, очень бледная, с кроткими серыми глазами. (А. П. Чехов, «Анюта») 7. Пашка отродясь не ел жареного мяса и, испробовав его теперь, нашёл, что оно очень вкусно. (А. П. Чехов, «Беглец») 8. В одном из углов стояло маленькое корытце, в котором она увидела мочёный горох и размокшие ржаные корки. (А. П. Чехов, «Каштанка») Пояснения: Ярмола — лесник, слуга рассказчика; баркан — плотная шерстяная ткань; глава (церковная) — купол церкви; лосниться — блестеть.',
  key:'1) От существительных: таинственная (таинство, суффикс -енн-), старинными (старина + -н- → нн), кожаным (-ан-), ледяными (-ян-), ржаные (-ан-).<br>2) Одна н: бешеный (бесить — несов. в., примет нет), жареного (жарить), мочёный (мочить).<br>3) Нн с приставкой: запутанный (за-), отвлечённый (от-), засаленным (за-), свежевыкрашенный (сложное слово, во второй части приставка вы-).<br>4) Н в корне: зелёный.<br>Не выписываются: гостиная (существительное); покрытыми, обитым, подёрнутого (суффикс -т-); полинялым (суффикс -л-); огромным, спокойном, безмолвная, однообразная, церковная, прозрачная, бледная (н стоит после согласного, выбора н/нн нет).'},
 {n:25,l:3,st:3,task:'Заполнить таблицу для каждого глагола: 1) отглагольное прилагательное с существительным; 2) то же прилагательное с не-; 3) сложное прилагательное из списка (если подходящего нет — прочерк); 4) причастие с зависимым словом; 5) причастие с приставкой. В каждом слове обозначить причину выбора н или нн. С двумя словами одного глагола составить предложения. Сложные прилагательные для третьего столбика: домотканый, свежевыбеленный, свежескошенный, свежевспаханный.',
  obr:'Красить: крашеный забор — некрашеный забор — гладкокрашеный пол — забор, крашенный в два слоя, — покрашенный забор.',
  body:'Ткать, белить, стричь, косить, пахать, мостить.',
  key:'Ткать: тканый ковёр — нетканый материал — домотканое полотно — ковёр, тканный на станке, — сотканный ковёр.<br>Белить: белёный потолок — небелёный холст — свежевыбеленный потолок — потолок, белённый известью, — побелённый потолок.<br>Стричь: стриженый пудель — нестриженые ногти — прочерк — пудель, стриженный под льва, — подстриженный пудель.<br>Косить: кошеный луг — некошеная трава — свежескошенная трава — луг, кошенный на рассвете, — скошенный луг.<br>Пахать: паханое поле — непаханая земля — свежевспаханное поле — поле, паханное тракторами, — вспаханное поле.<br>Мостить: мощёная улица — немощёный переулок — прочерк — улица, мощённая камнем, — вымощенная улица.<br>Одна н — в первых двух столбиках и в слове домотканый (во второй части нет приставки). Свежевыбеленный, свежескошенный, свежевспаханный — сложные слова, но во второй части приставка (вы-, с-, вс-), поэтому нн. Предложения — свободные.'},
 {n:53,l:3,st:4,task:'Найти и исправить ошибки в написании н и нн. В тексте семь ошибок. Каждое исправление объяснить правилом. Объяснить и верные написания слов с н или нн.',
  body:'Летом мы ездили с классом в небольшой старинный город. В краеведческом музее экскурсовод показала нам домотканные полотенца с вышивкой и портрет молодого офицера, контуженого под Бородином. Рядом висел портрет его названного брата: юноши побратались ещё в кадетском корпусе. Потом мы долго бродили по узким улочкам и вышли к собору со свежевыкрашеными куполами. На площади шла ярмарка: продавали подержанные книги, лоскутные одеяла, малосолёные огурцы и смышлённых щенков. Мой друг купил старую карту в потёртом, латанном-перелатанном футляре и был уверен, что она приведёт его к малоизученым пещерам за рекой.',
  key:'Ошибки: домотканные → домотканые (сложное слово, во второй части нет приставки: ткать); контуженого → контуженного (контузить — двувидовой, но есть зависимое слово под Бородином); названного → названого (устойчивое сочетание «названый брат» — побратим); свежевыкрашеными → свежевыкрашенными (во второй части приставка вы-); смышлённых → смышлёных (устойчивое слово); латанном-перелатанном → латаном-перелатаном (повтор: одна н в обеих частях); малоизученым → малоизученными (во второй части приставка из-).<br>Верно: старинный (старина + -н-), подержанные (приставка под-: прилагательное, но нн), малосолёные (сложное слово без приставки во второй части). Потёртом — суффикс -т-, вопроса о н нет.'},
 {n:54,l:3,st:4,task:'1) Вставить пропущенные буквы и объяснить написание. 2) Каждое слово с пропуском преобразовать тремя способами: а) добавить зависимое слово; б) заменить однокоренным словом с приставкой; в) если возможно, образовать сложное прилагательное с первой частью гладко-, свеже- или прибавить не-. Записать новые сочетания. 3) Объяснить, в каком случае число н не меняется, хотя у слова появилась новая часть.',
  body:'1. Просыпается он в большой комнате с краше..ыми стенами. (А. П. Чехов, «Горе») 2. Ей показалось, что от цветника с тощим, стриже..ым тополем пробиралась к дому какая-то тёмная фигура. (А. П. Чехов, «В потёмках») 3. В кладовой к потолку привешены были окорока, чтоб не портили мыши, сыры, головы сахару, провесная рыба, мешки с сушё..ыми грибами… (И. А. Гончаров, «Обломов») 4. В чашке были печё..ые яйца, ржавые лепёшки на сале, куски чёрного хлеба и ещё что-то… (А. П. Чехов, «Агафья») 5. Зоолог и дьякон сели на скамью около столика, а Самойленко опустился в плетё..ое кресло с широкой, покатой спинкой. (А. П. Чехов, «Дуэль») Пояснения: провесная рыба — провяленная на воздухе; ржавые — здесь: рыжевато-бурые; дьякон — священнослужитель.',
  key:'1) Крашеными, стриженым, сушёными, печёные, плетёное — одна н: образованы от глаголов несовершенного вида без приставки, зависимых слов нет.<br>2) Примерные ответы. 1. а) с крашенными в голубой цвет стенами; б) с выкрашенными (покрашенными) стенами; в) с гладкокрашеными стенами; с некрашеными стенами. 2. а) с тополем, стриженным садовником; б) с подстриженным тополем; в) с нестриженым тополем. 3. а) с сушенными на солнце грибами; б) с высушенными (засушенными) грибами; в) —. 4. а) яйца, печенные в золе; б) испечённые яйца; в) свежеиспечённые яйца. 5. а) кресло, плетённое из лозы; б) сплетённое кресло.<br>3) С зависимым словом и с приставкой — нн. Не меняется число н, если прибавить не- (некрашеными) или первую часть сложного слова к слову без приставки (гладкокрашеными). Свежеиспечённые — нн, потому что вторая часть сама с приставкой (испечь).'},
 {n:55,l:3,st:4,task:'Вставить пропущенные буквы. Распределить слова с пропусками в четыре столбика: 1) прилагательные от существительных; 2) причастия (указать примету: приставка, зависимое слово, совершенный вид); 3) прилагательные с приставкой; 4) сложные прилагательные. Найти причастие, в котором нет ни приставки, ни зависимого слова, и объяснить, почему в нём нн.',
  body:'1. Тут и полуразруше..ые, поросшие мхом гроты, фонтаны, прудики, предназначе..ые для золотой рыбы и ручных карпов, горы, беседки, дорогие оранжереи… (А. П. Чехов, «Драма на охоте») 2. Если бы этот городишко вдруг провалился или сгорел, то телеграмму об этом прочли бы в России с такою же скукой, как объявление о продаже подержа..ой мебели. (А. П. Чехов, «Дуэль») 3. На другой записке тем же самым излома..ым почерком с дли..ыми хвостами и закорючками было написано: «А кто-то в субботу не уедет». (А. П. Чехов, «Дуэль») 4. У них нет этого вот, как у нас, чтоб в шкафах лежала по годам куча старого, изноше..ого платья или набрался целый угол корок хлеба за зиму… (И. А. Гончаров, «Обломов») 5. Ветви сирени, посаже..ые дружеской рукой, дремлют над могилой да безмятежно пахнет полынь. (И. А. Гончаров, «Обломов») 6. Это был не купле..ый, а свой собстве..ый крыжовник, собра..ый в первый раз… (А. П. Чехов, «Крыжовник») 7. Он глядел на мальчика жалкими, растеря..ыми глазами, а его рука, показывавшая прямо в землю, ходила во все стороны. (А. И. Куприн, «Белый пудель») 8. Надворных построек — невысоких, но домовитых — множество, и все они точно слиты из тёмных дубовых брёвен под соломе..ыми крышами. (И. А. Бунин, «Антоновские яблоки») 9. Солнце сверкает сбоку, и дорога, уката..ая после дождей телегами, замаслилась и блестит, как рельсы. (И. А. Бунин, «Антоновские яблоки») Пояснения: грот — пещера; оранжерея — теплица для растений; надворные постройки — сараи, амбары и т. п. во дворе.',
  key:'1) От существительных: длинными (длина + -н-), собственный (суффикс -енн-), соломенными (-енн-).<br>2) Причастия: предназначенные (приставка пред-, зависимое слово для рыбы), посаженные (зависимое слово рукой, совершенный вид), купленный (совершенный вид: купить), собранный (приставка с-, зависимое слово в первый раз), укатанная (приставка у-, зависимые слова телегами, после дождей).<br>3) Прилагательные с приставкой: подержанной, изломанным, изношенного, растерянными — называют постоянный признак, но приставка даёт нн.<br>4) Сложное: полуразрушенные — во второй части приставка раз-, поэтому нн.<br>Без приставки и зависимых слов — купленный: глагол купить совершенного вида, поэтому нн.'},
 {n:56,l:3,st:5,task:'Лингвистическая задача (тонкость). Вставить пропущенные буквы. 1) Объяснить, почему в предложениях 1 и 2 пишется одна н, а в 3–5 — две. 2) Сравнить предложения 6 и 7: ни приставки, ни зависимого слова нет ни там, ни там, а написание разное. Объяснить разницу по значению: что называет слово — постоянный признак или состояние, вызванное действием и связанное с определённым временем? Какое слово в 7-м предложении на это указывает? 3) В предложении 8 найти краткую форму и объяснить, почему в ней одна н при любом значении.',
  body:'1. Ране..ого вынесли из окопа на руках. 2. Тяжелоране..ых отправили в тыл первым эшелоном. 3. Психиатры рассказывают, что один солдат, ране..ый при Ватерлоо, сошёл с ума и впоследствии уверял всех и сам в то верил, что он убит при Ватерлоо… (А. П. Чехов, «Драма на охоте») 4. Вся изране..ая, собака доползла до крыльца. 5. Ране..ый в плечо, капитан не покинул мостика. 6. Ране..ый капитан не покинул мостика. 7. Будучи ране..ым, капитан не покинул мостика. 8. Поверху наши пули летят, а вокруг меня татарские в воду шлёпают, а меня не касаются, и я не знаю: ране.. я или не ране.., но только достиг берега… (Н. С. Лесков, «Очарованный странник») Пояснения: Ватерлоо — место сражения 1815 года; эшелон — железнодорожный состав; мостик — площадка на корабле, откуда управляют судном; татарские — татарские пули.',
  key:'1. Раненого — существительное от прилагательного раненый: ранить — двувидовой глагол, приставки и зависимых слов нет → н. 2. Тяжелораненых — сложное слово, во второй части нет приставки → н. 3. Раненный (при Ватерлоо) — зависимое слово → нн. 4. Израненная — приставка из- → нн. 5. Раненный (в плечо) — зависимое слово → нн.<br>6. Раненый — постоянный признак («капитан с раной»), одна н. 7. Раненным — тонкость: при слове будучи («находясь в состоянии») оно обозначает временное состояние, вызванное действием, и становится причастием → нн (Розенталь). На это указывает будучи.<br>8. Ранен — краткое причастие мужского рода: в краткой форме мужского рода всегда одна н (ранен, как и сделан, решён).'},
// Урок 4
 {n:26,l:4,st:1,task:'Образовать от полных форм краткие формы женского рода и множественного числа. Сначала определить, что перед нами: прилагательное (называет качество) или причастие (на действие указывает зависимое слово). Записать, сколько н в краткой форме и почему.',
  obr:'Бездонная пропасть → пропасть бездонна, пропасти бездонны (прилагательное: дно → бездонный, как в полной форме — нн). Дорога, проложенная через лес → дорога проложена через лес, дороги проложены (причастие, есть зависимое слово: одна н).',
  body:'1. Туманная даль. 2. Юная гимнастка. 3. Бесценная находка. 4. Откровенная беседа. 5. Естественная улыбка. 6. Мужественная девушка. 7. Сдержанная речь. 8. Картина, написанная маслом. 9. Площадь, украшенная флагами. 10. Книга, изданная в прошлом веке. 11. Тропинка, протоптанная ребятами. 12. Станция, построенная к Олимпиаде. 13. Статья, переведённая с английского.',
  key:'Прилагательные — как в полной форме: даль туманна, дали туманны; гимнастка юна, гимнастки юны (н в корне — одна); находка бесценна, находки бесценны; беседа откровенна, беседы откровенны; улыбка естественна, улыбки естественны; девушка мужественна, девушки мужественны; речь сдержанна, речи сдержанны (прилагательное с приставкой: качество речи).<br>Причастия — одна н: картина написана маслом, картины написаны; площадь украшена флагами, площади украшены; книга издана, книги изданы; тропинка протоптана, тропинки протоптаны; станция построена, станции построены; статья переведена, статьи переведены.'},
 {n:27,l:4,st:1,task:'Определить, кратким причастием или кратким прилагательным является каждое слово с н или нн. Доказать: для причастия найти зависимое слово (кем? чем? где? когда?) или назвать действие; для прилагательного подобрать полную форму и найти однородное прилагательное. Найти два предложения с краткой формой мужского рода и объяснить, почему в них одна н, хотя одно из этих слов — прилагательное.',
  obr:'Тетрадь проверена учителем. → Проверена (кем?) учителем — краткое причастие. Тропа длинна и извилиста. → Длинна — краткое прилагательное (длинная тропа), однородное — извилиста.',
  body:'1. Все билеты на спектакль уже проданы. 2. Доводы докладчика убедительны и обоснованны. 3. Требования к участникам обоснованы правилами конкурса. 4. Окрестности города живописны и пустынны. 5. Спортивная площадка огорожена сеткой. 6. Девочка с детства болезненна и худа. 7. Гости приглашены к семи часам. 8. Движения фигуристки легки и непринуждённы. 9. Город основан в двенадцатом веке. 10. Мальчик воспитан и вежлив. 11. Посылка отправлена утром. 12. Птицы распуганы выстрелом.',
  key:'Причастия (одна н): проданы (действие — продали), обоснованы (чем?) правилами, огорожена (чем?) сеткой, приглашены (когда?) к семи часам, основан (когда?) в двенадцатом веке, отправлена (когда?) утром, распуганы (чем?) выстрелом.<br>Прилагательные (как в полной форме — нн): обоснованны (обоснованные доводы; однородное — убедительны), пустынны (пустынные окрестности; живописны), болезненна (болезненная девочка; худа), непринуждённы (непринуждённые движения; легки).<br>Мужской род: 9 — основан (причастие); 10 — воспитан (прилагательное: воспитанный мальчик, однородное — вежлив). В краткой форме мужского рода всегда одна н — и у причастий, и у прилагательных.'},
 {n:28,l:4,st:2,task:'Вставить н или нн. Над каждым словом с пропуском написать: кр. прич. или кр. прил. Объяснить выбор.',
  obr:'Сочинение провере..о учителем. → Проверено (кем?) учителем — краткое причастие, одна н. Девушка умна и образова..а. → Образованна — краткое прилагательное (образованная девушка), однородное — умна: две н.',
  body:'1. Задание выполне..о без единой ошибки. 2. Сестра умна, начита..а и остроумна. 3. Выставка оформле..а учениками художественной школы. 4. Наши планы на лето неизме..ы. 5. Вопросы к экзамену разосла..ы заранее. 6. Решения капитана всегда взвеше..ы и разумны. 7. Мука взвеше..а и разложена по пакетам. 8. Мосты через Неву разведе..ы на ночь. 9. Дороги к посёлку расчище..ы от снега. 10. Стихи этого поэта нежны и проникнове..ы. 11. Окна заклее..ы на зиму. 12. Брат честен, трудолюбив и самоотвержен.',
  key:'1. Выполнено — кр. прич. (выполнили), н. 2. Начитанна — кр. прил. (начитанная), нн. 3. Оформлена — кр. прич. (кем?) учениками, н. 4. Неизменны — кр. прил. (неизменные планы), нн. 5. Разосланы — кр. прич. (когда?) заранее, н. 6. Взвешенны — кр. прил.: «обдуманны», однородное разумны, нн. 7. Взвешена — кр. прич.: муку взвесили на весах, н. 8. Разведены — кр. прич. (когда?) на ночь, н. 9. Расчищены — кр. прич. (от чего?) от снега, н. 10. Проникновенны — кр. прил. (проникновенные стихи), однородное нежны, нн. 11. Заклеены — кр. прич. (на какое время?) на зиму, н. 12. Самоотвержен — кр. прил., но мужской род: одна н (самоотверженный → самоотвержен).'},
 {n:29,l:4,st:2,task:'С каждым словом составить два предложения по подсказкам: в первом слово должно быть кратким причастием (одна н), во втором — кратким прилагательным (две н). Подсказка указывает подлежащее и то, что должно стоять рядом. Записать предложения, обозначить нужное число н и объяснить.',
  obr:'Обдуман(н)ы: а) планы (когда? заранее); б) ответы (каковы? точны и …). → а) Планы обдуманы заранее. б) Ответы точны и обдуманны.',
  body:'1. Организован(н)ы: а) соревнования (кем? советом школы); б) ученики (каковы? дисциплинированны и …). 2. Ограничен(н)ы: а) сроки (чем? приказом); б) его возможности (каковы? = малы). 3. Рассеян(н)а: а) толпа (чем? дождём); б) студентка (какова? забывчива и …). 4. Изыскан(н)ы: а) средства на ремонт (кем? администрацией); б) манеры гостьи (каковы? утончённы и …). 5. Сдержан(н)а: а) атака противника (кем? нашими войсками); б) речь директора (какова? спокойна и …).',
  key:'Например: 1. а) Соревнования организованы советом школы. б) Ученики дисциплинированны и организованны. 2. а) Сроки ограничены приказом. б) Его возможности ограниченны. 3. а) Толпа рассеяна дождём. б) Студентка забывчива и рассеянна. 4. а) Средства на ремонт изысканы администрацией. б) Манеры гостьи утончённы и изысканны. 5. а) Атака противника сдержана нашими войсками. б) Речь директора спокойна и сдержанна.<br>В а) есть зависимое слово, называющее того, кто совершил действие, или чем оно совершено, — краткое причастие, одна н. В б) слово называет качество, стоит в ряду с прилагательными — краткое прилагательное, столько н, сколько в полной форме.'},
 {n:30,l:4,st:3,task:'Вставить пропущенные буквы. Подчеркнуть слово, от которого зависит выбор (дополнение, неопределённую форму глагола, придаточную часть), если оно есть, и объяснить написание. Найти предложение, где одна н пишется при любом значении слова, и объяснить почему.',
  obr:'Мы увере..ы в победе. → Уверены: есть дополнение (в чём?) в победе — значение «убеждены», одна н. Её движения увере..ы и точны. → Уверенны: дополнения нет, слово называет качество (уверенные движения), нн.',
  body:'1. Говорят, что они намере..ы заняться хозяйством, но всё-таки скучно… (А. П. Чехов, «Драма на охоте») 2. Дядечка купил, я в этом увере..а. (А. П. Чехов, «Вишнёвый сад») 3. Но нет в нём чего-то главного, лошадиного, и во время прикидки чувствуется через вожжи, что его руки неувере..ы и неточны. (А. И. Куприн, «Изумруд») 4. Надо понимать, видите ли, что он когда-то, во времена оны, всей душой был преда.. цивилизации, служил ей, постиг её насквозь… (А. П. Чехов, «Дуэль») 5. Собаки этой породы умны, послушны и бесконечно преда..ы. 6. Мы преда..ы своей мечте и не отступим. 7. Её резкость была явно намере..а: она хотела задеть собеседника. 8. Сестра намере..а поступать в медицинский институт. 9. Я хочу, чтоб ты и в глазах света была чиста и безукоризне..а, какова ты в самом деле… (И. А. Гончаров, «Обломов») 10. Скажите ему, что я глубоко оскорбле..а его невежливым поступком! (А. П. Чехов, «Барыня») 11. Вы, знающий, что она в вас по уши влюбле..а, всё ездите и ездите… (А. П. Чехов, «Драма на охоте») Пояснения: прикидка — пробный забег рысака; во времена оны — в давние времена; безукоризненный — такой, что не в чем упрекнуть.',
  key:'1. Намерены — есть неопределённая форма (заняться), значение «собираются»: н. 2. Уверена — есть дополнение (в этом): н. 3. Неуверенны — дополнения нет, качество (неуверенные руки), однородное неточны: нн. 4. Предан — краткая форма мужского рода: одна н при любом значении (к тому же есть дополнение цивилизации). 5. Преданны — дополнения нет, качество (преданные собаки), однородные умны, послушны: нн. 6. Преданы — есть дополнение (чему?) мечте: н. 7. Намеренна — «нарочита, умышленна», нн. 8. Намерена — есть неопределённая форма (поступать): н. 9. Безукоризненна — прилагательное от существительного (без укоризны), как в полной форме: нн. 10. Оскорблена — есть дополнение (чем?) поступком: н. 11. Влюблена — есть дополнение (в кого?) в вас: н.'},
 {n:57,l:4,st:3,task:'Вставить пропущенные буквы. Над каждым словом с пропуском написать: кр. прич. или кр. прил. Доказать: у причастия найти зависимое слово или назвать действие; у прилагательного — подобрать полную форму и найти однородные прилагательные.',
  obr:'Окна были отворе..ы настежь. → Отворены — кр. прич.: окна отворили (действие), зависимое слово настежь; одна н.',
  body:'1. Изба Игната, его сарай, хлев и колодец были окруже..ы высокими сугробами. (А. П. Чехов, «Белолобый») 2. Она так настойчива, непрекло..а! (И. А. Гончаров, «Обломов») 3. Лестница, полы и косяки — всё громадное, прямое и яркое — были выкраше..ы в великолепную жёлтую краску и издавали вкусный запах постного масла. (А. П. Чехов, «Беглец») 4. Пусть Ариадна Григорьевна, как вы говорите, поэтична и возвыше..а, но это не значит, что она должна быть вне законов природы. (А. П. Чехов, «Ариадна») 5. Всё небо усыпа..о весело мигающими звёздами, и Млечный Путь вырисовывается так ясно, как будто его перед праздником помыли и потёрли снегом… (А. П. Чехов, «Ванька») 6. Мужчины в домашнем быту легкомысле..ы, живут умом, а не сердцем, не понимают многого, но женщина всё понимает. (А. П. Чехов, «Дуэль») 7. Два окна, выходившие из дежурной комнаты, были ярко освеще..ы. (А. П. Чехов, «Винт») 8. Платов показывает государю собачку, а там на самом сугибе сдела..а русская надпись: «Иван Москвин во граде Туле». (Н. С. Лесков, «Левша») Пояснения: непреклонный — твёрдый, которого нельзя переубедить; сугиб — сгиб (слово Лескова); во граде — в городе.',
  key:'1. Окружены — кр. прич.: (чем?) сугробами, н. 2. Непреклонна — кр. прил.: непреклонная, однородное настойчива, нн. 3. Выкрашены — кр. прич.: (во что?) в краску, н. 4. Возвышенна — кр. прил.: возвышенная, однородное поэтична, нн. 5. Усыпано — кр. прич.: (чем?) звёздами, н. 6. Легкомысленны — кр. прил.: легкомысленные (суффикс -енн-), нн. 7. Освещены — кр. прич.: окна осветили (действие), обстоятельство ярко, н. 8. Сделана — кр. прич.: надпись сделали (где?) на сугибе, н.'},
 {n:58,l:4,st:3,task:'Выписать из предложений все краткие формы с н или нн в суффиксе вместе с подлежащим и распределить их в два столбика: 1) краткие причастия; 2) краткие прилагательные. Для каждого слова записать полную форму и доказательство. Указать слово, в котором выбора н/нн нет совсем, и объяснить почему. Затем найти полные прилагательные и причастия с н или нн и объяснить их написание по урокам 1–3.',
  obr:'Двери заперты, окна завешены. → Окна завешены — кр. прич.: окна завесили (действие); полная форма завешенные — нн, краткая — н. Заперты — суффикс -т-, не выписывается.',
  body:'1. Войдёшь в залу и не налюбуешься, как симметрически рассажены гости, как смирно и глубокомысленно сидят — за картами. (И. А. Гончаров, «Обломов») 2. Волосы её были не причёсаны, разбросаны по плечам, лицо заспанное, смуглое от сумерек… (А. П. Чехов, «Володя») 3. Но с какой стати она должна быть откровенна со мной? (А. П. Чехов, «Ариадна») 4. Как ни неожиданна и ни экстраординарна была встреча с сумасшедшим, но, тем не менее, скоро она была забыта… (А. П. Чехов, «Драма на охоте») 5. Потом он надел больничное платье; кальсоны были очень коротки, рубаха длинна, а от халата пахло копчёною рыбой. (А. П. Чехов, «Палата № 6») 6. Мой роман в заголовке назван «уголовным»… (А. П. Чехов, «Драма на охоте») Пояснения: симметрически — ровно, в одинаковом порядке; экстраординарный — необычайный; мой роман — рассказчик говорит о своей повести.',
  key:'1) Краткие причастия: гости рассажены (рассадили; полн. рассаженные), волосы причёсаны (причесали; полн. причёсанные), волосы разбросаны (по плечам; полн. разбросанные), роман назван (в заголовке; полн. названный).<br>2) Краткие прилагательные: она откровенна (откровенная), встреча неожиданна (неожиданная, однородное экстраординарна), рубаха длинна (длинная, длина + -н-).<br>Выбора нет: назван — мужской род, в краткой форме мужского рода всегда одна н. Забыта — суффикс -т-, н нет.<br>Полные: заспанное (приставка за- → нн), копчёною (коптить, несов. в., без примет → н). Больничное — н после согласного, выбора нет.'},
 {n:59,l:4,st:3,task:'Найти в каждом предложении полное прилагательное или причастие с нн и перестроить предложение или его часть так, чтобы это слово стало кратким и было сказуемым (во 2-м и 3-м предложениях — вместе с соседним однородным прилагательным). Записать, сколько н в краткой форме, и объяснить. Сравнить: почему в одних кратких формах нн сохраняется, а в других остаётся одна н?',
  obr:'Улицы, засыпанные снегом, опустели. → Улицы засыпаны снегом — кр. прич. (чем?), одна н. Цветы на столе искусственные. → Цветы искусственны — кр. прил. (искусство → -енн-), нн, как в полной форме.',
  body:'1. У него бодрый, здоровый вид, роскошные седые бакены, благовоспитанные манеры и громкий приятный голос. (А. П. Чехов, «Палата № 6») 2. Мать, Екатерина Павловна, когда-то, по-видимому, красивая, теперь же сырая не по летам, больная одышкой, грустная, рассеянная, старалась занять меня разговором о живописи. (А. П. Чехов, «Дом с мезонином») 3. Она шла гордая, самоуверенная, в первый раз чувствуя себя не девочкой, а дамой… (А. П. Чехов, «Анна на шее») 4. Усадьба — небольшая, но вся старая, прочная, окружённая столетними берёзами и лозинами. (И. А. Бунин, «Антоновские яблоки») 5. Наконец, уже совсем в темноте, вваливается ватага охотников в усадьбу какого-нибудь почти незнакомого холостяка-помещика и наполняет шумом весь двор усадьбы, которая озаряется фонарями, свечами и лампами, вынесенными навстречу гостям из дому… (И. А. Бунин, «Антоновские яблоки») 6. Радуясь предстоящему бегу, Изумруд рванулся было вперёд, но, сдержанный сильными руками, поднялся лишь немного на задних ногах… (А. И. Куприн, «Изумруд») Пояснения: бакены (бакенбарды) — полоски волос от висков по щекам; сырая — здесь: полная, рыхлая; лозина — ива; ватага — толпа; Изумруд — рысак.',
  key:'1. Манеры благовоспитанны — кр. прил. (качество), нн. 2. Мать была грустна и рассеянна — кр. прил., нн (рассеянна — черта, однородное грустна). 3. Она была горда и самоуверенна — кр. прил. (самоуверенная), нн. 4. Усадьба окружена столетними берёзами — кр. прич. (чем?), н. 5. Лампы вынесены навстречу гостям — кр. прич. (куда?), н. 6. Изумруд был сдержан сильными руками — кр. прич. (чем?), мужской род, н.<br>Прилагательное в краткой форме сохраняет нн полной формы (благовоспитанны, рассеянна, самоуверенна); у причастия в краткой форме одна н (окружена, вынесены); в мужском роде одна н всегда (сдержан). Грустна, горда — однородные прилагательные без н/нн в суффиксе.'},
 {n:60,l:4,st:4,task:'Найти и исправить ошибки в написании н и нн. В тексте шесть ошибок. Каждое исправление объяснить; объяснить и верные написания кратких форм.',
  body:'Школьная спартакиада подготовленна советом старшеклассников. Расписание соревнований вывешено в холле ещё в понедельник. Утро выдалось безветреное, но прохладное. Беговые дорожки стадиона ровны и гладки, трибуны заполненны болельщиками. Выступления наших гимнасток были вдохновенны и безупречны. Зато прыгуны в длину оказались невнимательны и дважды заступили за планку. Итоги финала были объявленны судьёй только к вечеру и оказались неожиданными для всех. Победителям вручили грамоты, подписаные директором, и кубок, изготовленный руками выпускников. Все участники были награждены памятными значками, а праздник получился по-настоящему торжественым.',
  key:'Ошибки: подготовленна → подготовлена (кр. прич., есть зависимое слово советом); безветреное → безветренное (приставка без-, урок 1); заполненны → заполнены (кр. прич., чем? болельщиками); объявленны → объявлены (кр. прич., кем? судьёй); подписаные → подписанные (полное причастие: приставка под-, зависимое слово директором); торжественым → торжественным (суффикс -енн-).<br>Верно: вывешено (кр. прич., н), вдохновенны (кр. прил., вдохновенные выступления, однородное безупречны, нн), неожиданными (исключение, нн), изготовленный (приставка, зависимое слово), награждены (кр. прич., чем? значками).'},
 {n:61,l:4,st:4,task:'Вставить пропущенные буквы в парах предложений. В каждой паре объяснить, почему слово пишется по-разному: найти зависимое слово, указывающее на действие, или однородные прилагательные, указывающие на качество. Для двух пар (по выбору) составить свою пару предложений с другим словом.',
  body:'1. а) Нет, друг мой, к несчастью людей, женщины не могут быть соверше..ы! (А. П. Чехов, «Драма на охоте») б) Ошибка соверше..а по невнимательности. 2. а) В следующие за тем дни он убедился, что его учительница барышня милая, серьёзная и аккуратная, но что она очень необразова..а и учить взрослых не умеет… (А. П. Чехов, «Дорогие уроки») б) Комиссия образова..а приказом директора. 3. а) Вещи уже собра..ы в дорогу. б) Перед стартом пловцы молчаливы и собра..ы. 4. а) Сроки сдачи проекта определе..ы ещё в сентябре. б) Ответы свидетеля уклончивы и неопределё..ы. 5. а) Чаши весов уравновеше..ы гирями. б) Старшая сестра спокойна и уравновеше..а.',
  key:'1. а) Совершенны — кр. прил. (совершенные, «безупречные»), нн; б) совершена — кр. прич. (ошибку совершили; по невнимательности), н. 2. а) Необразованна — кр. прил. (необразованная), нн; б) образована — кр. прич. (чем?) приказом, н. 3. а) Собраны — кр. прич. (куда?) в дорогу, н; б) собранны — кр. прил. («сосредоточенны, подтянуты»), однородное молчаливы, нн. 4. а) Определены — кр. прич. (сроки определили, когда?), н; б) неопределённы — кр. прил., однородное уклончивы, нн. 5. а) Уравновешены — кр. прич. (чем?) гирями, н; б) уравновешенна — кр. прил. (черта характера), однородное спокойна, нн. Свои пары — свободные.'},
 {n:62,l:4,st:4,task:'1) Вставить пропущенные буквы и объяснить написание по правилам уроков 1–4. 2) Выписать краткие формы с н или нн в суффиксе вместе с подлежащим и указать, причастие это или прилагательное. 3) В первом предложении расставить пропущенные запятые и объяснить их.',
  body:'1. Гримасы его странны и болезне..ы, но тонкие черты положе..ые на его лицо глубоким искренним страданием разумны и интеллигентны, и в глазах тёплый, здоровый блеск. (А. П. Чехов, «Палата № 6») 2. Эти слова, простые и обыкнове..ые, были сказа..ы простым человеческим языком, но Огнев в сильном смущении отвернулся от Веры, поднялся и вслед за смущением почувствовал испуг. (А. П. Чехов, «Верочка») 3. Сосредоточе..ые, неподвижные, с лицами, окраше..ыми в зелёный цвет от абажуров, они напоминали сказочных гномов или, чего боже избави, фальшивых монетчиков… (А. П. Чехов, «Винт») 4. Просто всё как будто каким-нибудь волшебством здесь переменилось: всё подновле..о, словно изба, к празднику убра..ая, а флигеля, где Груша жила, и следа нет: срыт, и на его месте новая постройка поставле..а. (Н. С. Лесков, «Очарованный странник») Пояснения: чего боже избави — не дай бог; монетчик — тот, кто чеканит фальшивые монеты; подновлено — обновлено, приведено в порядок; флигель — небольшая постройка рядом с главным домом.',
  key:'1) 1. Болезненны — кр. прил. (болезненные гримасы, суффикс -енн-), нн; положенные — полное причастие (приставка по-, зависимые слова). 2. Обыкновенные — прилагательное (суффикс -енн-), нн; сказаны — кр. прич., (чем?) языком, н. 3. Сосредоточенные — прилагательное с приставкой, нн; окрашенными — причастие (приставка о-, зависимые слова), нн. 4. Подновлено — кр. прич., н; убранная — полное причастие (приставка у-, зависимое слово к празднику), нн; поставлена — кр. прич., н.<br>2) Гримасы странны и болезненны — кр. прил.; слова сказаны — кр. прич.; всё подновлено — кр. прич.; постройка поставлена — кр. прич. (Разумны, интеллигентны — кр. прил. без н/нн в суффиксе; срыт — кр. прич. с суффиксом -т-: не выписываются.)<br>3) Тонкие черты, положенные на его лицо глубоким искренним страданием, разумны… — причастный оборот стоит после определяемого слова (черты) и обособляется.'},
 {n:63,l:4,st:5,task:'Лингвистическая задача (тонкость). Вставить пропущенные буквы. 1) Сравнить предложения 1 и 7: в обоих краткая форма стоит в ряду однородных членов и называет признак, а не действие. Почему же в 1-м — одна н, а в 7-м — две? 2) К кратким формам из предложений 1, 2, 4 подобрать полные и объяснить, почему в полной форме нн. 3) Сформулировать правило: какие краткие формы прилагательных с приставкой пишутся с одной н, как причастия, и почему такие слова нельзя проверить вопросом «каков?». 4) Составить предложения с полной и краткой формой слова заплаканный.',
  body:'1. Платье её, в отношении к нарядной шали и парадному чепцу, казалось старо и поноше..о. (И. А. Гончаров, «Обломов») 2. Лица заплака..ы, но это не мешает им улыбаться. (А. П. Чехов, «Детвора») 3. Девочка подняла на маму заплака..ые глаза. 4. Превосходство команды-победительницы общепризна..о. 5. Ира — общепризна..ый лидер класса. 6. В шкафу висело поноше..ое пальто. 7. Отношения между нашими школами давно дружестве..ы. Пояснения: в отношении к — по сравнению с; чепец — женский головной убор.',
  key:'1. Поношено — особый случай: прилагательное с приставкой (поношенное платье), но в краткой форме одна н, как у причастия. 2. Заплаканы — особый случай: заплаканные лица → лица заплаканы. 3. Заплаканные — полная форма, приставка за- → нн. 4. Общепризнано — особый случай: общепризнанное превосходство → превосходство общепризнано. 5. Общепризнанный — полная форма, сложное слово, во второй части приставка при- → нн. 6. Поношенное — полная форма, приставка по- → нн. 7. Дружественны — краткое прилагательное от дружественный (суффикс -енн-, урок 1): нн, как в полной форме.<br>1) Дружественны — прилагательное от существительного (дружество): у него краткая форма всегда сохраняет нн. Поношено — прилагательное, образованное от глагола с приставкой (поносить): его краткая форма совпадает с формой причастия (платье поношено = его поносили), поэтому одна н, хотя смысл — признак.<br>2) Поношенное, заплаканные, общепризнанное — приставки по-, за-, при- → нн.<br>3) Особые случаи — немногие отглагольные прилагательные с приставкой (поношено, заплаканы, общепризнано): в краткой форме одна н, вопрос «каков?» к ним подходит, но не решает; их написание запоминают и проверяют по словарю.<br>4) Например: Он вытер заплаканное лицо. — Её лицо было заплакано.'},
 {n:64,l:4,st:5,os:'диктант',task:'Выборочно-распределительный диктант. Текст читает учитель или родитель. Записать только прилагательные и причастия с н или нн после гласной в суффиксе, вместе с определяемыми словами (краткие формы — с подлежащим), в два столбика: 1) краткие формы; 2) полные формы. Объяснить написание каждого слова. Затем: 1) объяснить, почему «не убранная» пишется раздельно и с нн; 2) от двух полных причастий (по выбору) образовать краткие формы женского рода и составить с ними предложения.',
  body:'Коридорные часы сипло пробили два пополудни, а в номерке ещё не было убрано. Скомканное одеяло, разбросанные подушки, книги, платье, большой грязный таз, наполненный мыльными помоями, в которых плавали окурки, сор на полу — всё, казалось, было свалено в одну кучу, нарочно перемешано, скомкано… (А. П. Чехов, «Анюта») По стенам, около картин, лепилась в виде фестонов паутина, напитанная пылью; зеркала, вместо того чтоб отражать предметы, могли бы служить скорее скрижалями для записывания на них по пыли каких-нибудь заметок на память. На диване лежало забытое полотенце; на столе редкое утро не стояла не убранная от вчерашнего ужина тарелка с солонкой и с обглоданной косточкой да не валялись хлебные крошки. Если б не эта тарелка, да не прислонённая к постели только что выкуренная трубка, или не сам хозяин, лежащий на ней, то можно было бы подумать, что тут никто не живёт — так всё запылилось, полиняло и вообще лишено было живых следов человеческого присутствия. (И. А. Гончаров, «Обломов») Пояснения: номерок — маленькая комната в меблированных комнатах; помои — грязная вода; фестоны — зубчатые или волнистые узоры по краю; скрижали — здесь: доски для записей.',
  key:'1) Краткие формы (краткие причастия, одна н): (в номерке) было убрано, всё было свалено, перемешано, скомкано; (всё) лишено было.<br>2) Полные формы (нн): одеяло скомканное, подушки разбросанные, таз наполненный, паутина напитанная, тарелка (не) убранная, косточкой обглоданной, трубка прислонённая, трубка выкуренная — все с приставками (с-, раз-, на-, у-, об-, при-, вы-), многие и с зависимыми словами.<br>Не выписываются: забытое (суффикс -т-), хлебные (н после согласного), картин, паутина (существительные).<br>1) Не убранная (от вчерашнего ужина) — у причастия есть зависимые слова, поэтому не пишется раздельно; нн — приставка у- и зависимое слово.<br>2) Например: тарелка убрана; трубка выкурена; паутина напитана пылью.'},
// Урок 5
 {n:31,l:5,st:1,task:'От данных слов образовать сначала прилагательное (или причастие), а от него — наречие на -о. Записать цепочкой, в прилагательном обозначить суффикс. Объяснить, почему в наречии столько же н, сколько в прилагательном. С пятью наречиями составить словосочетания «глагол + наречие».',
  obr:'Восторг → восторж-енн-ый → восторженно: смотрел восторженно (в прилагательном суффикс -енн-, поэтому и в наречии две н).',
  body:'Церемония (с приставкой бес-), болезнь, жизнь (с приставкой без-), чин, закон, стекло, путать, учить, отчаяться, насторожиться, умилить, восхитить, возбудить, обидеть.',
  key:'Церемония → (бес)церемон-н-ый → бесцеремонно (основа на н + суффикс -н-: две н); болезнь → болезн-енн-ый → болезненно (-енн-); жизнь → (без)жизн-енн-ый → безжизненно (-енн-); чин → чин-н-ый → чинно (основа на н + -н-); закон → закон-н-ый → законно (то же); стекло → стекл-янн-ый → стеклянно (исключение: две н); путать → пута-н-ый → путано (отглагольное прилагательное без приставки и зависимых слов: одна н); учить → уч-ён-ый → учёно (то же: одна н); отчаяться → отчая-нн-ый → отчаянно (есть приставка от-: две н); насторожиться → насторож-енн-ый → настороженно (приставка на-); умилить → умил-ённ-ый → умилённо (глагол совершенного вида); восхитить → восхищ-ённ-ый → восхищённо (сов. вид); возбудить → возбужд-ённ-ый → возбуждённо (сов. вид); обидеть → обиж-енн-ый → обиженно (сов. вид).<br>Наречие образовано от прилагательного с помощью суффикса -о; суффикс прилагательного (-н-, -енн-, -янн-) переходит в наречие целиком, поэтому н в наречии столько же, сколько в прилагательном.<br>Словосочетания — например: бесцеремонно перебил, чинно поклонился, путано объяснял, восхищённо ахнул, настороженно прислушался.'},
 {n:65,l:5,st:1,task:'Выписать из предложений наречия, в которых пишется н или нн, и рядом — прилагательное, от которого образовано каждое наречие. Подчеркнуть в наречии н или нн. Краткие причастия и прилагательные (они бывают сказуемыми и тоже оканчиваются на -о, -а, -ы) не выписывать. В одном предложении наречия на правило нет.',
  obr:'Дождь лил беспрестанно, и дорога была размыта. → Беспрестанно (беспрестанный). Размыта — краткое причастие (сказуемое), не выписывается.',
  body:'1. Младший брат сонно потёр глаза и снова уткнулся в подушку. 2. Команда мужественно отыгрывалась до последней минуты матча. 3. Экскурсовод рассказывал вдохновенно, и никто его не перебивал. 4. Огни города туманно расплывались за мокрым окном автобуса. 5. Решение задачи было найдено мгновенно. 6. Бабушка неизменно встречала нас пирогами. 7. Судья временно остановил игру: на поле выбежала собака. 8. Окна в классе вымыты, парты расставлены, всё подготовлено к первому сентября. 9. Альпинисты напряжённо всматривались в облака над перевалом. 10. Мы искренне обрадовались, когда друг вернулся из больницы. 11. Площадь украшена флагами, на ней торжественно звучит оркестр. 12. Кот самоуверенно разлёгся посреди кухни.',
  key:'1. Сонно (сонный). 2. Мужественно (мужественный). 3. Вдохновенно (вдохновенный). 4. Туманно (туманный). 5. Мгновенно (мгновенный); найдено — краткое причастие. 6. Неизменно (неизменный). 7. Временно (временный). 8. Наречий на правило нет: вымыты, расставлены, подготовлено — краткие причастия (сказуемые). 9. Напряжённо (напряжённый). 10. Искренне (искренний) — наречие на -е. 11. Торжественно (торжественный); украшена — краткое причастие. 12. Самоуверенно (самоуверенный). Во всех наречиях две н, как в прилагательных.'},
 {n:32,l:5,st:2,task:'Вставить пропущенные буквы. Над каждым словом с пропуском указать: наречие (отвечает на вопрос «как?», относится к глаголу) или краткое причастие (сказуемое; к нему можно задать вопрос «что сделано?», часто есть зависимое слово «кем? чем?»). Объяснить написание. Найти пары однокоренных слов, которые пишутся по-разному, и объяснить разницу.',
  obr:'Всё имущество растеря..о при переезде. — Малыш растеря..о оглядывался. → Растеряно — кр. прич.: имущество (что сделано?) растеряно, одна н. Растерянно — наречие: оглядывался (как?) растерянно, от растерянный, две н.',
  body:'1. Внимание всего класса сосредоточе..о на опыте с магнитом. 2. Туристы шли организова..о, никто не отставал. 3. Котёнок испуга..о выглянул из-под дивана. 4. Обещание, данное тренеру, сдержа..о. 5. Горло раздраже..о дымом от костра. 6. Шахматист сосредоточе..о смотрел на доску. 7. Облако дыма постепенно рассея..о ветром. 8. Соревнование организова..о школьным спортклубом. 9. Сосед раздражё..о хлопнул дверью. 10. Стадо испуга..о грозой и сбилось в кучу. 11. Ученик рассея..о слушал объяснение и смотрел в окно. 12. Капитан сдержа..о поблагодарил болельщиков.',
  key:'1. Сосредоточено — кр. прич. (внимание что сделано? сосредоточено на опыте): одна н. 2. Организованно — нареч. (шли как?), от организованный: две н. 3. Испуганно — нареч. (выглянул как?). 4. Сдержано — кр. прич. (обещание сдержано). 5. Раздражено — кр. прич. (раздражено чем? дымом). 6. Сосредоточенно — нареч. (смотрел как?). 7. Рассеяно — кр. прич. (рассеяно чем? ветром). 8. Организовано — кр. прич. (организовано кем? спортклубом). 9. Раздражённо — нареч. (хлопнул как?). 10. Испугано — кр. прич. (испугано чем? грозой). 11. Рассеянно — нареч. (слушал как?). 12. Сдержанно — нареч. (поблагодарил как?).<br>Однокоренные пары с разным написанием — все шесть: сосредоточено — сосредоточенно, организовано — организованно, испугано — испуганно, сдержано — сдержанно, раздражено — раздражённо, рассеяно — рассеянно. В кратком причастии одна н, в наречии — столько, сколько в полном прилагательном (две).'},
 {n:74,l:5,st:2,task:'Заменить сочетания «глагол + с + существительное» сочетаниями «глагол + наречие» с тем же значением и записать их. Указать прилагательное, от которого образовано каждое наречие, и объяснить, сколько в нём н. Внимание: не все наречия здесь пишутся с нн — в нескольких на стыке одна н или н нет совсем; распределить наречия на три группы.',
  obr:'Ответил с обидой → ответил обиженно (обиженный: от глагола совершенного вида обидеть — две н).',
  body:'Говорил с убеждением, спорил с ожесточением, вздохнул с облегчением, переспросил с недоумением, ответил с упрёком, слушал с упоением, взглянул с сочувствием, держался с надменностью, оглянулся с тревогой, вёл себя с достоинством, ждал с нетерпением, поклонился с почтением, посмотрел с подозрением, отозвался с уважением, молился с благоговением.',
  key:'Две н: говорил убеждённо (убеждённый, от убедить — сов. вид); спорил ожесточённо (ожесточённый); вздохнул облегчённо (облегчённый); переспросил недоумённо (недоумённый); ответил укоризненно (укоризненный, суффикс -енн-); слушал упоённо (упоённый); взглянул сочувственно (сочувственный, -енн-); держался надменно (надменный, -енн-).<br>Одна н: оглянулся тревожно (тревожный: корень тревож- + суффикс -н-); вёл себя достойно (достойный: суффикс -н- после й); поклонился почтительно (почтительный: суффикс -тельн-); посмотрел подозрительно (подозрительный); отозвался уважительно (уважительный); молился благоговейно (благоговейный: суффикс -н- после й).<br>Без н на стыке: ждал нетерпеливо (нетерпеливый: суффикс -лив-).'},
 {n:33,l:5,st:3,task:'Переписать, вставляя пропущенные буквы. Над каждым наречием указать прилагательное, от которого оно образовано. В двух предложениях есть краткие причастия — найти их и объяснить, почему в них одна н.',
  obr:'Женщина озабоче..о и молча раскладывала карты. (М. Горький, «Мои университеты») → Озабоченно (озабоченный): раскладывала как? — наречие, две н.',
  body:'1. Говорил мало, сдержа..о, ждал вопросов, отвечал точно и обдума..о. (Ф. М. Достоевский, «Братья Карамазовы») 2. Я люблю, люблю восторже..о, беше..о, безумно! (Ф. М. Достоевский, «Бедные люди») 3. Вчерашний дождь перестал совсем, но было мокро, сыро и ветре..о. (Ф. М. Достоевский, «Бесы») 4. Иные шли медле..о и степе..о, другие — торопливо застёгивая на ходу полушубки. (М. Горький, «Мать») 5. Лицо у него постепе..о бурело, тёмные глаза изумлё..о расширялись. (М. Горький, «В людях») 6. Кто б ни был ты, увере..о / В калитку деревенскую / Стучись! (Н. А. Некрасов, «Кому на Руси жить хорошо») 7. От нас через стол, шагах в пяти, обедали два господина и оживлё..о разговаривали. (Ф. М. Достоевский, «Подросток») 8. Небесный свод, горящий славой звёздной, / Таинстве..о глядит из глубины, — / И мы плывём, пылающею бездной / Со всех сторон окруже..ы. (Ф. И. Тютчев, «Как океан объемлет шар земной…») 9. Всё, что я читал, было насыще..о идеями христианства, гуманизма, воплями о сострадании к людям, — об этом же красноречиво и пламе..о говорили лучшие люди, которых я знал в ту пору. (М. Горький, «Мои университеты») Пояснения: степенно — неторопливо, с достоинством; бурело — становилось тёмно-красным; свод — здесь: небо; гуманизм — человеколюбие.',
  key:'1. Сдержанно (сдержанный), обдуманно (обдуманный). 2. Восторженно (восторженный), бешено (бешеный — одна н). 3. Ветрено (ветреный — исключение, одна н). 4. Медленно (медленный — исключение, две н), степенно (степенный: основа степен- + -н-). 5. Постепенно (постепенный), изумлённо (изумлённый). 6. Уверенно (уверенный). 7. Оживлённо (оживлённый). 8. Таинственно (таинственный, -енн-); окружены — краткое причастие (окружены чем? бездной; сказуемое): одна н. 9. Насыщено — краткое причастие (насыщено чем? идеями): одна н; пламенно (пламенный: основа пламен- + -н-) — наречие, говорили как?'},
 {n:66,l:5,st:3,task:'Вставить пропущенные буквы. Распределить сочетания в два столбика: наречия с одной н и наречия с двумя. В скобках записать прилагательное, от которого образовано наречие, и объяснить, почему в нём одна или две н.',
  obr:'Багря..о пылал закат → багряно (багряный: н входит в корень, суффикса -н- нет — одна н).',
  body:'Пря..о пахло корицей; рья..о взялся за уборку; мудрё..о выражался; жема..о поджала губы; рва..о дышал после бега; неслыха..о повезло; единстве..о верное решение; румя..о светились яблоки в листве; беспреста..о звонил телефон; солё..о пахло морем; деревя..о звучал голос; самоотверже..о спасал людей; огне..о сверкнули глаза; стеснё..о дышал в душной комнате.',
  key:'Одна н: пряно (пряный: н входит в корень, суффикса -н- нет); рьяно (рьяный: то же); румяно (румяный: то же); мудрёно (мудрёный: отглагольное прилагательное без приставки и зависимых слов); рвано (рваный: от рвать, без примет причастия); солёно (солёный: то же).<br>Две н: жеманно (жеманный — исключение); неслыханно (неслыханный — исключение); единственно (единственный, -енн-); беспрестанно (беспрестанный: от перестать — есть приставка); деревянно (деревянный — исключение среди слов на -ян-); самоотверженно (самоотверженный: от отвергнуть, есть приставка); огненно (огненный, -енн-); стеснённо (стеснённый: от стеснить — сов. вид).'},
 {n:71,l:5,st:3,task:'Перестроить предложения по образцу: вместо краткого причастия употребить наречие при глаголе, данном в скобках. Записать оба предложения, вставляя пропущенные буквы. Объяснить, почему написание меняется. В последних двух предложениях сделать наоборот: наречие заменить кратким причастием с зависимым словом.',
  obr:'Публика озадаче..а вопросом. (переглянулась) → Публика озадачена вопросом (кр. прич., одна н). — Публика озадаченно переглянулась (наречие, как в слове озадаченный, — две н).',
  body:'1. Малышка обрадова..а подарком. (засмеялась) 2. Зрители разочарова..ы концовкой фильма. (вздохнули) 3. Девочка увлече..а рисованием. (рисовала) 4. Жители возмуще..ы шумом стройки. (обсуждали) 5. Путники утомле..ы долгой дорогой. (брели) 6. Гостья смуще..а комплиментом. (улыбнулась) 7. Бабушка удивле..а поздним звонком. (переспросила) 8. Собака встревоже..а шорохом. (залаяла) 9. Болельщики воодушевле..ы победой. (запели) 10. Мама огорче..а плохой отметкой сына. (покачала головой) 11. Сестра растеря..о молчала. (… новостью) 12. Капитаны увере..о пожали друг другу руки. (… в победе)',
  key:'1. Обрадована — обрадованно засмеялась. 2. Разочарованы — разочарованно вздохнули. 3. Увлечена — увлечённо рисовала. 4. Возмущены — возмущённо обсуждали. 5. Утомлены — утомлённо брели. 6. Смущена — смущённо улыбнулась. 7. Удивлена — удивлённо переспросила. 8. Встревожена — встревоженно залаяла. 9. Воодушевлены — воодушевлённо запели. 10. Огорчена — огорчённо покачала головой. 11. Растерянно молчала — Сестра растеряна новостью. 12. Уверенно пожали — Капитаны уверены в победе.<br>Краткое причастие (сказуемое, есть зависимое слово «чем?», «в чём?») пишется с одной н; наречие отвечает на вопрос «как?» при глаголе и пишется с двумя н, как полное прилагательное (обрадованный, разочарованный, увлечённый…).'},
 {n:68,l:5,st:3,task:'Разобрать наречия по составу: выделить приставку, корень, суффиксы (окончания у наречия нет). Объяснить, откуда в каждом слове одна или две н, и распределить слова по группам: а) основа на н + суффикс -н-; б) суффикс -енн-, -онн-; в) слово-исключение; г) отглагольное прилагательное с суффиксом -н- (одна н) или причастие с суффиксом -нн-, -енн- (две н); д) н входит в корень.',
  obr:'Длинно (говорил длинно) → длин-н-о: корень длин- оканчивается на н, к нему прибавлен суффикс -н-, затем -о; две н — группа а.',
  body:'Сонно (сонно зевал), картинно (картинно поклонился), письменно, традиционно, учёно, растерянно, утомлённо, нечаянно, юно.',
  key:'Сон-н-о — а (основа сон- + суффикс -н-). Картин-н-о — а (картина + -н-). Письм-енн-о — б (-енн-). Традици-онн-о — б (-онн-). Уч-ён-о — г (учёный: без приставки, одна н). Рас-тер-я-нн-о — г (растерянный: есть приставка, две н). Утомл-ённ-о — г (утомлённый: от глагола сов. вида утомить, две н). Не-ча-я-нн-о — в (нечаянный — исключение: две н без примет; приставка не- приметой не считается). Юн-о — д (н входит в корень: юный).<br>Во всех словах последний суффикс -о — суффикс наречия.'},
 {n:67,l:5,st:4,task:'Переписать, вставляя пропущенные буквы. Выписать в два столбика: 1) наречия на -о (с прилагательным, от которого они образованы); 2) краткие причастия — вместе с подлежащим, если оно есть. Доказать, что слова второго столбика — причастия: задать вопрос «что сделано?» или найти зависимое слово «кем? чем?». Остальные слова с пропусками объяснить по правилам уроков 1–4.',
  obr:'Рукопись была исправле..а, и автор удовлетворё..о кивнул. → Исправлена — кр. прич. (рукопись что сделана? исправлена): одна н. Удовлетворённо — наречие (кивнул как?), от удовлетворённый: две н.',
  body:'1. Всё это сдела..о, одето, раскраше..о и размеще..о умело и искус..о, и кажется, что всё живёт и шумит. (М. Горький, «Сказки об Италии») 2. Оно было писа..о тёмным и запута..ым слогом. (А. С. Пушкин, «История Пугачёва») 3. Немедле..о доставле..о было калмыкам вспоможение юртами, скотом, одеждою и хлебом. (А. С. Пушкин, «История Пугачёва») 4. Все скоро уложе..о было у нас, / И утром, ни с кем не прощаясь, / Мы тронулись в путь. (Н. А. Некрасов, «Русские женщины») 5. Этой нитью всё связа..о, всё оплете..о, незримой крепостью её и держится на веки вечные государево царство. (М. Горький, «Мои университеты») 6. У Грушницкого растрёпа..ая причёска и отчая..ый вид; он, кажется, в самом деле огорчён, особе..о самолюбие его оскорбле..о; но ведь есть же люди, в которых даже отчаяние забавно!.. (М. Ю. Лермонтов, «Герой нашего времени») Пояснения: оно — здесь: письмо, воззвание; слог — манера письма; вспоможение — помощь; юрта — переносное жилище кочевников; калмыки — кочевой народ.',
  key:'1. Сделано, раскрашено, размещено — кр. прич. (всё что сделано? сделано, раскрашено, размещено); одето — тоже краткое причастие, но с суффиксом -т-; искусно — наречие (размещено как?), от искусный: суффикс -н- после корня искус-, одна н; умело — наречие без н на стыке.<br>2. Писано — кр. прич. (оно что сделано? писано чем? слогом): одна н; запутанным — полное прилагательное с приставкой за-: две н (урок 2).<br>3. Немедленно — наречие (доставлено как?), от немедленный: две н; доставлено — кр. прич. (вспоможение что сделано?).<br>4. Уложено — кр. прич. (все вещи что сделано? уложено): одна н.<br>5. Связано, оплетено — кр. прич. (связано, оплетено чем? нитью).<br>6. Растрёпанная, отчаянный — полные прилагательные с приставками рас-, от-: две н; особенно — наречие (от особенный): две н; оскорблено — кр. прич. (самолюбие что сделано? оскорблено); огорчён — краткое причастие мужского рода, одна н.<br>Наречия: искусно, немедленно, особенно. Краткие причастия: (всё) сделано, раскрашено, размещено; (оно) писано; (вспоможение) доставлено; (все) уложено; (всё) связано, оплетено; (самолюбие) оскорблено.'},
 {n:69,l:5,st:4,task:'Вставить пропущенные буквы. Над каждым словом с пропуском, которое оканчивается на -о, -а, -ы, указать, чем оно является: наречием, кратким причастием или кратким прилагательным. Доказать: задать вопрос, найти зависимое слово, определить значение (действие или состояние после действия — или постоянное качество). Остальные слова с пропусками объяснить.',
  body:'1. Конница Кара была утомле..а и малочисле..а. (А. С. Пушкин, «История Пугачёва») 2. Сумрачно и скучно в узкой галерее, тесно завале..ой шерстью, овчинами, пенькой, канатом, валя..ым сапогом, шорным товаром. От панели её отделяют колонны из кирпича; неуклюже толстые, они обглода..ы временем, обрызга..ы грязью улицы. Все кирпичи и щели между ними, наверное, мысле..о пересчита..ы тысячи раз и навсегда легли в памяти тяжкой сетью своих уродливых узоров. (М. Горький, «В людях») 3. Я вам открове..о скажу: дела мои расстрое..ы, крайне расстрое..ы. (Ф. М. Достоевский, «Игрок») 4. И были строги, медле..ы / Движенья. (Н. А. Некрасов, «Кому на Руси жить хорошо») 5. Читая Вашу статью, я болел душою не только за себя, но и за тех моих товарищей, которые неви..о пригвожде..ы к позорному столбу общественного мнения. (М. Горький, «Несвоевременные мысли») 6. Душа невольно смуще..а, / И в колесе недоумений / Вертится нехотя она. (Ф. И. Тютчев, «Как нас ни угнетай разлука…») 7. Зина была как-то торжестве..о молчалива. (Ф. М. Достоевский, «Дядюшкин сон») Пояснения: конница Кара — конный отряд генерала Кара; пенька — волокно конопли для верёвок; шорный товар — упряжь для лошадей; панель — здесь: тротуар; пригвождены к позорному столбу — подвергнуты всеобщему осуждению; колесо недоумений — круговорот сомнений.',
  key:'1. Утомлена — краткое причастие: состояние после действия (конницу утомили походы), одна н; малочисленна — краткое прилагательное: постоянное качество (малочисленная конница), две н, как в полной форме.<br>2. Заваленной — полное причастие с приставкой и зависимыми словами; валяным — отглагольное прилагательное (валять, без приставки и зависимых слов): одна н; обглоданы, обрызганы — краткие причастия: обглоданы чем? временем, обрызганы чем? грязью; мысленно — наречие (пересчитаны как?), от мысленный: две н; пересчитаны — краткое причастие (пересчитаны сколько раз? — действие).<br>3. Откровенно — наречие (скажу как?), от откровенный; расстроены (дважды) — краткое причастие: дела расстроены — состояние после действия, одна н. Слово «крайне» здесь не делает его прилагательным: решает значение.<br>4. Медленны — краткое прилагательное (движенья каковы? медленны — постоянный признак): две н, как в слове медленный.<br>5. Невинно — наречие (пригвождены как?), от невинный: корень вин- (вина) + суффикс -н-, две н; пригвождены — краткое причастие (сказуемое, есть зависимые слова «к столбу»): одна н.<br>6. Смущена — краткое причастие: состояние после действия (душу смутили), одна н; невольно — наречие с одной н (невольный: корень -воль- + суффикс -н-).<br>7. Торжественно — наречие: относится к прилагательному «молчалива» (как? в какой мере?), от торжественный: две н. Наречие может относиться не только к глаголу, но и к прилагательному.'},
 {n:70,l:5,st:4,task:'В заметке для школьного сайта допущено шесть ошибок в написании н и нн. Найти и исправить их, объяснить каждую. Доказать, что остальные слова с н и нн написаны верно.',
  body:'Городской марафон начался торжественно: заиграл оркестр, и сотни бегунов одновремено сорвались с места. Трасса была тщательно размеченна, вдоль неё стояли волонтёры. Первые километры Миша бежал уверено и даже весело поглядывал по сторонам. Потом подул ветер, стало ветренно и холодно. Миша растерянно оглянулся: друзья отстали. Пить хотелось нестерпимо, но пункт с водой был недалеко: его организовали у моста. Последние метры Миша пробежал отчаянно, из последних сил. Медаль, вручёная ему на финише, оказалась непривычно тяжёлой. «Ты её заслужено получил, — сказал тренер. — Всё было продумано правильно: и темп, и питьё».',
  key:'Ошибки: одновремено → одновременно (наречие от одновременный, две н); размеченна → размечена (краткое причастие: трасса что сделана? размечена — одна н); уверено → уверенно (наречие: бежал как? — от уверенный); ветренно → ветрено (от ветреный — исключение, одна н); вручёная → вручённая (полное причастие с приставкой в- и зависимыми словами — две н); заслужено → заслуженно (наречие: получил как? — от заслуженный).<br>Верно: торжественно (наречие от торжественный), растерянно (от растерянный), отчаянно (от отчаянный), продумано (краткое причастие: всё что сделано? продумано — одна н), непривычно, нестерпимо (суффикс -н- после корня: одна н или н на стыке нет).'},
 {n:72,l:5,st:5,task:'(Тонкость.) Сравнить наречия в каждой паре, вставить пропущенные буквы и объяснить, почему написание различается или совпадает. Для каждого наречия назвать прилагательное и указать, отчего в нём одна или две н.',
  body:'1. Пута..о объяснял — запута..о объяснял. 2. Ветре..о на улице — безветре..о на море. 3. Учё..о рассуждал — заучё..о повторял. 4. Нечая..о задел — отчая..о сопротивлялся. 5. Искус..о вышитая скатерть — искусстве..о созданное озеро. 6. Невида..о богатый урожай — незва..о явился в гости.',
  key:'1. Путано (путаный: нет приставки, одна н) — запутанно (запутанный: есть приставка за-, две н). Различаются приставкой.<br>2. Ветрено (ветреный — исключение, одна н) — безветренно (безветренный: слово с приставкой пишется с двумя н). Различаются приставкой.<br>3. Учёно (учёный: без приставки, одна н) — заученно (заученный: приставка за-, две н).<br>4. Нечаянно (нечаянный — исключение: две н без примет) — отчаянно (отчаянный: приставка от-, две н). Совпадают, но по разным причинам.<br>5. Искусно (искусный: корень искус- + суффикс -н-, одна н) — искусственно (искусственный: суффикс -енн-, две н). Различаются суффиксом.<br>6. Невиданно (невиданный — исключение: две н) — незвано (незваный: приставка не- приметой не считается, одна н). Различаются: одно слово — исключение, другое пишется по общему правилу.'},
  {n:73,l:5,st:5,task:'Прочитать отрывки. 1) Переписать, вставляя пропущенные буквы. 2) Выписать все слова с пропусками в три столбика: полные прилагательные и причастия; краткие прилагательные и причастия; наречия. 3) Объяснить написание каждого наречия и каждой краткой формы. 4) В отрывке 1 найти наречие, которое относится не к глаголу, и указать, к какому слову оно относится. 5) В отрывке 1 есть слово на -о, которое легко принять за наречие. Доказать, что это краткое прилагательное (найти подлежащее). 6) Объяснить, почему в слове «драгоценных» две н.',
  body:'1. Это была образная. Были сумерки. Лампады ярко сверкали своими огнями на золотых ризах и драгоце..ых каменьях образов. Из-под блестящих окладов тускло выглядывали лики святых. Всё здесь так не походило на другие комнаты, так было таинстве..о и угрюмо, что была пораже..а и какой-то испуг овладел моим сердцем. К тому же я была так болезне..о настрое..а! (Ф. М. Достоевский, «Неточка Незванова») 2. Исправник смире..о положил в карман свою бумагу и молча принялся за гуся с капустой. Между тем слуги успели уж несколько раз обойти гостей, наливая каждому его рюмку. Несколько бутылок горского и цымлянского громко были уже откупоре..ы и приняты благоскло..о под именем шампанского, лица начинали рдеть, разговоры становились звонче, несвязнее и веселее. (А. С. Пушкин, «Дубровский») Пояснения: образная — комната с иконами (образами); лампада — небольшой светильник перед иконой; риза, оклад — металлическое покрытие иконы; лики — лица на иконах; исправник — начальник уездной полиции; горское, цымлянское — сорта вина; рдеть — краснеть.',
  key:'2) Полные: драгоценных (каменьях). Краткие: (всё) таинственно — краткое прилагательное; (подлежащее «я» подразумевается) поражена, настроена — краткие причастия; (бутылки) откупорены — краткое причастие. Наречия: болезненно; смиренно, благосклонно.<br>3) Таинственно — краткая форма прилагательного таинственный (-енн-): пишется как полная форма, две н. Поражена — краткое причастие: состояние после действия (меня поразило то, что я увидела), одна н. Настроена — краткое причастие, одна н. Откупорены — краткое причастие: бутылки что сделаны? откупорены кем? слугами — одна н. Болезненно — наречие от болезненный (-енн-). Смиренно — наречие (положил как?) от смиренный (от смирить — сов. вид): две н. Благосклонно — наречие (приняты как?) от благосклонный: основа склон- + суффикс -н-, две н.<br>4) Болезненно относится к краткому причастию «настроена» (настроена как?).<br>5) Таинственно: «всё здесь… было таинственно и угрюмо» — подлежащее «всё», сказуемое «было таинственно» (каково?); это краткое прилагательное среднего рода, однородное с «угрюмо». Написание то же, что у наречия, — две н.<br>6) Драгоценный: драго-цен-н-ый — основа цен- (цена) оканчивается на н, к ней прибавлен суффикс -н-.'},
// Урок 6
 {n:34,l:6,st:1,task:'Вставить пропущенные буквы в существительных. В скобках указать слово, от которого образовано существительное, и сколько н в этом слове. Затем записать слова в два столбика: с одной н и с двумя.',
  obr:'Песча..ик → песчаник (песчаный: одна н).',
  body:'Масле..ица, копчё..ости, ряже..ые (на Святки), торфя..ик, пря..ик, варе..ики, избра..ик, изгна..ик, утопле..ик, родстве..ик, сторо..ик.',
  key:'Масленица (масленый: одна н), копчёности (копчёный: одна н), ряженые (ряженый: одна н), торфяник (торфяной: одна н), пряник (пряный: одна н), вареники (варёный: одна н); избранник (избранный: две н), изгнанник (изгнанный: две н), утопленник (утопленный: от утопить — сов. вид, две н), родственник (родственный: две н), сторонник (сторона — основа на н + суффикс -ник: две н).<br>Одна н: Масленица, копчёности, ряженые, торфяник, пряник, вареники. Две н: избранник, изгнанник, утопленник, родственник, сторонник.'},
 {n:75,l:6,st:1,task:'Образовать существительные: 1) с суффиксом -ник или -ниц(а) — от существительных; 2) с суффиксом -ость — от прилагательных. Обозначить суффикс и объяснить, сколько н в каждом слове. В части 2 найти два слова с одной н.',
  obr:'1) Малина → малин-ник: основа малин- оканчивается на н, к ней прибавлен суффикс -ник — две н. 2) Рассеянный → рассеянн-ость: две н, как в прилагательном.',
  body:'1) Звон (колокольный) — башня с колоколами; сон — книга, в которой толкуют сны; лимон — растение; песня — сборник песен. 2) Смышлёный, ветреный, ограниченный, уединённый, искренний, непреклонный, раскованный.',
  key:'1) Звон-ниц-а (звонница), сон-ник (сонник), лимон-ник (лимонник), песен-ник (песенник: основа песен- от песня) — везде основа на н + суффикс -ник или -ниц(а): две н.<br>2) Смышлёность (смышлёный: одна н), ветреность (ветреный — исключение, одна н); ограниченность, уединённость, искренность, непреклонность, раскованность — две н, как в прилагательных.'},
 {n:83,l:6,st:2,task:'Заменить описания одним существительным с н или нн. Записать существительные, обозначить в них суффикс и объяснить, сколько н. Найти четыре слова, в которых пишется одна н, хотя суффикс у них тот же, что у соседних слов с двумя н.',
  obr:'Заросли рябины → рябин-ник (основа рябин- на н + суффикс -ник: две н).',
  body:'1. Заросли малины. 2. Заросли черники. 3. Заросли осины. 4. Заросли брусники. 5. Человек, который поселился в уединении, в пустынном месте. 6. Тот, кто разделяет чьи-то взгляды и мысли. 7. Тот, кто живёт в одно время с кем-либо. 8. Болезненное состояние, когда человек не может уснуть. 9. Военный, который охраняет границу. 10. Работник нефтяной промышленности. 11. Мастер, который выделывает кожу. 12. Конное войско.',
  key:'1. Малинник (малин- + -ник: две н). 2. Черничник (черник-а → чернич- + -ник: основа не на н — одна н). 3. Осинник (осин- + -ник: две н). 4. Брусничник (бруснич- + -ник: одна н). 5. Пустынник (пустын- от пустыня + -ник: две н). 6. Единомышленник (единомышленный: две н). 7. Современник (современный: две н). 8. Бессонница (бессонный: две н). 9. Пограничник (пограничный: основа погранич- не на н — одна н). 10. Нефтяник (нефтяной: суффикс -ян-, одна н). 11. Кожевник (кожев- + -ник: основа не на н — одна н). 12. Конница (кон- от конь + -ниц-: две н).<br>Суффикс -ник, но одна н: черничник, брусничник, пограничник, кожевник (основа не оканчивается на н — в отличие от малинник, осинник, пустынник).'},
 {n:35,l:6,st:2,task:'Вставить пропущенные буквы и распределить существительные в два столбика: с одной н и с двумя. Рядом с каждым словом в скобках записать слово, от которого оно образовано.',
  obr:'Лимо..ик → лимонник (лимон: основа на н + суффикс -ник — две н).',
  body:'Дровя..ик, листве..ица, дружи..ик, солё..ья, письме..ость, тума..ость, овся..ка, покло..ик, учё..ость, бездо..ость, мороже..щик, избалова..ость. Пояснения: письменность — письмо, система знаков народа и записанные на ней тексты; бездонность — бесконечная глубина.',
  key:'Одна н: дровяник (дровяной), соленья (солёный), овсянка (овсяный), учёность (учёный), мороженщик (мороженое — в нём одна н).<br>Две н: лиственница (лиственный), дружинник (дружина: основа на н + -ник), поклонник (поклон: основа на н + -ник), письменность (письменный), туманность (туманный), бездонность (бездонный), избалованность (избалованный).'},
 {n:36,l:6,st:3,task:'Переписать, вставляя пропущенные буквы. Над каждым существительным указать слово, от которого оно образовано, и сколько н в этом слове. Остальные слова с пропусками объяснить по правилам уроков 1–5.',
  obr:'Ребята набрали полную корзину в мали..ике. → Малиннике: малина (основа на н) + -ник — две н.',
  body:'1. Это был день неожида..остей, день развязок прежнего и завязок нового, резких разъяснений и ещё пущей пута..ицы. (Ф. М. Достоевский, «Бесы») 2. Дядья считали, что это прида..ое должно быть поделено между ними. (М. Горький, «Детство») 3. Двор — маленький, тесный и сорный, от ворот идут построе..ые из горбушин сарайчики, дровя..ики и погреба, потом они загибаются, заканчиваясь баней. (М. Горький, «Детство») 4. Его движения были столь быстры и непредвидимы, что не было средства его преследовать; к тому же ко..ица была слишком изнуре..а. (А. С. Пушкин, «История Пугачёва») 5. Расстилаем на снегу одеяла, укладываем на них ране..ых, все, кто может, наваливаемся на что-то горячее, медное впереди машины — ни с места. (М. М. Пришвин, «Августовские леса») 6. Посадская вдова: / Как божия посла..ица, / Старушка появляется / В холерные года… (Н. А. Некрасов, «Кому на Руси жить хорошо») 7. Дома меня встретили, как имени..ика, женщины заставили подробно рассказать, как доктор лечил меня, что он говорил, — слушали и ахали, сладостно причмокивая, морщась. (М. Горький, «В людях») 8. Всё это — праздная фантазия легкомысле..ых путешестве..иков. (Ф. М. Достоевский, «Крокодил») 9. Стали отпускать, но пле..ые не идут, они хотят лучше идти за куском хлеба, чем оставаться одним в лесу. (М. М. Пришвин, «Августовские леса») Пояснения: пущий — ещё больший; горбушина — горбыль, крайняя доска с корой от распила бревна; непредвидимы — непредсказуемы; изнурена — сильно утомлена; посадская — жительница посада, торговой части города; холерные года — годы эпидемии холеры; праздная — пустая; в предложениях 5 и 9 речь о войне: санитарный отряд везёт раненых, казаки ведут пленных.',
  key:'1. Неожиданностей (неожиданный: две н), путаницы (путаный: одна н). 2. Приданое — одна н (это слово запоминают); поделено — краткое причастие, одна н. 3. Построенные — полное причастие с зависимыми словами; дровяники (дровяной: одна н). 4. Конница (кон- от конь + -ниц-: две н); изнурена — краткое причастие, одна н. 5. Раненых (раненый: одна н — от ранить без приставки и зависимых слов); медное — одна н (медь + -н-). 6. Посланница (посланный: две н). 7. Именинника (именины: основа на н + -ник: две н). 8. Легкомысленных (легкомысленный: -енн-), путешественников (путешествие → путешеств-енн-ик: две н). 9. Пленные (пленный: плен + -н-: две н).'},
 {n:77,l:6,st:3,task:'Переписать, вставляя пропущенные буквы. Выписать в один столбик существительные с н или нн, в другой — прилагательные и причастия. У существительных указать слово, от которого они образованы. Объяснить: 1) почему «гости..ый» в предложении 4 — не существительное; 2) почему в словах «помощница», «благодетельница» (предложение 7) одна н.',
  obr:'Ряже..ые ходили по домам и пели колядки. → Ряженые — существительное (ряженый: одна н).',
  body:'1. Накануне праздника гости начали съезжаться, иные останавливались в господском доме и во флигелях, другие у приказчика, третьи у свяще..ика, четвёртые у зажиточных крестьян. (А. С. Пушкин, «Дубровский») 2. Там, и единстве..о только там, он мог бы приносить настоящую, несомне..ую пользу своим соотечестве..икам. (Ф. М. Достоевский, «Дядюшкин сон») 3. Масле..ые и копчё..ые кочегары-белорусы считались на пароходе низшими людьми. (М. Горький, «В людях») 4. Гости..ый двор и остальные дома, церкви и монастыри были разграбле..ы. (А. С. Пушкин, «История Пугачёва») 5. Пригнали тогда в Балахну нашу десятка три пле..иков; всё народ сухонькой, мелкой; одеты кто в чём, хуже нищей братии, дрожат, а которые и помороже..ы, стоять не в силе. (М. Горький, «Детство») 6. Пришли на площадь стра..ики: / Товару много всякого / И видимо-невидимо / Народу! (Н. А. Некрасов, «Кому на Руси жить хорошо») 7. Бедная воспита..ица была не что иное, как слепая помощница разбойника, убийцы старой её благодетельницы!.. (А. С. Пушкин, «Пиковая дама») Пояснения: флигель — боковая пристройка или отдельный дом при усадьбе; приказчик — управляющий имением; Гостиный двор — ряды торговых лавок; кочегар — рабочий, который топит котлы парохода; сухонькой, мелкой — так говорит дед в рассказе (по-книжному: сухонький, мелкий); стоять не в силе — не могут стоять; благодетельница — та, кто делает добро.',
  key:'Существительные: священника (священный: две н); соотечественникам (соотечественный — от отечество, -енн-: две н); пленников (пленный: две н); странники (страна: основа на н + -ник, две н); воспитанница (воспитанный: две н).<br>Прилагательные и причастия: несомненную (несомненный: -енн-), масленые (масленый: отглагольное прилагательное, одна н), копчёные (копчёный: одна н), Гостиный (одна н: суффикс -ин-); разграблены, поморожены — краткие причастия (одна н). Единственно — наречие (две н).<br>1) «Гостиный» отвечает на вопрос «какой?» и относится к слову «двор» — это прилагательное. Существительным становится только «гостиная» (комната).<br>2) Помощница: помощ- + -ниц(а); благодетельница: благодетель + -ниц(а). Основа не оканчивается на н, поэтому н одна.'},
 {n:78,l:6,st:3,task:'Разобрать существительные по составу по школьному плану (окончание, основа, приставка, корень, суффиксы). Указать, от какого слова образовано каждое существительное, и объяснить, откуда в нём одна или две н.',
  obr:'Ряженые → ряж-ен-ые: окончание -ые, основа ряжен-, корень ряж-, суффикс -ен-; от ряженый — одна н.',
  body:'Дружинник, конница, бессонница, лиственница, нефтяник, путаница, избранник, письменность, овсянка, сторонник.',
  key:'Дружин-ник (окончание нулевое; корень дружин-, суффикс -ник): от дружина, основа на н + -ник — две н.<br>Кон-ниц-а (окончание -а; корень кон-, суффикс -ниц-): от конь — две н.<br>Бес-сон-ниц-а (приставка бес-, корень сон-, суффикс -ниц-, окончание -а): от бессонный — две н.<br>Листв-енн-иц-а (корень листв-, суффиксы -енн-, -иц-, окончание -а): от лиственный — две н.<br>Нефт-ян-ик (корень нефт-, суффиксы -ян-, -ик, окончание нулевое): от нефтяной — одна н.<br>Пут-а-н-иц-а (корень пут-, суффиксы -а-, -н-, -иц-, окончание -а): от путаный — одна н.<br>Из-бр-а-нн-ик (приставка из-, корень бр-, суффиксы -а-, -нн-, -ик, окончание нулевое): от избранный — две н.<br>Письм-енн-ость (корень письм-, суффиксы -енн-, -ость, окончание нулевое): от письменный — две н.<br>Овс-ян-к-а (корень овс-, суффиксы -ян-, -к-, окончание -а): от овсяный — одна н.<br>Сторон-ник (корень сторон-, суффикс -ник, окончание нулевое): от сторона — основа на н + -ник, две н.'},
 {n:84,l:6,st:3,task:'Написать заметку для школьной газеты (7–9 предложений) на одну из тем: «Встреча с путешественником», «Как мы готовились к Масленице», «Поход за грибами». Употребить не меньше восьми существительных с н или нн, причём из разных групп: от прилагательных с одной н; от прилагательных и причастий с двумя н; основа на н + суффикс -ник, -ниц(а); на -ость. Подчеркнуть эти существительные и над каждым указать слово, от которого оно образовано.',
  obr:'На столе стояли соленья и копчёности. → Соленья (солёный: одна н), копчёности (копчёный: одна н).',
  body:'Слова для выбора: путешественник, единомышленник, современник, родственник, воспитанница, конница, звонница, осинник, малинник, черничник, бессонница, Масленица, вареники, соленья, пряники, ряженые, гостиная, мороженое, туманность, уверенность, рассеянность, смышлёность.',
  key:'Ответ свободный. Проверить написание: одна н — Масленица, вареники, соленья, пряники, ряженые, гостиная, мороженое, смышлёность, черничник; две н — путешественник, единомышленник, современник, родственник, воспитанница, туманность, уверенность, рассеянность; основа на н + -ник, -ниц(а) — конница, звонница, осинник, малинник; бессонница (бессонный). Масленица — название праздника, пишется с прописной буквы.'},
 {n:79,l:6,st:4,task:'Вставить пропущенные буквы. Определить, какой частью речи является каждое слово с пропуском (существительное, полное прилагательное, полное причастие, краткая форма, наречие), и объяснить, почему в однокоренных словах пишется разное число н (или одинаковое).',
  body:'1) 1. Ране..ых доставили в госпиталь на вертолёте. — Ране..ые осколками бойцы ждали помощи. 2. Учё..ые обсуждали открытие весь вечер. — Заучё..ые наизусть стихи легко вспоминались. 3. Прида..ое невесты везли на трёх подводах. — Батальон, прида..ый полку, занял высоту. 4. Он вёл жизнь самую рассея..ую; торчал на всех балах, объедался на всех дипломатических обедах, и на всяком зва..ом вечере был так же неизбежим, как резановское мороже..ое. (А. С. Пушкин, «Египетские ночи») 2) Вставить буквы в словах каждого гнезда: а) собра..ость, собра..ый ученик, отвечал собра..о, вещи собра..ы; б) образова..ость, образова..ая девушка, девушка образова..а и умна, комиссия образова..а в мае; в) ограниче..ость, ограниче..ые возможности, время ограниче..о правилами. Пояснения: придать — здесь: временно присоединить к другой части войск; неизбежим — здесь: неизбежен; резановское мороженое — мороженое из известной кондитерской.',
  key:'1) 1. Раненых — существительное (от раненый: ранить без приставки и зависимых слов — одна н); раненные (осколками) — причастие с зависимым словом: две н. 2. Учёные — существительное (учёный: одна н); заученные — причастие с приставкой и зависимым словом: две н. 3. Приданое — существительное: одна н (запоминают); приданный (полку) — причастие от глагола сов. вида придать: две н. 4. Рассеянную — прилагательное (рассеянный: приставка рас-, две н); званом — отглагольное прилагательное (звать, без приставки и зависимых слов): одна н; мороженое — существительное (мороженый: одна н).<br>2) а) Собранность, собранный — две н (приставка); собранно — наречие, две н; собраны — краткое причастие (вещи собраны кем-то), одна н. б) Образованность, образованная — две н (суффикс -ова-); образованна — краткое прилагательное: постоянное качество, две н; образована — краткое причастие (комиссия образована когда? — действие), одна н. в) Ограниченность, ограниченные — две н; ограничено — краткое причастие (ограничено чем? правилами), одна н.'},
 {n:80,l:6,st:4,task:'В заметке ученика шесть ошибок в написании н и нн. Найти и исправить их, объяснить каждую. Доказать, что остальные слова с н и нн написаны верно.',
  body:'В субботу наш класс ездил в краеведческий музей. В первом зале была устроена старинная гостинная: резной буфет, на столе — самовар и медные подносы. Экскурсовод рассказала, как в нашем городе праздновали Масленницу: пекли блины, катались с ледяных гор. В следующем зале хранятся доспехи дружиников и копья, найденные при раскопках. Мы узнали, что первые жители города были искусными кузнецами и серебрянниками. На стенде висят письма наших земляков-путешествеников. Самое интересное — макет старой улицы: кажется, что вот-вот из-за угла выедет конница. После экскурсии мы зашли в кафе и заказали мороженное. Никакой путаницы с расписанием не было: всё было организовано учителем.',
  key:'Ошибки: гостинная → гостиная (гостиный: суффикс -ин-, одна н); Масленницу → Масленицу (масленый: одна н; название праздника — с прописной); дружиников → дружинников (дружина: основа на н + -ник); серебрянниками → серебряниками (серебряный: одна н); путешествеников → путешественников (путешеств-енн-ик); мороженное → мороженое (мороженый: одна н).<br>Верно: старинная (старина: основа на н + -н-), медные (медь + -н-: одна н), ледяных (суффикс -ян-: одна н), найденные (полное причастие с зависимыми словами), искусными (искус- + -н-: одна н), конница (кон- + -ниц-), путаницы (путаный: одна н), организовано (краткое причастие: всё что сделано? кем? учителем — одна н).'},
 {n:81,l:6,st:4,task:'Прочитать отрывок. 1) Переписать, вставляя пропущенные буквы. 2) Выписать все слова с пропусками и распределить по группам: существительные; прилагательные, образованные от существительных; причастия и прилагательные, образованные от глаголов. Объяснить написание каждого слова. 3) Почему в слове «почте..ой» две н, хотя нет ни приставки, ни зависимых слов? 4) В отрывке есть существительное с суффиксом -ник, в котором одна н. Найти его и сравнить с существительным «сторонник». 5) Найти причастный оборот и объяснить, почему он выделен запятой. 6) Разобрать по составу слова «мороже..ое» и «гости..ой».',
  body:'Они прошли ряд великолепных комнат, наполне..ых учтивыми официантами. Несколько генералов и тайных советников играли в вист; молодые люди сидели, развалясь на штоф..ых диванах, ели мороже..ое и курили трубки. В гости..ой за дли..ым столом, около которого теснилось человек двадцать игроков, сидел хозяин и метал банк. Он был человек лет шестидесяти, самой почте..ой наружности; голова покрыта была серебря..ой сединою; полное и свежее лицо изображало добродушие; глаза блистали, оживлё..ые всегдашнею улыбкою. (А. С. Пушкин, «Пиковая дама») Пояснения: штоф — плотная шёлковая ткань для мебели; вист — карточная игра; метать банк — сдавать карты в азартной игре; тайный советник — высокий чин в старой России; всегдашний — постоянный.',
  key:'2) Существительные: мороженое (мороженый: одна н), гостиной (гостиный: суффикс -ин-, одна н). Прилагательные от существительных: штофных (штоф + -н-: одна н), длинным (длина: основа на н + -н-: две н), серебряной (суффикс -ян-: одна н). От глаголов: наполненных (приставка на- и зависимое слово: две н), почтенной (почтить — сов. вид: две н), оживлённые (сов. вид и зависимое слово: две н).<br>3) Почтенный образован от глагола совершенного вида почтить; совершенный вид — одна из примет: две н.<br>4) Советников: совет + суффикс -ник — основа не на н, одна н. Сторонник: сторон(а) + -ник — основа на н, две н.<br>5) «Оживлённые всегдашнею улыбкою» — причастный оборот стоит после определяемого слова «глаза» и выделяется запятой (в конце предложения — одной запятой перед оборотом).<br>6) Морож-ен-ое: корень морож-, суффикс -ен-, окончание -ое. Гост-ин-ой: корень гост-, суффикс -ин-, окончание -ой.'},
 {n:82,l:6,st:5,task:'(Тонкость.) В этих словах число н нельзя объяснить только по слову, от которого образовано существительное. Вставить пропущенные буквы и, пользуясь пояснениями, объяснить написание. Указать слова, которые приходится запоминать.',
  body:'1. Сущий муче..ик четырнадцатого класса, огражде..ый своим чином токмо от побоев, и то не всегда (ссылаюсь на совесть моих читателей). (А. С. Пушкин, «Станционный смотритель») 2. Много ли останется истинных труже..иков, как вы думаете? (Ф. М. Достоевский, «Дневник писателя») 3. Так мерил пристав следстве..ый / Побои на подравшихся / На рынке мужиках: / «Под правым глазом ссадина / Величиной с двугриве..ый, / В средине лба пробоина / В целковый. (Н. А. Некрасов, «Кому на Руси жить хорошо») 4. Знайте, что каждый человек содержит в себе дурака и моше..ика: дурак — его чувство, а моше..ик — ум. (М. Горький, «Проходимец») 5. Он говорит, что спас мне жизнь, потому что прикрыл обман Акулины Памфиловны, которая сказала злодеям, будто бы я её племя..ица. (А. С. Пушкин, «Капитанская дочка») 6. Девушки гадали на суже..ого. — Улица, суже..ая из-за ремонта, стояла в пробках. 7. За бесприда..ицу никто не сватался. — Мастер-серебря..ик показал нам свои кубки. Пояснения: четырнадцатый класс — самый низкий чин; станционный смотритель — служащий почтовой станции; токмо — только; пристав следственный — чиновник, который ведёт дознание; двугривенный — монета в двадцать копеек, целковый — в рубль; суженый — жених, предназначенный судьбой (от старого «судить» — предназначать); бесприданница — девушка без приданого.',
  key:'1. Мученик — одна н: суффикс -еник- (муч-еник), как в слове ученик; ограждённый — причастие с зависимыми словами, две н. 2. Труженик — одна н: тот же суффикс -еник- (труж-еник). 3. Следственный — суффикс -енн-; двугривенный — две н: гривна (гривен-) + суффикс -н-, основа на н (так же гривенник). 4. Мошенник — две н: запоминают. 5. Племянница — две н: запоминают (как и племянник). 6. Суженого — одна н: прилагательное, ставшее существительным, без приставки и зависимых слов (от «судить»); суженная — причастие от сузить (сов. вид) с зависимыми словами: две н. 7. Бесприданница — две н, хотя в слове «приданое» одна: на стыке основы придан- и суффикса -ниц- встречаются две н; серебряник — одна н (серебряный: суффикс -ян-).<br>Запоминают: мошенник, племянник (племянница), приданое — бесприданница; мученик и труженик проверяются суффиксом -еник-.'},
// Урок 7. Повторение
 {n:85,l:7,st:1,task:'Слова записаны верно. Распределить их по группам в зависимости от того, каким правилом объясняется одна или две н: А) суффиксы -ан-, -ян-, -ин- (одна н); Б) суффиксы -енн-, -онн- (две н); В) основа на н + суффикс -н- (две н); Г) слово-исключение; Д) отглагольное прилагательное без примет причастия (одна н); Е) причастие: есть приставка, зависимое слово, суффикс -ова- или совершенный вид (две н); Ж) краткое причастие (одна н); З) наречие или существительное, в котором столько н, сколько в исходном слове. В каждой группе должно оказаться не меньше двух слов.',
  obr:'Гусиный → А (суффикс -ин-).',
  body:'Соломенный, сонный, оловянный, ржаной, полотняный, станционный, каменный, ветреный, тканый, вымощенный, купленный, балованный, солёный, засушенный, (задача) решена, (письма) написаны, (ответил) растерянно, (смотрел) сонно, дружинник, избранник.',
  key:'А: ржаной (-ан-), полотняный (-ян-); гусиный — в образце.<br>Б: соломенный (-енн-), станционный (-онн-).<br>В: сонный, каменный.<br>Г: оловянный (две н), ветреный (одна н).<br>Д: тканый, солёный.<br>Е: вымощенный (приставка), купленный (сов. вид), балованный (-ова-), засушенный (приставка).<br>Ж: решена, написаны.<br>З: растерянно, сонно (наречия — как в прилагательных растерянный, сонный); дружинник (дружина + -ник), избранник (избранный).'},
 {n:37,l:7,st:2,task:'Переписать текст, вставляя пропущенные буквы. Над каждым словом с пропуском указать номер урока, по правилу которого оно пишется, и кратко объяснить написание.',
  obr:'Ю..ый помощник садовника… → юный (урок 1: н входит в корень, суффикса -н- нет — одна н).',
  body:'После дождя городской сад казался умытым. На песча..ых дорожках блестели лужи, а скамейки, недавно выкраше..ые в зелёный цвет, были усыпа..ы мокрыми листьями. На ветке клёна сидела взъероше..ая ворона. Старый садовник неторопливо подрезал куст шиповника, посаже..ого ещё его дедом. Малыши в резиновых сапогах бегали по траве и самозабве..о кричали. Из летнего кафе пахло ваниль..ой выпечкой. У фонтана, облицова..ого серым гранитом, играл уличный музыкант; мелодия звучала нежно и чуть отрешё..о. Сад жил своей неторопливой, неизме..ой жизнью.',
  key:'Песчаных (урок 1: суффикс -ан-, одна н); выкрашенные (урок 2: приставка вы- и зависимые слова, две н); усыпаны (урок 4: краткое причастие, одна н); взъерошенная (урок 2: приставка взъ-, две н); посаженного (урок 2: приставка и зависимое слово); самозабвенно (урок 5: наречие от самозабвенный, две н); ванильной (урок 1: ваниль + суффикс -н-, основа не на н — одна н); облицованного (урок 2: суффикс -ова-, две н); отрешённо (урок 5: наречие от отрешённый, две н); неизменной (урок 1: основа -измен- на н + суффикс -н-, две н).'},
 {n:86,l:7,st:3,task:'Выборочный диктант. Учитель (или родитель) читает предложения, ученик записывает только слова, в которых пишется н или нн на стыке корня и суффикса или в суффиксе, распределяя их в два столбика: с одной н и с двумя. Затем открыть текст, проверить и объяснить каждое слово.',
  obr:'Цветы глядят с тоской влюблённой… → Две н: влюблённой (причастие от влюбить — сов. вид).',
  body:'1. Роняя с пылью благовонной / Плодов румяных семена. (А. А. Фет, «Цветы») 2. Последний сноп свезён с нагих полей, / По стоптанным гуляет жнивьям стадо… (А. А. Фет, «Псовая охота») 3. И я один, с моей тупой тоскою, / Хочу сознать себя и не могу — / Разбитый чёлн, заброшенный волною / На безымянном диком берегу. (Ф. И. Тютчев, «Есть и в моём страдальческом застое…») 4. Казённое имущество было разграблено; офицеры перебиты, кроме одного, пощажённого по просьбе работников; колодники присоединены к шайке мятежников. (А. С. Пушкин, «История Пугачёва») 5. Это бредут куда-то легко раненные, и с ними ещё две белые собачки. (М. М. Пришвин, «Августовские леса») 6. Его лицо, облитое потом, выпачканное сажей, плакало грязными слезами, глаза испуганно мигали, в мокрой бороде запуталось мочало. (М. Горький, «Мои университеты») 7. Медленно прошёл день, бессонная ночь и ещё более медленно другой день. (М. Горький, «Мать») Пояснения: благовонный — душистый; сноп — связка сжатых колосьев; жнивьё — поле после жатвы; чёлн — лодка; колодник — арестант; мочало — волокно из коры липы; в предложении 5 речь о войне.',
  key:'Одна н: румяных (н в корне); свезён (краткое причастие); разграблено, присоединены (краткие причастия).<br>Две н: благовонной (вон- «запах» + -н-: основа на н); стоптанным (приставка); заброшенный (приставка, зависимое слово); безымянном (как именной: основа имен-/ымян- + -н-); казённое (суффикс -ённ-, от казна); пощажённого (сов. вид, зависимое слово); раненные (есть зависимое слово «легко»: причастие); выпачканное (приставка, зависимое слово); испуганно (наречие от испуганный); медленно — дважды (от медленный — исключение); бессонная (бессонный: сон + -н-).<br>Слова «облитое», «перебиты» — с суффиксом -т-, к правилу не относятся.'},
 {n:87,l:7,st:3,task:'Распределительный диктант. Записать предложения под диктовку, вставляя пропущенные буквы, затем выписать слова с н и нн в пять столбиков: 1) прилагательные, образованные от существительных; 2) полные причастия и отглагольные прилагательные; 3) краткие причастия и прилагательные; 4) наречия; 5) существительные. Объяснить написание.',
  obr:'Улица была вымоще..а камнем. → 3 столбик: вымощена — краткое причастие, одна н.',
  body:'1. В холодном сумраке они шли по немощё..ой улице к высоким каме..ым клеткам фабрики, она с равнодушной увере..остью ждала их, освещая грязную дорогу десятками жирных квадратных глаз. (М. Горький, «Мать») 2. Гляжу: могилка прибра..а, / На деревя..ом крестике / Складная золочё..ая / Икона. (Н. А. Некрасов, «Кому на Руси жить хорошо») 3. Всё было пусто; стулья, столы, сундуки были перелома..ы; посуда перебита; всё растаска..о. (А. С. Пушкин, «Капитанская дочка») 4. Я прибегнул к утешению всех скорбящих и, впервые вкусив сладость молитвы, излия..ой из чистого, но растерза..ого сердца, спокойно заснул, не заботясь о том, что со мною будет. (А. С. Пушкин, «Капитанская дочка») 5. Князь рассея..о поглядел на неё, повернулся и пошёл назад в свою гости..ицу. (Ф. М. Достоевский, «Идиот») 6. Письмо сие, вместе с другими драгоце..ыми бумагами, доставле..о было родстве..иками и наследниками Фонвизина князю Вяземскому, занимавшемуся биографией автора «Недоросля». (А. С. Пушкин, «История Пугачёва») 7. Это был высокий, сухой и копчё..ый человек, в тяжёлом тулупе из овчины, с жёсткими волосами на костлявом, заржавевшем лице. (М. Горький, «Детство») Пояснения: квадратные глаза — здесь: освещённые окна фабрики; складная икона — раскладывающаяся из нескольких частей; излиянная — вылившаяся (здесь: молитва от всего сердца); сие — это; Д. И. Фонвизин — писатель, автор комедии «Недоросль».',
  key:'1) Каменным (камень: основа на н + -н-), деревянном (исключение), драгоценными (драго-цен-н-ый: основа цен- + -н-).<br>2) Немощёной (приставка не- приметой не считается: одна н), золочёная (без приставки и зависимых слов: одна н), излиянной (приставка из-), растерзанного (приставка рас-), копчёный (одна н).<br>3) Прибрана, переломаны, растаскано, доставлено — краткие причастия: одна н.<br>4) Рассеянно (от рассеянный: две н).<br>5) Уверенностью (уверенный: две н), гостиницу (гостиный: одна н), родственниками (родственный: две н).<br>Слово «перебита» — с суффиксом -т-, к правилу не относится.'},
 {n:38,l:7,st:4,task:'В десяти предложениях есть ошибки в написании н и нн, четыре предложения написаны верно. Найти и исправить ошибки, объяснить каждую и указать номер урока, по правилу которого пишется слово. Доказать, что в верных предложениях ошибок нет.',
  body:'1. Мы перешли речку по деревяному мостику. 2. На полдник дали булочку и стакан клюквеного киселя. 3. Ребята сидели на некрашенной скамейке у калитки. 4. Брат снял с полки зачитанную до дыр книгу. 5. На ужин сварили молодую картошку и подали её с варённой кукурузой. 6. Учительница проверила сочинения: все работы написанны аккуратно. 7. Ответы ученицы продуманны и точны. 8. Гости разговаривали оживлено и весело. 9. Всё решено: завтра едем на море. 10. Мой дед в молодости был нефтянником. 11. Командир похвалил раненного бойца. 12. Мы нечаянно разбили вазу. 13. С тех пор он стал мне названным братом. 14. В магазине продавались свежемороженные овощи.',
  key:'Ошибки: 1. Деревянному (урок 1: исключение, две н). 2. Клюквенного (урок 1: суффикс -енн-). 3. Некрашеной (урок 2: приставка не- приметой не считается, зависимых слов нет — одна н). 5. Варёной (урок 2: отглагольное прилагательное без примет — одна н). 6. Написаны (урок 4: краткое причастие — одна н). 8. Оживлённо (урок 5: наречие, от оживлённый). 10. Нефтяником (урок 6: от нефтяной, одна н). 11. Раненого (урок 2: ранить без приставки и зависимых слов — одна н). 13. Названым (урок 3: названый брат — побратим, устойчивое сочетание, одна н). 14. Свежемороженые (урок 3: сложное слово, во второй части нет приставки — одна н).<br>Верно: 4 — зачитанную (приставка за-); 7 — продуманны (краткое прилагательное: постоянное качество ответов, как в полной форме продуманный); 9 — решено (краткое причастие); 12 — нечаянно (наречие от нечаянный — исключение).'},
 {n:88,l:7,st:4,task:'Переписать, вставляя пропущенные буквы и расставляя недостающие запятые при причастных оборотах (остальные знаки поставлены). Выписать причастные обороты вместе с определяемыми словами. Найти краткие причастия, наречия и однородные обороты. Объяснить, почему в предложении 3 при причастии нет запятых.',
  body:'1. Вот мы и свернули налево и кое-как, после многих хлопот, добрались до скудного приюта состоящего из двух саклей сложе..ых из плит и булыжника и обведё..ых такою же стеною; оборва..ые хозяева приняли нас радушно. 2. В одном из домов слободки построе..ом на краю обрыва заметил я чрезвычайное освещение… 3. Я слез и подкрался к окну; неплотно притворё..ый ставень позволил мне видеть пирующих и расслышать их слова. (М. Ю. Лермонтов, «Герой нашего времени») 4. В полутёмной тесной комнате, на полу, под окном, лежит мой отец, одетый в белое и необыкнове..о дли..ый; пальцы его босых ног странно растопыре..ы, пальцы ласковых рук смирно положе..ых на грудь тоже кривые… (М. Горький, «Детство») 5. Мы проходили через селения разорё..ые бунтовщиками и поневоле отбирали у бедных жителей то, что успели они спасти. (А. С. Пушкин, «Капитанская дочка») Пояснения: сакля — горское жилище; слобода, слободка — пригород, посёлок; пирующие — те, кто пирует; растопырены — широко раздвинуты.',
  key:'1. …до скудного приюта, состоящего из двух саклей, сложенных из плит и булыжника и обведённых такою же стеною; оборванные хозяева… Обороты: (приюта) состоящего из двух саклей; (саклей) сложенных из плит и булыжника и обведённых такою же стеною — два однородных оборота, соединённых союзом «и», поэтому между ними запятой нет. Сложенных, обведённых — полные причастия с приставками и зависимыми словами: две н; оборванные — приставка об-: две н.<br>2. В одном из домов слободки, построенном на краю обрыва, заметил я… Оборот (домов) построенном на краю обрыва — после определяемого слова, выделяется с двух сторон; две н.<br>3. Притворённый — причастие с приставкой: две н; при нём только зависимое слово «неплотно», стоящее перед ним, и всё это стоит перед определяемым словом «ставень» — запятые не нужны.<br>4. …пальцы ласковых рук, смирно положенных на грудь, тоже кривые. Оборот (рук) смирно положенных на грудь — после определяемого слова. Необыкновенно — наречие (от необыкновенный); длинный — основа на н + -н-; растопырены — краткое причастие: одна н; одетый — суффикс -т-.<br>5. Мы проходили через селения, разорённые бунтовщиками, и поневоле… Оборот (селения) разорённые бунтовщиками; две н (сов. вид, зависимое слово).'},
 {n:90,l:7,st:4,task:'(В формате ОГЭ/ЕГЭ, для 8–11 классов.) Укажите все цифры, на месте которых пишется НН. Выполнить задание для каждого предложения и записать ответ цифрами без пробелов. Затем объяснить написание каждого слова.',
  body:'1. Ю(1)ый художник показал нам рисунки, выполне(2)ые карандашом на тонкой льня(3)ой бумаге, и несколько картин, писа(4)ых маслом. 2. Тиши(1)а была необыкнове(2)ой: в ледя(3)ом воздухе застыли осе(4)ие листья, а дальний лес казался нарисова(5)ым. 3. Сбивчивые объяснения гостя были прерва(1)ы: в комнату вошёл дежурный с запечата(2)ым конвертом, и все взгляды мгнове(3)о обратились к нему. 4. Я посмотрелся в зеркало; тусклая бледность покрывала лицо моё, хранившее следы мучительной бессо(1)ицы; но глаза, хотя окружё(2)ые коричневою тенью, блистали гордо и неумолимо. (М. Ю. Лермонтов, «Герой нашего времени»)',
  key:'1. Ответ: 24. Юный — н в корне; выполненные (приставка, зависимое слово); льняной (суффикс -ян-: одна н); писанных (есть зависимое слово «маслом» — причастие: две н).<br>2. Ответ: 245. Тишина — н входит в суффикс существительного -ин-, одна; необыкновенной (-енн-); ледяном (суффикс -ян-: одна н); осенние (осень: основа на н + -н-); нарисованным (приставка, -ова-).<br>3. Ответ: 23. Прерваны (краткое причастие — одна н); запечатанным (приставка); мгновенно (наречие от мгновенный).<br>4. Ответ: 12. Бессонницы (бессонный: сон + -н-, две н); окружённые (приставка, зависимое слово).'},
 {n:91,l:7,st:4,task:'(В формате ОГЭ/ЕГЭ, для 8–11 классов.) Укажите варианты ответов, в которых во всех словах одного ряда пропущена одна буква Н. Записать номера ответов, затем вставить буквы во все слова и объяснить, почему остальные ряды не подходят.',
  body:'1) песча..ый карьер, гуси..ое перо, румя..ые щёки; 2) кваше..ая капуста, плетё..ая корзина, вяле..ая рыба; 3) клюкве..ый морс, жела..ый гость, купле..ый билет; 4) задача реше..а, письма написа..ы, некоше..ый луг; 5) торжестве..о, нечая..о, рья..о; 6) варе..ики, ряже..ые, торфя..ик; 7) соломе..ая шляпа, лимо..ый сок, назва..ый брат.',
  key:'Ответ: 1, 2, 4, 6.<br>1) Песчаный (-ан-), гусиное (-ин-), румяные (н в корне). 2) Квашеная, плетёная, вяленая — отглагольные прилагательные без примет. 4) Решена, написаны — краткие причастия; некошеный — не- приметой не считается. 6) Вареники (варёный), ряженые (ряженый), торфяник (торфяной) — существительные от слов с одной н.<br>Не подходят: 3) — во всех словах две н (клюквенный: -енн-; желанный — исключение; купленный — сов. вид); 5) торжественно, нечаянно — две н, рьяно — одна; 7) соломенная (-енн-), лимонный (основа на н + -н-) — две н, названый (брат) — одна.'},
 {n:92,l:7,st:4,task:'(В формате ОГЭ/ЕГЭ, для 8–11 классов.) Прочитайте текст и выполните задания. 1) Укажите варианты ответов, в которых дано верное объяснение написания выделенного слова. 2) Из предложения 4 выпишите слово, которое легко принять за причастие с суффиксом -нн-, хотя в нём другой суффикс. 3) Из предложения 5 выпишите прилагательное, образованное от существительного с помощью суффикса -енн-. 4) Из предложения 5 выпишите краткие прилагательные и объясните, почему в них одна н.',
  body:'(1) Графиня стала раздеваться перед зеркалом. (2) Откололи с неё чепец, украшенный розами; сняли напудренный парик с её седой и плотно остриженной головы. (3) Булавки дождём сыпались около неё. (4) Жёлтое платье, шитое серебром, упало к её распухлым ногам. (5) Германн был свидетелем отвратительных таинств её туалета; наконец графиня осталась в спальной кофте и ночном чепце: в этом наряде, более свойственном её старости, она казалась менее ужасна и безобразна. (А. С. Пушкин, «Пиковая дама») Варианты к заданию 1: 1) УКРАШЕННЫЙ (розами) — в полном страдательном причастии с зависимым словом пишется НН. 2) НАПУДРЕННЫЙ — в прилагательном, образованном от существительного с помощью суффикса -ЕНН-, пишется НН. 3) СВОЙСТВЕННОМ — в прилагательном, образованном от существительного с помощью суффикса -ЕНН-, пишется НН. 4) ОСТРИЖЕННОЙ — в отглагольном прилагательном без приставки пишется НН. 5) УЖАСНА — в кратком прилагательном пишется столько же Н, сколько в полной форме. Пояснения: таинства туалета — здесь: долгое переодевание; распухлые — распухшие.',
  key:'1) Ответ: 1, 3, 5. Вариант 2 неверен: напудренный — причастие от напудрить, НН из-за приставки на-, а не суффикса -енн- отымённого прилагательного. Вариант 4 неверен: в слове остриженной есть приставка о- и зависимое слово «плотно» — это причастие.<br>2) Шитое: суффикс -т- (шить — шитый), н здесь нет.<br>3) Свойственном (свойство → свойственный).<br>4) Ужасна, безобразна: полные формы ужасный, безобразный — суффикс -н- после основы, которая не оканчивается на н (ужас-, безобраз-), поэтому одна н и в полной, и в краткой форме.'},
 {n:89,l:7,st:5,os:'работа с текстом',task:'Прочитать отрывок. 1) Переписать, вставляя пропущенные буквы. 2) Выписать все слова с пропусками и распределить их по правилам: прилагательные от существительных (суффикс -ян-, слово-исключение, н в корне, суффикс -н- после основы не на н); причастия; краткие формы. 3) Объяснить, почему в словах «ледя..ые» и «серебря..ые» одна н, а в слове «оловя..ая» две. 4) Почему в слове «тёмно-зелё..ой» одна н, хотя это сложное слово? 5) Найти причастные обороты, выписать их вместе с определяемыми словами и объяснить запятые. 6) Определить, какой формой являются слова «ненуже..» и «ненуж..о», и объяснить их написание. 7) Разобрать по составу слова «настоя..ой» и «прониза..ых».',
  body:'День был светлый; в два окна, сквозь ледя..ые стёкла, смотрели косые лучи зимнего солнца; на столе, убра..ом к обеду, тускло блестела оловя..ая посуда, графин с рыжим квасом и другой с тёмно-зелё..ой дедовой водкой, настоя..ой на буквице и зверобое. В проталины окон был виден ослепительно сверкающий снег на крышах, искрились серебря..ые чепчики на столбах забора и скворешне. На косяках окон, в клетках, прониза..ых солнцем, играли мои птицы: щебетали весёлые, руч..ые чижи, скрипели снегири, заливался щегол. Но весёлый, серебря..ый и звонкий этот день не радовал, был ненуже.., и всё было ненуж..о. (М. Горький, «Детство») Пояснения: буквица, зверобой — лекарственные травы; проталина — оттаявшее место на замёрзшем стекле; серебряные чепчики — здесь: снежные шапки; чиж, снегирь, щегол — певчие птицы.',
  key:'1)–2) Прилагательные от существительных: ледяные (суффикс -ян-), серебряные, серебряный (-ян-), оловянная (исключение: две н), тёмно-зелёной (н в корне), ручные (рук- → руч- + суффикс -н-: одна н). Причастия: убранном (приставка у-, зависимое слово), настоянной (приставка, зависимые слова), пронизанных (приставка, зависимое слово) — две н. Краткие формы: ненужен, ненужно — краткие прилагательные (полная форма ненужный).<br>3) Ледяной, серебряный образованы с суффиксом -ян-: одна н. Оловянный — одно из трёх исключений (стеклянный, оловянный, деревянный): две н.<br>4) Вторая часть «зелёный» — непроизводное прилагательное: н входит в корень, суффикса -н- нет; в сложном слове написание не меняется.<br>5) (на столе) убранном к обеду; (водкой) настоянной на буквице и зверобое; (в клетках) пронизанных солнцем — все обороты стоят после определяемого слова и выделяются запятыми.<br>6) Ненужен, ненужно — краткие прилагательные (сказуемые: день был ненужен, всё было ненужно); в полной форме ненужный суффикс -н- после корня нуж-, одна н — и в краткой форме одна н.<br>7) На-сто-я-нн-ой: приставка на-, корень сто-, суффиксы -я-, -нн-, окончание -ой. Про-низ-а-нн-ых: приставка про-, корень низ-, суффиксы -а-, -нн-, окончание -ых.'},
 {n:39,l:7,st:5,os:'диктант',task:'Диктант. Учитель (или родитель) читает текст, ученик записывает его. Знаки препинания, которые ещё не изучались (точка с запятой, тире на месте пропущенного слова), учитель называет при чтении. После диктанта подчеркнуть все слова, в которых пишется н или нн в суффиксе или на стыке корня и суффикса, и объяснить их написание; причастные обороты выделить. Текст для проверки — ниже.',
  body:'Германн вошёл в спальню. Перед кивотом, наполненным старинными образами, теплилась золотая лампада. Полинялые штофные кресла и диваны с пуховыми подушками, с сошедшей позолотою, стояли в печальной симметрии около стен, обитых китайскими обоями. На стене висели два портрета, писанные в Париже <…>. Один из них изображал мужчину лет сорока, румяного и полного, в светло-зелёном мундире и со звездою; другой — молодую красавицу с орлиным носом, с зачёсанными висками и с розою в пудреных волосах. По всем углам торчали фарфоровые пастушки, столовые часы <…>, коробочки, рулетки, веера и разные дамские игрушки, изобретённые в конце минувшего столетия <…>. Германн пошёл за ширмы. За ними стояла маленькая железная кровать. (А. С. Пушкин, «Пиковая дама») Пояснения: кивот (киот) — застеклённый шкафчик для икон; образа — иконы; лампада — светильник перед иконой; штофный — обитый плотной шёлковой тканью; со звездою — с орденом; ширмы — складная перегородка; текст немного сокращён.',
  key:'Две н: наполненным (приставка, зависимое слово — причастие), старинными (старина: основа на н + -н-), писанные (есть зависимое слово «в Париже» — причастие, хотя глагол писать несовершенного вида и приставки нет), зачёсанными (приставка за-), изобретённые (приставка, зависимые слова).<br>Одна н: штофные (штоф + -н-), румяного (н в корне), светло-зелёном (н в корне), орлиным (суффикс -ин-), пудреных (пудрить: без приставки и зависимых слов — отглагольное прилагательное), железная (железо + -н-), печальной (печаль + -н-).<br>Причастные обороты: (кивотом) наполненным старинными образами; (стен) обитых китайскими обоями; (портрета) писанные в Париже; (игрушки) изобретённые в конце минувшего столетия.'},
 {n:40,l:7,st:5,os:'сочинение',task:'Сочинение-миниатюра «Ярмарка» (8–10 предложений). Употребить не меньше двенадцати слов с н и нн на все случаи правила: прилагательные от существительных (в том числе одно слово-исключение); отглагольные прилагательные и причастия (в том числе причастие с зависимым словом); одно слово из урока 3 (сложное слово или устойчивое сочетание); краткие причастия и краткие прилагательные; наречия; существительные. Подчеркнуть эти слова и над каждым указать номер урока.',
  body:'Опорные слова (можно брать не все): расписные игрушки, плетёные корзины, домотканые половики, точёные ложки, печённые в золе картофелины, сушёные грибы, румяные калачи, копчёная рыба, стеклянные бусы, серебряные серьги; ряды украшены флагами, цены названы громко, торговцы приветливы и веселы, площадь многолюдна; торговали оживлённо, расхваливали товар неутомимо; Масленица, пряники, мороженое, путаница, родственники.',
  key:'Ответ свободный. Проверить: расписные — суффикса -н- нет на стыке с корнем «пис» (расписной), к правилу не относится; плетёные, точёные, сушёные, румяные, копчёная, серебряные — одна н; домотканые — сложное слово без приставки во второй части (урок 3): одна н; печённые (в золе) — причастие с зависимым словом: две н; стеклянные — исключение: две н; украшены, названы — краткие причастия: одна н; многолюдна — краткое прилагательное (многолюдный: одна н); оживлённо — наречие: две н; Масленица (с прописной: название праздника), пряники, мороженое — одна н; путаница — одна н; родственники — две н.'},
];  // n — постоянный номер упражнения: не менять и не переиспользовать (по нему задают домашку и хранят отметки)
const LNAMES=['','Прилагательные от существительных','Причастия и прилагательные от глаголов','Трудные случаи','Краткие формы','Наречия','Существительные','Повторение'];
